"use client";

import { Suspense, useEffect, useMemo, useState } from "react";
import { useSearchParams, useRouter } from "next/navigation";
import { useQueryClient } from "@tanstack/react-query";
import { Plus, LayoutGrid, List, Search, Star } from "lucide-react";
import SuggestedCirclesWidget from "@/components/circles/SuggestedCirclesWidget";
import CreateCircleModal, { type CreateCircleData } from "@/components/modals/CreateCircleModal";
import JoinCircleModal, { type JoinCircleData } from "@/components/modals/JoinCircleModal";
import CircleGridCard from "@/components/circles/CircleGridCard";
import CircleSearchAutocomplete from "@/components/circles/CircleSearchAutocomplete";
import CircleListRow from "@/components/circles/CircleListRow";
import ComparisonFloatingBar from "@/components/circles/ComparisonFloatingBar";
import CircleComparison from "@/components/circles/CircleComparison";
import { CircleComparisonProvider } from "@/contexts/CircleComparisonContext";
import { useCircleViewPreference } from "@/hooks/useCircleViewPreference";
import { useBookmarks } from "@/hooks/useBookmarks";
import { useCircleTags } from "@/hooks/useCircleTags";
import { useEmailVerification } from "@/hooks/useEmailVerification";
import { useToast } from "@/components/ui/Toast";
import { INVITE_REF_PARAM, markInviteStatus } from "@/lib/circleInvites";
import { CURRENT_WALLET, filterCirclesByQuery, type DiscoverCircle } from "@/data/circles";
import { getStoredCircles, saveStoredCircle, CIRCLE_RENEWAL_UPDATED_EVENT } from "@/lib/circleRenewal";
import { useCircles } from "@/lib/hooks/useCircles";
import { queryKeys } from "@/lib/queryKeys";
import { SavingsCardSkeletonGrid } from "@/components/skeleton/SavingsCardSkeleton";

// ---------------------------------------------------------------------------
// View toggle button
// ---------------------------------------------------------------------------
function ViewToggle({
  view,
  onChange,
}: {
  view: "grid" | "list";
  onChange: (v: "grid" | "list") => void;
}) {
  return (
    <div
      className="flex items-center rounded-lg border border-[var(--ov-14)] bg-[var(--ov-05)] p-0.5 gap-0.5"
      role="group"
      aria-label="Circle display view"
    >
      <button
        type="button"
        onClick={() => onChange("grid")}
        aria-pressed={view === "grid"}
        aria-label="Grid view"
        className={`flex items-center justify-center w-8 h-8 rounded-md transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76] ${
          view === "grid"
            ? "bg-[var(--ov-14)] text-[var(--text)]"
            : "text-[var(--muted)] hover:text-[var(--text)]"
        }`}
      >
        <LayoutGrid size={15} aria-hidden="true" />
      </button>
      <button
        type="button"
        onClick={() => onChange("list")}
        aria-pressed={view === "list"}
        aria-label="List view"
        className={`flex items-center justify-center w-8 h-8 rounded-md transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76] ${
          view === "list"
            ? "bg-[var(--ov-14)] text-[var(--text)]"
            : "text-[var(--muted)] hover:text-[var(--text)]"
        }`}
      >
        <List size={15} aria-hidden="true" />
      </button>
    </div>
  );
}

// ---------------------------------------------------------------------------
// List view column header row
// ---------------------------------------------------------------------------
function ListHeader() {
  return (
    <div
      className="hidden sm:grid items-center gap-x-4 px-4 py-2 rounded-lg bg-[var(--ov-05)] mb-1
        grid-cols-[28px_minmax(160px,2fr)_110px_100px_80px_100px_auto]"
      role="rowgroup"
      aria-label="Circle list column headers"
    >
      <span className="sr-only">Compare</span>
      <span className="text-[10px] font-semibold uppercase tracking-wider text-[var(--muted)]">
        Circle
      </span>
      <span className="text-[10px] font-semibold uppercase tracking-wider text-[var(--muted)]">
        Contribution
      </span>
      <span className="text-[10px] font-semibold uppercase tracking-wider text-[var(--muted)]">
        Members
      </span>
      <span className="text-[10px] font-semibold uppercase tracking-wider text-[var(--muted)]">
        Round
      </span>
      <span className="text-[10px] font-semibold uppercase tracking-wider text-[var(--muted)]">
        Next payout
      </span>
      <span className="sr-only">Action</span>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Empty state
// ---------------------------------------------------------------------------
function EmptyState({
  tab,
  hasQuery,
}: {
  tab: "my" | "discover" | "bookmarked";
  hasQuery: boolean;
}) {
  return (
    <div className="flex flex-col items-center justify-center py-24 text-center gap-3">
      {hasQuery ? (
        <>
          <Search size={32} className="text-[var(--muted)]" aria-hidden="true" />
          <p className="text-[var(--muted)] text-base">No circles match your search.</p>
        </>
      ) : tab === "bookmarked" ? (
        <>
          <Star size={32} className="text-[var(--muted)]" aria-hidden="true" />
          <p className="text-[var(--muted)] text-base">
            You haven&apos;t bookmarked any circles yet.
          </p>
        </>
      ) : (
        <p className="text-[var(--muted)] text-base">
          {tab === "my"
            ? "You haven't joined any circles yet."
            : "No open circles available to join right now."}
        </p>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Main content (inside Suspense for useSearchParams)
// ---------------------------------------------------------------------------
type Tab = "my" | "discover" | "bookmarked";

function CirclesContent() {
  const searchParams = useSearchParams();
  const router = useRouter();

  const tab: Tab = (searchParams.get("tab") as Tab) ?? "my";
  const inviteId = searchParams.get("invite");
  const inviteRef = searchParams.get(INVITE_REF_PARAM);
  const action = searchParams.get("action");

  const [createOpen, setCreateOpen] = useState(false);
  const [duplicateValues, setDuplicateValues] = useState<Partial<CreateCircleData> | undefined>();
  const queryClient = useQueryClient();
  // Circle list now comes from the typed API client (lib/api) via TanStack
  // Query instead of a direct `data/circles.ts` import.
  const { data: fetchedCircles, isLoading, isError } = useCircles();
  // Circles created locally or renewed from previous cycles
  const [localCircles, setLocalCircles] = useState<DiscoverCircle[]>(() => getStoredCircles());

  useEffect(() => {
    const sync = () => {
      setLocalCircles(getStoredCircles());
    };
    sync();
    window.addEventListener(CIRCLE_RENEWAL_UPDATED_EVENT, sync);
    return () => window.removeEventListener(CIRCLE_RENEWAL_UPDATED_EVENT, sync);
  }, []);

  const circles = useMemo(
    () => [...localCircles, ...(fetchedCircles ?? [])],
    [localCircles, fetchedCircles]
  );
  const [joinCircle, setJoinCircle] = useState<JoinCircleData | null>(null);
  const [query, setQuery] = useState("");

   const { view, setView } = useCircleViewPreference();
   const { bookmarkedIds } = useBookmarks();
   const { tags, assignedIds } = useCircleTags();
   const [tagFilter, setTagFilter] = useState("");
  const { isVerified } = useEmailVerification();
  const { showToast } = useToast();

  function requireVerified(): boolean {
    if (isVerified) return true;
    showToast({
      title: "Verify your email to continue",
      message: "Creating and joining circles requires a verified email address.",
      variant: "warning",
    });
    return false;
  }

  function requestJoinCircle(circle: JoinCircleData) {
    if (!requireVerified()) return;
    setJoinCircle(circle);
  }

   // Arriving from an email/SMS invite counts as the invite being opened.
   useEffect(() => {
     if (inviteRef) markInviteStatus(inviteRef, "opened");
   }, [inviteRef]);

   // Handle invite / create deep-link params
   useEffect(() => {
     if (!inviteId) return;
     const circle = circles.find((c) => c.id === inviteId);
    if (circle) setJoinCircle(circle);
    if (circle) requestJoinCircle(circle);
   }, [circles, inviteId]);

   useEffect(() => {
    if (action === "create") {
      if (requireVerified()) setCreateOpen(true);
      router.replace("/dashboard/circles");
    }
   }, [action, router]);

   function openCreateCircle() {
    if (!requireVerified()) return;
     setDuplicateValues(undefined);
     setCreateOpen(true);
   }

function duplicateCircle(circle: DiscoverCircle) {
     if (!requireVerified()) return;
      const contribution = circle.contribution.replace(/[^\d.]/g, "");
      const roundDuration = circle.duration.replace(/[^\d.]/g, "");
      setDuplicateValues({
        name: `${circle.name} (Copy)`,
        description: circle.description ?? "",
        contribution,
        maxMembers: String(circle.totalSlots),
        roundDuration,
        category: circle.category ?? "family",
        isPrivate: circle.isPrivate ?? false,
        penaltyEnabled: circle.penaltyEnabled ?? false,
        penaltyType: circle.penaltyType ?? "percentage",
        penaltyValue: circle.penaltyValue ?? "",
        reserveEnabled: circle.reserveEnabled ?? false,
        reservePercentage: circle.reservePercentage ? String(circle.reservePercentage) : "",
      });
      setCreateOpen(true);
    }

  function handleCreateCircle(data: CreateCircleData) {
    const newCircle = {
      id: typeof crypto !== "undefined" && crypto.randomUUID ? crypto.randomUUID() : `circle-${Date.now()}`,
      name: data.name,
      creator: CURRENT_WALLET,
      members: [CURRENT_WALLET],
      totalSlots: Number(data.maxMembers),
      contribution: `${data.contribution} USDT`,
      duration: `${data.roundDuration} Days`,
      description: data.description,
      category: data.category,
      isPrivate: data.isPrivate,
      penaltyEnabled: data.penaltyEnabled,
      penaltyType: data.penaltyType,
      penaltyValue: data.penaltyValue,
      reserveEnabled: data.reserveEnabled,
      reservePercentage: data.reserveEnabled ? Number(data.reservePercentage) : 0,
      reserveBalance: 0,
    };
    saveStoredCircle(newCircle as any);
    setLocalCircles((current) => [newCircle, ...current.filter((c) => c.id !== newCircle.id)]);
    setDuplicateValues(undefined);
    // No real "create circle" endpoint yet; invalidating keeps the list in
    // sync with the server once one exists, same as the join-circle flow.
    queryClient.invalidateQueries({ queryKey: queryKeys.circles.all() });
  }

  const setTab = (t: Tab) => {
    setQuery(""); // clear search when switching tabs
    router.push(`/dashboard/circles?tab=${t}`);
  };

  // Derive filtered list — memo keeps it cheap on re-render
  const baseCircles = useMemo<DiscoverCircle[]>(() => {
    if (tab === "my") return circles.filter((c) => c.members.includes(CURRENT_WALLET));
    if (tab === "bookmarked") return circles.filter((c) => bookmarkedIds.includes(c.id));
    return circles.filter((c) => !c.members.includes(CURRENT_WALLET));
  }, [circles, tab, bookmarkedIds]);

  const displayCircles = useMemo(
    () => filterCirclesByQuery(baseCircles, query).filter((circle) => !tagFilter || assignedIds(circle.id).includes(tagFilter)),
    [assignedIds, baseCircles, query, tagFilter]
  );

  const isDiscover = tab === "discover";
  const isBookmarked = tab === "bookmarked";

  return (
    <>
      <div className="space-y-6 pb-20 md:pb-0">
        {/* ---- Page title row ---- */}
        <div className="flex items-center gap-4">
          <h1 className="text-2xl font-bold font-sora text-[var(--text)] shrink-0">
            Circles
          </h1>
          <div className="h-px bg-[var(--ov-1a)] w-full" aria-hidden="true" />
          <button
            onClick={openCreateCircle}
            className="flex items-center gap-2 shrink-0 px-4 py-2 bg-[#4B6B76] hover:bg-[#3D5A64] text-white text-sm font-medium rounded-lg transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76]"
          >
            <Plus size={16} aria-hidden="true" />
            Create Circle
          </button>
        </div>

        {/* ---- Tabs + search + view toggle ---- */}
        <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          {/* Tabs */}
          <div
            className="flex border-b border-[var(--ov-1a)] sm:border-b-0"
            role="tablist"
            aria-label="Circle views"
          >
            <button
              role="tab"
              aria-selected={tab === "my"}
              aria-controls="circles-panel"
              onClick={() => setTab("my")}
              className={`px-5 py-2.5 text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76] focus-visible:ring-inset -mb-px sm:mb-0 sm:rounded-lg ${
                tab === "my"
                  ? "text-[var(--text)] border-b-2 border-white sm:border-0 sm:bg-[var(--ov-0a)]"
                  : "text-[var(--muted)] hover:text-[var(--text)] border-b-2 border-transparent sm:border-0 sm:hover:bg-[var(--ov-07)]"
              }`}
            >
              My Circles
              <span
                className="ml-2 text-xs text-[var(--muted)] tabular-nums"
                aria-label={`${circles.filter((c) => c.members.includes(CURRENT_WALLET)).length} circles`}
              >
                {circles.filter((c) => c.members.includes(CURRENT_WALLET)).length}
              </span>
            </button>
            <button
              role="tab"
              aria-selected={tab === "discover"}
              aria-controls="circles-panel"
              onClick={() => setTab("discover")}
              className={`px-5 py-2.5 text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76] focus-visible:ring-inset -mb-px sm:mb-0 sm:rounded-lg ${
                tab === "discover"
                  ? "text-[var(--text)] border-b-2 border-white sm:border-0 sm:bg-[var(--ov-0a)]"
                  : "text-[var(--muted)] hover:text-[var(--text)] border-b-2 border-transparent sm:border-0 sm:hover:bg-[var(--ov-07)]"
              }`}
            >
              Discover
              <span
                className="ml-2 text-xs text-[var(--muted)] tabular-nums"
                aria-label={`${circles.filter((c) => !c.members.includes(CURRENT_WALLET)).length} circles`}
              >
                {circles.filter((c) => !c.members.includes(CURRENT_WALLET)).length}
              </span>
            </button>
            <button
              role="tab"
              aria-selected={tab === "bookmarked"}
              aria-controls="circles-panel"
              onClick={() => setTab("bookmarked")}
              className={`flex items-center px-5 py-2.5 text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76] focus-visible:ring-inset -mb-px sm:mb-0 sm:rounded-lg ${
                tab === "bookmarked"
                  ? "text-[var(--text)] border-b-2 border-white sm:border-0 sm:bg-[var(--ov-0a)]"
                  : "text-[var(--muted)] hover:text-[var(--text)] border-b-2 border-transparent sm:border-0 sm:hover:bg-[var(--ov-07)]"
              }`}
            >
              <Star size={13} aria-hidden="true" className="mr-1.5" />
              Bookmarked
              <span
                className="ml-2 text-xs text-[var(--muted)] tabular-nums"
                aria-label={`${circles.filter((c) => bookmarkedIds.includes(c.id)).length} circles`}
              >
                {circles.filter((c) => bookmarkedIds.includes(c.id)).length}
              </span>
            </button>
          </div>

          {/* Search + view toggle */}
          <div className="flex items-center gap-2">
            {/* Search input */}
            <CircleSearchAutocomplete
              key={tab}
              circles={baseCircles}
              onQueryChange={setQuery}
              className="flex-1 sm:flex-none sm:w-52"
            />

            {tags.length > 0 && (
              <select aria-label="Filter by tag" value={tagFilter} onChange={(event) => setTagFilter(event.target.value)} className="h-9 rounded-lg border border-[var(--ov-14)] bg-[var(--content)] px-2 text-xs text-[var(--text)]">
                <option value="">All tags</option>
                {tags.map((tag) => <option key={tag.id} value={tag.id}>{tag.name}</option>)}
              </select>
            )}

            {/* View toggle */}
            <ViewToggle view={view} onChange={setView} />
          </div>
        </div>

        {/* ---- Results count (when filtering) ---- */}
        {query && (
          <p className="text-xs text-[var(--muted)]" role="status" aria-live="polite">
            {displayCircles.length === 0
              ? "No results"
              : `${displayCircles.length} result${displayCircles.length !== 1 ? "s" : ""} for "${query}"`}
          </p>
        )}

        {/* ---- Personalized picks (Discover tab only) ---- */}
        {isDiscover && !query && (
          <SuggestedCirclesWidget circles={circles} wallet={CURRENT_WALLET} onJoin={requestJoinCircle} />
        )}

        {/* ---- Panel ---- */}
        <div id="circles-panel" role="tabpanel">
          {isLoading ? (
            <SavingsCardSkeletonGrid count={6} />
          ) : isError ? (
            <div className="flex flex-col items-center justify-center py-24 text-center gap-2" role="alert">
              <p className="text-[var(--muted)] text-base">
                Couldn&apos;t load circles right now. Please try again.
              </p>
              <button
                type="button"
                onClick={() => queryClient.invalidateQueries({ queryKey: queryKeys.circles.all() })}
                className="text-sm font-medium text-[#4B6B76] underline"
              >
                Retry
              </button>
            </div>
          ) : displayCircles.length === 0 ? (
            <EmptyState tab={tab} hasQuery={query.length > 0} />
          ) : view === "grid" ? (
            /* Grid view */
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5">
              {displayCircles.map((circle) => (
                <CircleGridCard
                  key={circle.id}
                  circle={circle}
                  showJoin={isDiscover || (isBookmarked && !circle.members.includes(CURRENT_WALLET))}
                 onJoin={requestJoinCircle}
                  onDuplicate={tab === "my" && circle.creator.toLowerCase() === CURRENT_WALLET.toLowerCase() ? duplicateCircle : undefined}
                />
              ))}
            </div>
          ) : (
            /* List view */
            <div
              className="flex flex-col gap-0.5"
              role="table"
              aria-label={tab === "my" ? "My circles" : tab === "discover" ? "Discover circles" : "Bookmarked circles"}
            >
              <ListHeader />
              {displayCircles.map((circle, i) => (
                <CircleListRow
                  key={circle.id}
                  circle={circle}
                  showJoin={isDiscover || (isBookmarked && !circle.members.includes(CURRENT_WALLET))}
                  onJoin={setJoinCircle}
                  onDuplicate={tab === "my" && circle.creator.toLowerCase() === CURRENT_WALLET.toLowerCase() ? duplicateCircle : undefined}
                  even={i % 2 === 1}
                />
              ))}
            </div>
          )}
        </div>
      </div>

      <CreateCircleModal
        open={createOpen}
        onClose={() => {
          setCreateOpen(false);
          setDuplicateValues(undefined);
        }}
        initialValues={duplicateValues}
        onCreate={handleCreateCircle}
      />
      <JoinCircleModal
        open={joinCircle !== null}
        onClose={() => {
          setJoinCircle(null);
          if (inviteId) router.replace("/dashboard/circles");
        }}
        circle={joinCircle}
        currentWallet={CURRENT_WALLET}
        onJoined={() => {
          if (inviteRef) markInviteStatus(inviteRef, "joined");
          // Membership changed server-side (in a real backend) — refetch.
          queryClient.invalidateQueries({ queryKey: queryKeys.circles.all() });
        }}
      />
      <ComparisonFloatingBar allCircles={circles} />
      <CircleComparison
        allCircles={circles}
        onJoinCircle={(circle) => requestJoinCircle(circle)}
      />
    </>
  );
}

export default function CirclesPage() {
  return (
    <Suspense>
      <CircleComparisonProvider>
        <CirclesContent />
      </CircleComparisonProvider>
    </Suspense>
  );
}

"use client";

import { useState, useRef, useCallback } from "react";
import { ChevronDown } from "lucide-react";
import { MOCK_LOCKED_FUNDS } from "@/data/lockedFunds";

const TOKENS = ["USDT", "USDC", "STRK", "XLM"];



export default function LockedFundsPage() {
  const [tokenOpen, setTokenOpen] = useState(false);
  const [selectedToken, setSelectedToken] = useState("USDT");
  const [focusedIndex, setFocusedIndex] = useState<number>(-1);
  const listRef = useRef<HTMLUListElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);

  const openDropdown = () => {
    setTokenOpen(true);
    setFocusedIndex(TOKENS.indexOf(selectedToken));
  };

  const closeDropdown = useCallback(() => {
    setTokenOpen(false);
    setFocusedIndex(-1);
    triggerRef.current?.focus();
  }, []);

  const selectToken = (token: string) => {
    setSelectedToken(token);
    closeDropdown();
  };

  const handleTriggerKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "ArrowDown" || e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      openDropdown();
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      openDropdown();
    }
  };

  const handleListKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Escape") {
      e.preventDefault();
      closeDropdown();
      return;
    }
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setFocusedIndex((i) => (i + 1) % TOKENS.length);
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setFocusedIndex((i) => (i - 1 + TOKENS.length) % TOKENS.length);
    } else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      if (focusedIndex >= 0) selectToken(TOKENS[focusedIndex]);
    } else if (e.key === "Tab") {
      closeDropdown();
    }
  };

  return (
    <div className="space-y-8 pb-20 md:pb-0">
      {/* Page Title */}
      <div className="flex items-center gap-4">
        <h1 className="text-2xl font-bold font-sora text-[var(--text)] shrink-0">My Locked Funds</h1>
        <div className="h-px bg-[var(--ov-1a)] w-full" aria-hidden="true" />
      </div>

      {/* Action Bar */}
      <div className="flex items-center gap-3">
        <button className="px-5 py-2 bg-[var(--elevated)] hover:bg-[var(--elevated-hover)] text-[var(--text)] text-sm font-medium rounded-lg transition-colors border border-[var(--ov-1a)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76]">
          Commit
        </button>

        {/* Token Dropdown */}
        <div className="relative">
          <button
            ref={triggerRef}
            type="button"
            onClick={() => (tokenOpen ? closeDropdown() : openDropdown())}
            onKeyDown={handleTriggerKeyDown}
            className="flex items-center gap-2 px-4 py-2 bg-[var(--elevated)] hover:bg-[var(--elevated-hover)] text-[var(--text)] text-sm font-medium rounded-lg border border-[var(--ov-1a)] transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76]"
            aria-haspopup="listbox"
            aria-expanded={tokenOpen}
            aria-label={`Select token, currently ${selectedToken}`}
          >
            {selectedToken}
            <ChevronDown
              size={16}
              className={`transition-transform ${tokenOpen ? "rotate-180" : ""}`}
              aria-hidden="true"
            />
          </button>

          {tokenOpen && (
            <ul
              ref={listRef}
              role="listbox"
              aria-label="Select token"
              onKeyDown={handleListKeyDown}
              tabIndex={-1}
              className="absolute top-full mt-1 left-0 bg-[var(--modal)] border border-[var(--ov-1a)] rounded-lg overflow-hidden z-10 min-w-full outline-none"
            >
              {TOKENS.map((t, idx) => (
                <li key={t} role="option" aria-selected={selectedToken === t}>
                  <button
                    type="button"
                    onClick={() => selectToken(t)}
                    data-index={idx}
                    className={`w-full text-left px-4 py-2 text-sm transition-colors focus-visible:outline-none focus-visible:bg-[var(--ov-1a)] ${
                      focusedIndex === idx ? "bg-[var(--ov-1a)]" : "hover:bg-[var(--ov-0f)]"
                    } ${selectedToken === t ? "text-[var(--text)] font-semibold" : "text-[var(--muted)]"}`}
                    tabIndex={tokenOpen ? 0 : -1}
                    autoFocus={focusedIndex === idx}
                  >
                    {t}
                  </button>
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>

      {/* Locked Funds Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5">
        {MOCK_LOCKED_FUNDS.map((fund) => (
          <article
            key={fund.name}
            className="bg-[var(--content)] rounded-2xl p-6 flex flex-col gap-4 hover:bg-[var(--content-hover)] transition-colors"
          >
            <p className="text-[var(--muted)] text-sm font-medium">{fund.name}</p>
            <h2 className="text-3xl font-bold font-sora text-[var(--text)] tracking-tight">
              {fund.amount} {fund.token}
            </h2>
            <p className="text-[var(--muted)] text-sm">Locked until: {fund.lockedUntil}</p>
            <button className="mt-auto px-5 py-2.5 bg-[#4B6B76] hover:bg-[#3D5A64] text-white text-sm font-medium rounded-lg transition-colors w-fit focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--content)]">
              View Details
            </button>
          </article>
        ))}
      </div>
    </div>
  );
}

"use client";

import { useState, useCallback, useEffect, useMemo } from "react";
import { useUndoableRemoval } from "@/hooks/useUndoableRemoval";
import Link from "next/link";
import {
  Bell,
  ChevronDown,
  ChevronUp,
  CheckCircle2,
  DollarSign,
  AlertCircle,
  Clock,
  Trash2,
  MailOpen,
  UserPlus,
  UserMinus,
  Megaphone,
  Repeat,
  Send,
  PauseCircle,
  PlayCircle,
  AlarmClock,
} from "lucide-react";
import type { Notification, NotificationType, NotificationCategory } from "@/types/notification";
import { NOTIFICATION_CATEGORIES } from "@/types/notification";
import { MOCK_NOTIFICATIONS } from "@/data/notifications";
import RelativeTime from "@/components/ui/RelativeTime";
import { useLoadMore } from "@/hooks/useLoadMore";
import {
  getActiveNotificationSnoozes,
  getExpiredNotificationIds,
  NOTIFICATION_SNOOZE_OPTIONS,
  NOTIFICATIONS_EVENT,
  restoreNotification,
  snoozeNotification,
} from "@/lib/notifications";

const TYPE_CONFIG: Record<
  NotificationType,
  { icon: React.ComponentType<{ size?: number; className?: string }>; color: string }
> = {
  round_complete: { icon: CheckCircle2, color: "text-[var(--success)]" },
  payout_ready: { icon: DollarSign, color: "text-[#FBBF24]" },
  missed_contribution: { icon: AlertCircle, color: "text-[#FF5B5B]" },
  your_turn: { icon: Clock, color: "text-[#4B6B76]" },
  join_request: { icon: UserPlus, color: "text-[#4B6B76]" },
  member_left: { icon: UserMinus, color: "text-[#FF5B5B]" },
  announcement: { icon: Megaphone, color: "text-[#4B6B76]" },
  seat_transfer: { icon: Repeat, color: "text-[#4B6B76]" },
  circle_invite: { icon: Send, color: "text-[#4B6B76]" },
  circle_paused: { icon: PauseCircle, color: "text-[#FBBF24]" },
  circle_resumed: { icon: PlayCircle, color: "text-[var(--success)]" },
};


function getFilterLabel(filter: NotificationCategory): string {
  const labels: Record<NotificationCategory, string> = {
    all: "All Notifications",
    payouts: "Payouts",
    contributions: "Contributions",
    system: "System",
    snoozed: "Snoozed",
  };
  return labels[filter];
}

export default function NotificationsPage() {
  const [notifications, setNotifications] = useState<Notification[]>(MOCK_NOTIFICATIONS);
  const [selectedFilter, setSelectedFilter] = useState<NotificationCategory>("all");
  const [snoozedUntil, setSnoozedUntil] = useState<Record<string, number>>({});

  useEffect(() => {
    const stored = JSON.parse(localStorage.getItem("ahjoorxmr:notifications") ?? "[]") as Array<Omit<Notification, "timestamp"> & { timestamp: string }>;
    if (stored.length > 0) {
      // Notifications are persisted client-side until the API is available.
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setNotifications((current) => [...stored.map((notification) => ({ ...notification, timestamp: new Date(notification.timestamp) })), ...current]);
    }
    try {
      setGroupingEnabled(localStorage.getItem(NOTIFICATION_GROUPING_STORAGE_KEY) !== "false");
    } catch {
      // Keep grouping enabled when preferences cannot be read.
    }
  }, []);

  useEffect(() => {
    const syncSnoozes = (event?: Event) => {
      const { snoozedUntil: activeSnoozes, expiredIds } = getActiveNotificationSnoozes();
      const returnedIds = event ? getExpiredNotificationIds(event) : [];
      setSnoozedUntil(activeSnoozes);
      const unreadIds = new Set([...expiredIds, ...returnedIds]);
      if (unreadIds.size > 0) {
        setNotifications((current) =>
          current.map((notification) =>
            unreadIds.has(notification.id) ? { ...notification, read: false } : notification
          )
        );
      }
    };
    const handleChange = (event: Event) => syncSnoozes(event);
    syncSnoozes();
    const interval = setInterval(() => syncSnoozes(), 30 * 1000);
    window.addEventListener(NOTIFICATIONS_EVENT, handleChange);
    window.addEventListener("storage", handleChange);
    return () => {
      clearInterval(interval);
      window.removeEventListener(NOTIFICATIONS_EVENT, handleChange);
      window.removeEventListener("storage", handleChange);
    };
  }, []);

  // #245: dismissing a notification is destructive (there's no "view
  // deleted notifications" anywhere), so it goes through the shared
  // undo-toast flow instead of filtering `notifications` directly —
  // `pendingIds` hides it from view immediately, but the real removal
  // from `notifications` only happens if the 5s undo window closes.
  const { remove: removeWithUndo, isPending } = useUndoableRemoval<string>();

  const snoozedIds = useMemo(() => new Set(Object.keys(snoozedUntil)), [snoozedUntil]);
  const unreadCount = useMemo(
    () => notifications.filter((n) => !n.read && !snoozedIds.has(n.id)).length,
    [notifications, snoozedIds]
  );

  // Filter notifications based on selected category
  const filteredNotifications = useMemo(() => {
    if (selectedFilter === "snoozed") {
      return notifications.filter((n) => snoozedIds.has(n.id) && !isPending(n.id));
    }
    const types = NOTIFICATION_CATEGORIES[selectedFilter];
    return notifications.filter((n) => types.includes(n.type) && !snoozedIds.has(n.id) && !isPending(n.id));
  }, [notifications, selectedFilter, isPending, snoozedIds]);

  // Sort by date descending (newest first)
  const sortedNotifications = useMemo(
    () => [...filteredNotifications].sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime()),
    [filteredNotifications]
  );

  const { visibleCount, hasMore, loadMore, sentinelRef, announcement } = useLoadMore(
    notificationGroups.length,
    `dashboard:notifications:${selectedFilter}`
  );
  const visibleGroups = notificationGroups.slice(0, visibleCount);

  const markAllRead = useCallback(() => {
    setNotifications((prev) => prev.map((n) => ({ ...n, read: true })));
  }, []);

  const markGroupAsRead = useCallback((ids: string[]) => {
    setNotifications((prev) =>
      prev.map((notification) =>
        ids.includes(notification.id) ? { ...notification, read: true } : notification
      )
    );
  }, []);

  const deleteNotification = useCallback(
    (group: ReturnType<typeof selectNotificationGroups>[number]) => {
      const ids = new Set(group.notifications.map((notification) => notification.id));
      removeWithUndo(group.id, {
        title: group.count === 1 ? "Notification dismissed" : "Notification group dismissed",
        message: group.count === 1 ? group.latest.title : `${group.count} notifications dismissed`,
        commit: () => setNotifications((prev) => prev.filter((notification) => !ids.has(notification.id))),
      });
    },
    [removeWithUndo],
  );

  const handleSnooze = (notificationId: string, value: string) => {
    const option = NOTIFICATION_SNOOZE_OPTIONS.find((candidate) => candidate.label === value);
    if (option) snoozeNotification(notificationId, option.ms);
  };

  const handleRestore = (notificationId: string) => restoreNotification(notificationId);

  const handleFilterChange = (filter: NotificationCategory) => {
    setSelectedFilter(filter);
  };

  if (notifications.length === 0) {
    return (
      <div className="space-y-8 pb-20 md:pb-0">
        <div className="flex items-center mb-6">
          <h1 className="text-3xl font-bold font-sora text-[var(--text)] shrink-0">Notifications</h1>
          <div className="ml-4 h-px bg-[var(--ov-1a)] w-full" aria-hidden="true" />
        </div>

        {/* Empty State */}
        <div className="bg-[var(--content)] p-12 rounded-3xl flex flex-col items-center justify-center min-h-[500px] text-center">
          <div className="w-20 h-20 rounded-full bg-[var(--ov-0a)] flex items-center justify-center mb-6">
            <Bell size={40} className="text-[var(--muted)]" aria-hidden="true" />
          </div>
          <h2 className="text-2xl font-bold font-sora text-[var(--text)] mb-3">
            All caught up
          </h2>
          <p className="text-[var(--muted)] mb-8 max-w-md">
            No notifications yet. You&apos;ll be notified about important circle events, payouts, and your turns.
          </p>
          <Link
            href="/dashboard"
            className="inline-flex items-center gap-2 px-6 py-3 bg-white text-black rounded-lg font-medium hover:bg-gray-100 transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76]"
          >
            Back to Dashboard
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-8 pb-20 md:pb-0">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-2">
          <h1 className="text-3xl font-bold font-sora text-[var(--text)]">Notifications</h1>
          <div className="h-px bg-[var(--ov-1a)] w-40" aria-hidden="true" />
        </div>
        {unreadCount > 0 && (
          <button
            onClick={markAllRead}
            className="inline-flex items-center gap-2 px-4 py-2 text-sm font-medium text-[#4B6B76] bg-[var(--ov-0a)] hover:bg-[var(--ov-1a)] rounded-lg transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76]"
          >
            <MailOpen size={16} aria-hidden="true" />
            Mark all as read
          </button>
        )}
      </div>

      {/* Filter Tabs */}
      <div className="flex gap-2 overflow-x-auto pb-2">
        {(["all", "payouts", "contributions", "system", "snoozed"] as const).map((filter) => (
          <button
            key={filter}
            onClick={() => handleFilterChange(filter)}
            className={`px-4 py-2 rounded-lg font-medium text-sm whitespace-nowrap transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76] ${
              selectedFilter === filter
                ? "bg-white text-black"
                : "bg-[var(--ov-0a)] text-[var(--muted)] hover:text-[var(--text)]"
            }`}
          >
            {getFilterLabel(filter)}
          </button>
        ))}
      </div>

      {/* Results Summary */}
      <div className="flex items-center justify-between">
        <p className="text-sm text-[var(--muted)]">
          Showing {visibleGroups.length} of{" "}
          {notificationGroups.length} notification group{notificationGroups.length !== 1 ? "s" : ""}
        </p>
        {unreadCount > 0 && (
          <span className="inline-flex items-center gap-2 px-3 py-1 bg-[var(--ov-0a)] rounded-lg text-sm font-medium text-[var(--muted)]">
            <span className="w-2 h-2 rounded-full bg-[#4B6B76]" />
            {unreadCount} unread
          </span>
        )}
      </div>

      {/* Notifications List */}
      <div className="space-y-2 bg-[var(--content)] rounded-3xl overflow-hidden">
        {visibleGroups.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-12">
            <Bell size={32} className="text-[var(--muted)] mb-3" aria-hidden="true" />
            <p className="text-[var(--muted)]">No notifications in this category</p>
          </div>
        ) : (
          visibleGroups.map((group) => {
            const notification = group.latest;
            const { icon: Icon, color } = TYPE_CONFIG[notification.type];
            const expanded = expandedGroups.has(group.id);
            const memberIds = group.notifications.map((member) => member.id);
            return (
              <div
                key={group.id}
                className={`border-b border-[var(--ov-0f)] last:border-b-0 ${
                  !group.read ? "bg-[var(--ov-03)]" : ""
                }`}
              >
                <div className="flex items-start gap-4 p-4 md:p-5 hover:bg-[var(--modal)] transition-colors">
                  <div
                    className={`w-10 h-10 rounded-lg bg-[var(--ov-0a)] flex items-center justify-center shrink-0 mt-0.5 ${color}`}
                  >
                    <Icon size={18} aria-hidden="true" />
                  </div>

                  <Link
                    href={notification.href}
                    onClick={() => markGroupAsRead(memberIds)}
                    className="flex-1 min-w-0 group focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76] rounded"
                  >
                    <div className="flex items-start justify-between gap-3 mb-1">
                      <p className="text-sm font-semibold text-[var(--text)] group-hover:text-[#4B6B76] transition-colors">
                        {notification.title}
                      </p>
                      {!group.read && (
                        <span
                          className="w-2.5 h-2.5 rounded-full bg-[#4B6B76] shrink-0 mt-1"
                          aria-label="Unread"
                        />
                      )}
                    </div>
                    <p className="text-xs text-[var(--muted)] line-clamp-2 mb-2">
                      {notification.description}
                    </p>
                    <p className="text-xs text-[var(--faint)]">
                      <RelativeTime date={notification.timestamp} className="text-[var(--faint)]" />
                    </p>
                  </Link>

                  <div className="flex items-center gap-1 shrink-0">
                    {group.count > 1 && (
                      <>
                        <span
                          aria-label={`${group.count} notifications`}
                          className="rounded-full bg-[var(--ov-0a)] px-2 py-1 text-xs font-medium text-[var(--muted)]"
                        >
                          {group.count}
                        </span>
                        <button
                          type="button"
                          onClick={() => toggleGroup(group.id)}
                          aria-expanded={expanded}
                          aria-label={`${expanded ? "Collapse" : "Expand"} ${group.count} notifications`}
                          className="p-2 rounded-lg text-[var(--muted)] hover:text-[var(--text)] hover:bg-[var(--ov-0a)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76]"
                        >
                          {expanded ? <ChevronUp size={16} aria-hidden="true" /> : <ChevronDown size={16} aria-hidden="true" />}
                        </button>
                      </>
                    )}
                    <button
                      onClick={() => deleteNotification(group)}
                      className="p-2 rounded-lg text-[var(--muted)] hover:text-[#FF5B5B] hover:bg-[var(--ov-0a)] transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#FF5B5B]"
                      aria-label={group.count === 1
                        ? `Delete notification: ${notification.title}`
                        : `Delete all ${group.count} notifications`}
                    >
                      <Trash2 size={16} aria-hidden="true" />
                    </button>
                  </div>
                  <p className="text-xs text-[var(--muted)] line-clamp-2 mb-2">
                    {notification.description}
                  </p>
                  <p className="text-xs text-[var(--faint)]">
                    <RelativeTime date={notification.timestamp} className="text-[var(--faint)]" />
                  </p>
                </Link>

                <div className="flex shrink-0 items-center gap-1">
                  {snoozedIds.has(notification.id) ? (
                    <button
                      onClick={() => handleRestore(notification.id)}
                      className="p-2 rounded-lg text-[var(--muted)] hover:text-[var(--text)] hover:bg-[var(--ov-0a)] transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76]"
                      aria-label={`Unsnooze notification: ${notification.title}`}
                    >
                      <AlarmClock size={16} aria-hidden="true" />
                    </button>
                  ) : (
                    <select
                      value=""
                      onChange={(event) => handleSnooze(notification.id, event.target.value)}
                      aria-label={`Snooze notification: ${notification.title}`}
                      className="cursor-pointer rounded-lg border border-[var(--ov-14)] bg-transparent px-2.5 py-1.5 text-xs text-[var(--muted)] hover:bg-[var(--ov-0a)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76]"
                    >
                      <option value="" disabled>
                        Snooze…
                      </option>
                      {NOTIFICATION_SNOOZE_OPTIONS.map((option) => (
                        <option key={option.label} value={option.label}>
                          {option.label}
                        </option>
                      ))}
                    </select>
                  )}
                  <button
                    onClick={() => deleteNotification(notification.id)}
                    className="p-2 rounded-lg text-[var(--muted)] hover:text-[#FF5B5B] hover:bg-[var(--ov-0a)] transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#FF5B5B]"
                    aria-label={`Delete notification: ${notification.title}`}
                  >
                    <Trash2 size={16} aria-hidden="true" />
                  </button>
                </div>
              </div>
            );
          })
        )}
      </div>

      <div ref={sentinelRef} aria-hidden="true" className="h-px" />
      <div className="flex items-center justify-between gap-4">
        <p className="text-sm text-[var(--muted)]" role="status" aria-live="polite">
          {announcement || `Showing ${visibleGroups.length} of ${notificationGroups.length} notification groups`}
        </p>
        {hasMore ? (
          <button
            type="button"
            onClick={loadMore}
            className="inline-flex items-center gap-2 px-4 py-2 rounded-lg font-medium text-sm text-[var(--text)] bg-[var(--ov-0a)] hover:bg-[var(--ov-1a)] transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76]"
          >
            Load more
            <ChevronDown size={16} aria-hidden="true" />
          </button>
        ) : (
          <span className="text-sm text-[var(--muted)]">All notifications loaded</span>
        )}
      </div>
    </div>
  );
}

