      const now = new Date();
      const daysDiff = Math.floor((now.getTime() - txDate.getTime()) / (1000 * 60 * 60 * 24));

      if (timeFilter === "30d" && daysDiff > 30) return false;
      if (timeFilter === "90d" && daysDiff > 90) return false;
      if (timeFilter === "year" && daysDiff > 365) return false;
