              </div>
            </div>

            <div className="bg-[var(--modal)] p-6 rounded-2xl flex flex-col relative overflow-hidden group hover:bg-[var(--content-hover)] transition-colors">
              <div className="w-10 h-10 rounded-full bg-[var(--ov-0a)] flex items-center justify-center mb-6">
                <CheckCircle2 size={20} className="text-[var(--text)]" aria-hidden="true" />
              </div>
              <p className="text-[var(--muted)] text-sm font-medium mb-2">Completed Circles</p>
              <div className="flex items-end justify-between">
                <h3 className="text-3xl font-semibold font-sora tracking-tight text-[var(--text)]">12</h3>
                <div className="flex items-center gap-1 text-[var(--success)] text-xs font-semibold" aria-label="200% increase">
                  <span>+200%</span>
                  <ArrowUpRight size={14} aria-hidden="true" />
                </div>
              </div>
            </div>
          </div>
        );
      case 'balance-breakdown':
        return <BalanceBreakdownWidget />;
      case 'chart':
        return <SavingsGrowthChart />;
      case 'active-savings':
        return (
          <div>
            <div className="flex items-center mb-6">
              <h2 className="text-xl font-bold font-sora text-[var(--text)] shrink-0">Active savings</h2>
              <div className="ml-4 h-px bg-[var(--ov-1a)] w-full" aria-hidden="true" />
            </div>
            <div className="space-y-4">
              {circles.map((circle) => (
                <SavingsCard
                  key={circle.id}
                  circle={circle}
                  onContribute={handleContributeClick}
                  onClaim={handleClaimClick}
                />
              ))}
            </div>
          </div>
        );
      case 'payouts-calendar':
        return <UpcomingPayoutsCalendar circles={circles} />;
      default:
        return null;
    }
  };

  const hiddenWidgets = layout.filter(w => !w.visible);

  return (
    <div className="pb-20 md:pb-0 relative min-h-screen">
      {/* #217: dismisses itself (returns null) once the active wallet has
          a trustline — no separate dismiss button/state needed. */}
      <div className="mb-6">
        <TrustlineBanner />
      </div>

      {/* Top action bar */}
      {isClient && (
        <div className="flex justify-end mb-6 relative">
          <div className="relative">
            <FeatureSpotlight featureId="dashboard-customize" align="right">
              <button
                onClick={() => setIsCustomizeOpen(!isCustomizeOpen)}
                className="flex items-center gap-2 px-3 py-1.5 text-sm font-medium rounded-full bg-[var(--modal)] border border-[var(--border)] hover:bg-[var(--content-hover)] transition-colors text-[var(--text)]"
              >
                <Settings2 size={16} />
                Customize Layout
              </button>
            </FeatureSpotlight>

            {isCustomizeOpen && (
              <div className="absolute right-0 top-full mt-2 w-64 bg-[var(--modal)] border border-[var(--border)] rounded-xl shadow-xl p-4 z-50">
                <h4 className="text-sm font-semibold mb-3 text-[var(--text)]">Hidden Widgets</h4>
                {hiddenWidgets.length > 0 ? (
                  <div className="space-y-2 mb-4">
                    {hiddenWidgets.map(w => (
                      <div key={w.id} className="flex items-center justify-between bg-[var(--background)] px-3 py-2 rounded-lg border border-[var(--border)]">
                        <span className="text-sm text-[var(--text)]">{WIDGET_TITLES[w.id]}</span>
                        <button
                          onClick={() => toggleVisibility(w.id, true)}
                          className="p-1 hover:bg-[var(--ov-0a)] rounded text-[var(--text)]"
                          title="Show Widget"
                        >
                          <Plus size={16} />
                        </button>
                      </div>
                    ))}
                  </div>
                ) : (
                  <p className="text-xs text-[var(--muted)] mb-4">All widgets are currently visible.</p>
                )}

                <div className="h-px bg-[var(--border)] w-full mb-3" />
                <button
                  onClick={resetLayout}
                  className="w-full flex items-center justify-center gap-2 px-3 py-2 text-sm font-medium rounded-lg text-red-500 hover:bg-red-500/10 transition-colors"
                >
                  <RotateCcw size={16} />
                  Reset to Default
                </button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Widgets Flow — re-keyed on reconnect so widgets re-read fresh data */}
      <div key={refreshToken} className="space-y-6">
        <AnnualSavingsSummary />
        <SavingsGoalsWidget />
        {isClient ? layout.map((widget, idx) => {
          if (!widget.visible) return null;
          const isDragged = draggedIdx === idx;

          return (
            <div
              key={widget.id}
              draggable
              onDragStart={(e) => handleDragStart(e, idx)}
              onDragOver={(e) => handleDragOver(e, idx)}
              onDrop={(e) => handleDrop(e, idx)}
              onDragEnd={handleDragEnd}
              className={`relative group transition-all duration-200 ${isDragged ? 'opacity-40 scale-[0.98]' : 'opacity-100'}`}
            >
              <div className="flex items-center justify-between mb-2 opacity-0 group-hover:opacity-100 focus-within:opacity-100 transition-opacity h-8 px-1">
                <div className="flex items-center gap-2 text-[var(--muted)]">
                  <button
                    className="cursor-grab active:cursor-grabbing p-1 hover:text-[var(--text)] hover:bg-[var(--ov-0a)] rounded transition-colors"
                    aria-label={`Drag ${WIDGET_TITLES[widget.id]}`}
                  >
                    <GripHorizontal size={16} />
                  </button>
                  <span className="text-xs font-semibold uppercase tracking-wider">{WIDGET_TITLES[widget.id]}</span>
                </div>

                <div className="flex items-center gap-1 bg-[var(--modal)] rounded-lg border border-[var(--border)] p-1 shadow-sm">
                  <button
                    onClick={() => moveWidget(idx, -1)}
                    disabled={idx === 0}
                    className="p-1 rounded hover:bg-[var(--ov-0a)] text-[var(--muted)] hover:text-[var(--text)] disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
                    aria-label="Move Up"
                  >
                    <ArrowUp size={14} />
                  </button>
                  <button
                    onClick={() => moveWidget(idx, 1)}
                    disabled={idx === layout.length - 1}
                    className="p-1 rounded hover:bg-[var(--ov-0a)] text-[var(--muted)] hover:text-[var(--text)] disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
                    aria-label="Move Down"
                  >
                    <ArrowDown size={14} />
                  </button>
                  <div className="w-px h-4 bg-[var(--border)] mx-1" />
                  <button
                    onClick={() => toggleVisibility(widget.id, false)}
                    className="p-1 rounded hover:bg-red-500/10 text-[var(--muted)] hover:text-red-500 transition-colors"
                    aria-label="Hide Widget"
                  >
                    <EyeOff size={14} />
                  </button>
                </div>
              </div>

              <div className={isDragged ? 'pointer-events-none' : ''}>
                {renderWidgetContent(widget.id)}
              </div>
            </div>
          );
        }) : (
          /* Server-side / Initial rendering fallback */
          <>
            <div className="mt-8 mb-6">{renderWidgetContent('stats')}</div>
            <div className="mb-6">{renderWidgetContent('chart')}</div>
            <div className="mb-6">{renderWidgetContent('active-savings')}</div>
            <div>{renderWidgetContent('payouts-calendar')}</div>
          </>
        )}
      </div>

      {failedTx && !pendingTx && (
        <div className="mb-6 flex items-start justify-between gap-4 rounded-2xl border border-red-500/30 bg-red-500/10 p-4" role="alert">
          <div className="min-w-0">
            <p className="font-semibold text-red-500">Transaction failed</p>
            <p className="mt-1 text-sm text-[var(--text)]">{failedTx.reason}</p>
            <p className="mt-1 text-xs text-[var(--muted)]">
              {failedTx.type === "contribute" ? "Contribution" : "Claim"} for {failedTx.circle.name} · Attempt {failedTx.attempt}
            </p>
            {failedTx.hash && (
              <a
                href={`https://starkscan.co/tx/${failedTx.hash}`}
                target="_blank"
                rel="noopener noreferrer"
                className="mt-2 inline-flex text-xs text-[var(--muted)] underline"
              >
                View failed transaction {failedTx.hash.slice(0, 10)}...
              </a>
            )}
          </div>
          <button
            type="button"
            onClick={() => {
              setPendingTx({
                type: failedTx.type,
                circle: failedTx.circle,
                amount: failedTx.amount,
                retryFailure: failedTx,
              });
              setFailedTx(null);
            }}
            className="shrink-0 rounded-lg bg-red-500 px-4 py-2 text-sm font-semibold text-white hover:bg-red-600 transition-colors"
          >
            Retry
          </button>
        </div>
      )}

      {pendingTx && (
        <TxConfirmModal
          isOpen={!!pendingTx}
          onClose={() => setPendingTx(null)}
          type={pendingTx.type}
          circleName={pendingTx.circle.name}
          amount={pendingTx.amount}
          retryFailure={pendingTx.retryFailure}
          onFailure={(failure) => setFailedTx({ ...failure, type: pendingTx.type, circle: pendingTx.circle, amount: pendingTx.amount })}
          onConfirm={(attempt) =>
            pendingTx.type === "contribute"
              ? submitContribution(pendingTx.circle, pendingTx.amount, attempt)
              : submitClaim(pendingTx.circle, attempt)
          }
        />
      )}
    </div>
  );
}

"use client";

import { useCallback, useMemo, useState } from "react";
import Link from "next/link";
import { ArrowUpRight, CheckCircle2, Clock3, ChevronDown, FileText, X, AlertTriangle, Send } from "lucide-react";
import ExportButton from "@/components/ui/ExportButton";
import ShareMilestoneButton from "@/components/ui/ShareMilestoneButton";
import GlossaryTerm from "@/components/ui/GlossaryTerm";
import type { ExportRow } from "@/lib/export";
import type { MilestoneData } from "@/types/milestone";
import {
  MOCK_PAYOUT_HISTORY,
  formatPayoutAmount,
  type PayoutRecord,
  type PayoutStatus,
} from "@/data/payouts";
import { useLoadMore } from "@/hooks/useLoadMore";

// ---------------------------------------------------------------------------
// Local formatting helpers (screen-only variants, keep in sync with data/payouts.ts)
// ---------------------------------------------------------------------------
function formatAmount(amount: number, tokenSymbol: string) {
  return formatPayoutAmount(amount, tokenSymbol);
}

function formatDate(dateValue: string) {
  return new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  }).format(new Date(dateValue));
}

function truncateHash(hash: string) {
  return `${hash.slice(0, 8)}...${hash.slice(-6)}`;
}

function statusStyles(status: PayoutStatus) {
  if (status === "completed") {
    return "bg-[#1f3b2d] text-[#8ef0b0] border-[#2d5c43]";
  }
  return "bg-[#3a2f18] text-[#ffd56a] border-[#665221]";
}

// ---------------------------------------------------------------------------
// Round close checklist data (organizer pre-payout confirmation)
// ---------------------------------------------------------------------------
interface ChecklistMember {
  address: string;
  name: string;
  paid: boolean;
}

interface RoundCloseChecklist {
  circleName: string;
  roundNumber: number;
  tokenSymbol: string;
  poolBalance: number;
  expectedPayout: number;
  recipientAddress: string;
  members: ChecklistMember[];
}

const MOCK_ROUND_CLOSE_CHECKLIST: RoundCloseChecklist = {
  circleName: "Stark Savings Circle",
  roundNumber: 4,
  tokenSymbol: "USDC",
  poolBalance: 1200,
  expectedPayout: 1000,
  recipientAddress: "0x04f2a1b9c3d8e7f60a1b2c3d4e5f60718293a4b5c6d7e8f9012345678abcdef",
  members: [
    { address: "0x04f2a1b9c3d8e7f60a1b2c3d4e5f60718293a4b5c6d7e8f9012345678abcdef", name: "Amara O.", paid: true },
    { address: "0x07c3d4e5f60718293a4b5c6d7e8f9012345678abcdef04f2a1b9c3d8e7f6", name: "Bilal K.", paid: true },
    { address: "0x0a1b2c3d4e5f60718293a4b5c6d7e8f9012345678abcdef04f2a1b9c3d8", name: "Chen W.", paid: false },
    { address: "0x0d4e5f60718293a4b5c6d7e8f9012345678abcdef04f2a1b9c3d8e7f60a", name: "Dara M.", paid: false },
  ],
};

export default function PayoutsPage() {
  const [checklistOpen, setChecklistOpen] = useState(false);
  const [reminderSent, setReminderSent] = useState(false);
  const { visibleCount, hasMore, loadMore, sentinelRef, announcement } = useLoadMore(
    MOCK_PAYOUT_HISTORY.length,
    "dashboard:payouts"
  );
  const visiblePayouts = MOCK_PAYOUT_HISTORY.slice(0, visibleCount);

  const checklist = MOCK_ROUND_CLOSE_CHECKLIST;
  const unpaidMembers = useMemo(
    () => checklist.members.filter((member) => !member.paid),
    [checklist.members]
  );
  const balanceSufficient = checklist.poolBalance >= checklist.expectedPayout;

  const openChecklist = useCallback(() => {
    setReminderSent(false);
    setChecklistOpen(true);
  }, []);

  const closeChecklist = useCallback(() => {
    setChecklistOpen(false);
  }, []);

  const sendReminder = useCallback(() => {
    setReminderSent(true);
  }, []);

  // Exports the full history, not just the rows currently paged into view.
  const getExportRows = useCallback(
    (): ExportRow[] =>
      MOCK_PAYOUT_HISTORY.map((payout) => ({
        date: formatDate(payout.payout_date),
        circleName: payout.circle_name,
        round: payout.round_number,
        amount: formatAmount(payout.amount, payout.token_symbol),
        type: payout.status === "completed" ? "Payout" : "Payout (pending)",
        transactionHash: payout.transaction_hash,
      })),
    []
  );

  return (
    <div className="space-y-8 pb-20 md:pb-0">
      <div className="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
        <div>
          <p className="text-sm font-medium uppercase tracking-[0.2em] text-[var(--muted)]">
            Trustless transparency
          </p>
          <h1 className="mt-2 text-3xl font-bold font-sora text-[var(--text)]">
            Payout history
          </h1>
          <p className="mt-3 max-w-2xl text-sm leading-6 text-[var(--muted2)]">
            Review every completed and pending{" "}
            <GlossaryTerm term="payout">payout</GlossaryTerm> from your circles. Each
            transaction links to a{" "}
            <GlossaryTerm term="block-explorer">block explorer</GlossaryTerm> for independent
            verification.
          </p>
        </div>

        <div className="flex flex-col items-start gap-3 sm:flex-row sm:items-center">
          <button
            type="button"
            onClick={openChecklist}
            className="inline-flex items-center gap-2 rounded-xl bg-[var(--accent)] px-4 py-2.5 text-sm font-semibold text-[var(--accent-contrast)] transition-opacity hover:opacity-90"
          >
            <FileText size={16} aria-hidden="true" />
            Release payout
          </button>
          <div className="rounded-2xl border border-[var(--ov-14)] bg-[var(--modal)] px-4 py-3 text-sm text-[var(--muted2)]">
            <span className="font-semibold text-[var(--text)]">{MOCK_PAYOUT_HISTORY.length}</span> total payouts
          </div>
        </div>
      </div>

      {checklistOpen && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4"
          role="dialog"
          aria-modal="true"
          aria-labelledby="round-close-checklist-title"
        >
          <div className="max-h-[90vh] w-full max-w-lg overflow-y-auto rounded-3xl border border-[var(--ov-12)] bg-[var(--modal)] p-6 shadow-[0_24px_80px_rgba(0,0,0,0.5)]">
            <div className="flex items-start justify-between gap-4">
              <div>
                <h2
                  id="round-close-checklist-title"
                  className="text-xl font-semibold text-[var(--text)]"
                >
                  Round close checklist
                </h2>
                <p className="mt-1 text-sm text-[var(--muted2)]">
                  {checklist.circleName} · Round {checklist.roundNumber}
                </p>
              </div>
              <button
                type="button"
                onClick={closeChecklist}
                className="rounded-lg p-1.5 text-[var(--muted)] transition-colors hover:bg-[var(--ov-08)] hover:text-[var(--text)]"
                aria-label="Close checklist"
              >
                <X size={18} aria-hidden="true" />
              </button>
            </div>

            <div className="mt-5 space-y-4">
              <div className="rounded-2xl border border-[var(--ov-12)] bg-[var(--ov-05)] p-4">
                <p className="text-xs uppercase tracking-[0.18em] text-[var(--muted)]">
                  Pool balance vs expected
                </p>
                <div className="mt-2 flex items-baseline justify-between gap-3">
                  <span className="text-lg font-semibold text-[var(--text)]">
                    {formatAmount(checklist.poolBalance, checklist.tokenSymbol)}
                  </span>
                  <span className="text-sm text-[var(--muted2)]">
                    expected {formatAmount(checklist.expectedPayout, checklist.tokenSymbol)}
                  </span>
                </div>
                {!balanceSufficient && (
                  <p className="mt-2 inline-flex items-center gap-1.5 text-sm text-[#ff8a8a]">
                    <AlertTriangle size={14} aria-hidden="true" />
                    Pool balance is insufficient to cover the payout.
                  </p>
                )}
              </div>

              <div className="rounded-2xl border border-[var(--ov-12)] bg-[var(--ov-05)] p-4">
                <p className="text-xs uppercase tracking-[0.18em] text-[var(--muted)]">
                  Recipient address
                </p>
                <p className="mt-2 break-all font-mono text-sm text-[var(--text)]">
                  {checklist.recipientAddress}
                </p>
              </div>

              <div className="rounded-2xl border border-[var(--ov-12)] bg-[var(--ov-05)] p-4">
                <p className="text-xs uppercase tracking-[0.18em] text-[var(--muted)]">
                  Members ({checklist.members.length - unpaidMembers.length}/{checklist.members.length} paid)
                </p>
                <ul className="mt-3 space-y-2">
                  {checklist.members.map((member) => (
                    <li
                      key={member.address}
                      className="flex items-center justify-between gap-3 text-sm"
                    >
                      <span className="text-[var(--text)]">{member.name}</span>
                      <span
                        className={`inline-flex items-center gap-1 rounded-full border px-2.5 py-1 text-xs font-semibold uppercase tracking-[0.16em] ${
                          member.paid
                            ? "bg-[#1f3b2d] text-[#8ef0b0] border-[#2d5c43]"
                            : "bg-[#3a2f18] text-[#ffd56a] border-[#665221]"
                        }`}
                      >
                        {member.paid ? "Paid" : "Unpaid"}
                      </span>
                    </li>
                  ))}
                </ul>
                {unpaidMembers.length > 0 && (
                  <button
                    type="button"
                    onClick={sendReminder}
                    disabled={reminderSent}
                    className="mt-3 inline-flex items-center gap-2 rounded-xl border border-[var(--ov-14)] px-3 py-2 text-sm font-medium text-[var(--text)] transition-colors hover:bg-[var(--ov-08)] disabled:cursor-not-allowed disabled:opacity-60"
                  >
                    <Send size={14} aria-hidden="true" />
                    {reminderSent
                      ? "Reminder sent"
                      : `Send reminder to ${unpaidMembers.length} unpaid`}
                  </button>
                )}
              </div>
            </div>

            <div className="mt-6 flex flex-col-reverse gap-3 sm:flex-row sm:justify-end">
              <button
                type="button"
                onClick={closeChecklist}
                className="rounded-xl border border-[var(--ov-14)] px-4 py-2.5 text-sm font-medium text-[var(--text)] transition-colors hover:bg-[var(--ov-08)]"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={closeChecklist}
                disabled={!balanceSufficient}
                className="inline-flex items-center justify-center gap-2 rounded-xl bg-[var(--accent)] px-4 py-2.5 text-sm font-semibold text-[var(--accent-contrast)] transition-opacity hover:opacity-90 disabled:cursor-not-allowed disabled:opacity-50"
              >
                <CheckCircle2 size={16} aria-hidden="true" />
                Confirm release
              </button>
            </div>
          </div>
        </div>
      )}

      <section className="overflow-hidden rounded-3xl border border-[var(--ov-12)] bg-[var(--modal)] shadow-[0_24px_80px_rgba(0,0,0,0.35)]">
        {MOCK_PAYOUT_HISTORY.length === 0 ? (
          <div className="flex min-h-[320px] flex-col items-center justify-center px-6 text-center">
            <div className="mb-4 flex h-14 w-14 items-center justify-center rounded-full border border-[var(--ov-14)] bg-[var(--ov-08)] text-[var(--text)]">
              <CheckCircle2 size={24} aria-hidden="true" />
            </div>
            <h2 className="text-xl font-semibold text-[var(--text)]">No payouts yet</h2>
            <p className="mt-2 max-w-md text-sm leading-6 text-[var(--muted)]">
              When your circles start distributing funds, the full payout
              history will appear here with transaction links for verification.
            </p>
          </div>
        ) : (
          <>
            <div className="overflow-x-auto">
              <table className="min-w-full divide-y divide-[var(--ov-0f)]">
                <thead className="bg-[var(--ov-05)] text-start text-xs uppercase tracking-[0.18em] text-[var(--muted)]">
                  <tr>
                    <th scope="col" className="px-6 py-4 font-medium">
                      Circle Name
                    </th>
                    <th scope="col" className="px-6 py-4 font-medium">
                      Amount
                    </th>
                    <th scope="col" className="px-6 py-4 font-medium">
                      Date
                    </th>
                    <th scope="col" className="px-6 py-4 font-medium">
                      Round #
                    </th>
                    <th scope="col" className="px-6 py-4 font-medium">
                      <span className="inline-flex items-center gap-1">
                        Transaction Hash
                        <GlossaryTerm term="transaction-hash" iconOnly placement="bottom" />
                      </span>
                    </th>
                    <th scope="col" className="px-6 py-4 font-medium">
                      Status
                    </th>
                    <th scope="col" className="px-6 py-4 font-medium">
                      <span className="sr-only">Share</span>
                    </th>
                    <th scope="col" className="px-6 py-4 font-medium">
                      <span className="sr-only">Receipt</span>
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[var(--ov-0f)] bg-[var(--modal)]">
                  {visiblePayouts.map((payout) => (
                    <tr key={payout.transaction_hash} className="transition-colors hover:bg-[var(--ov-06)]">
                      <td className="px-6 py-4 text-sm font-medium text-[var(--text)]">
                        {payout.circle_name}
                      </td>
                      <td className="px-6 py-4 text-sm text-[var(--text)]">
                        {formatAmount(payout.amount, payout.token_symbol)}
                      </td>
                      <td className="px-6 py-4 text-sm text-[var(--muted2)]">
                        {formatDate(payout.payout_date)}
                      </td>
                      <td className="px-6 py-4 text-sm text-[var(--muted2)]">
                        {payout.round_number}
                      </td>
                      <td className="px-6 py-4 text-sm">
                        <Link
                          href={`https://starkscan.co/tx/${payout.transaction_hash}`}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="inline-flex items-center gap-1 text-[var(--info)] transition-colors hover:text-[var(--text)]"
                          aria-label={`Open transaction ${payout.transaction_hash} in a new tab`}
                        >
                          <span className="font-mono">
                            {truncateHash(payout.transaction_hash)}
                          </span>
                          <ArrowUpRight size={14} aria-hidden="true" />
                        </Link>
                      </td>
                      <td className="px-6 py-4 text-sm">
                        <span
                          className={`inline-flex items-center gap-1 rounded-full border px-2.5 py-1 text-xs font-semibold uppercase tracking-[0.16em] ${statusStyles(
                            payout.status
                          )}`}
                        >
                          {payout.status === "completed" ? (
                            <CheckCircle2 size={12} aria-hidden="true" />
                          ) : (
                            <Clock3 size={12} aria-hidden="true" />
                          )}
                          {payout.status}
                        </span>
                      </td>
                      <td className="px-6 py-4 text-sm">
                        <ShareMilestoneButton
                          milestone={{
                            type: "payout_received",
                            circleName: payout.circle_name,
                            amount: formatAmount(payout.amount, payout.token_symbol),
                            subtitle: `Round ${payout.round_number}`,
                            date: formatDate(payout.payout_date),
                          } satisfies MilestoneData}
                        />
                      </td>
                      <td className="px-6 py-4 text-sm">
                        <Link
                          href={`/dashboard/payouts/${payout.transaction_hash}`}
                          className="inline-flex items-center gap-1 text-[var(--info)] transition-colors hover:text-[var(--text)]"
                        >
                          <FileText size={14} aria-hidden="true" />
                          Receipt
                        </Link>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            <div ref={sentinelRef} aria-hidden="true" className="h-px" />
            <div className="flex items-center justify-between gap-4 border-t border-[var(--ov-0f)] px-6 py-4">
              <p className="text-sm text-[var(--muted)]" role="status" aria-live="polite">
                {announcement || `Showing ${visiblePayouts.length} of ${MOCK_PAYOUT_HISTORY.length} payouts`}
              </p>

              {hasMore ? (
                <button
                  type="button"
                  onClick={loadMore}
                  className="inline-flex items-center gap-2 rounded-full border border-[var(--ov-16)] bg-[var(--ov-08)] px-4 py-2 text-sm font-medium text-[var(--text)] transition-colors hover:bg-[var(--ov-10)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76]"
                >
                  Load more
                  <ChevronDown size={14} aria-hidden="true" />
                </button>
              ) : null}
            </div>
          </>
        )}
      </section>
    </div>
  );
}

