"use client";

import { useState, useMemo } from "react";
import { Calculator, Calendar, DollarSign, Users, Clock, Info } from "lucide-react";

export type Frequency = "Daily" | "Weekly" | "Bi-weekly" | "Monthly";

const FREQUENCY_DAYS: Record<Frequency, number> = {
  "Daily": 1,
  "Weekly": 7,
  "Bi-weekly": 14,
  "Monthly": 30,
};

function getFrequencyFromDays(days: number): string {
  if (days === 1) return "Daily";
  if (days === 7) return "Weekly";
  if (days === 14) return "Bi-weekly";
  if (days === 30) return "Monthly";
  return `Every ${days} days`;
}

interface SavingsCalculatorProps {
  // Controlled props for preview mode
  amount?: number;
  participants?: number;
  frequencyDays?: number;
  
  // Uncontrolled initial values for standalone mode
  defaultAmount?: number;
  defaultParticipants?: number;
  defaultFrequency?: Frequency;
  
  isReadOnly?: boolean;
}

export default function SavingsCalculator({
  amount: controlledAmount,
  participants: controlledParticipants,
  frequencyDays: controlledFrequencyDays,
  defaultAmount = 50,
  defaultParticipants = 5,
  defaultFrequency = "Weekly",
  isReadOnly = false,
}: SavingsCalculatorProps) {
  // Local state for standalone mode
  const [localAmount, setLocalAmount] = useState<string>(defaultAmount.toString());
  const [localParticipants, setLocalParticipants] = useState<string>(defaultParticipants.toString());
  const [localFrequency, setLocalFrequency] = useState<Frequency>(defaultFrequency);

  const amount = isReadOnly ? (controlledAmount || 0) : (Number(localAmount) || 0);
  const participants = isReadOnly ? (controlledParticipants || 0) : (Number(localParticipants) || 0);
  const daysPerRound = isReadOnly 
    ? (controlledFrequencyDays || 7) 
    : FREQUENCY_DAYS[localFrequency];

  // Validation bounds
  const isValidAmount = amount > 0;
  const isValidParticipants = participants >= 2 && participants <= 20;
  
  const totalPayout = amount * participants;
  const totalDurationDays = participants * daysPerRound;

  // Generate schedule
  const schedule = useMemo(() => {
    if (!isValidAmount || !isValidParticipants) return [];
    
    const dates = [];
    let currentDate = new Date();
    
    for (let i = 1; i <= participants; i++) {
      // Add days
      currentDate = new Date(currentDate.getTime() + daysPerRound * 24 * 60 * 60 * 1000);
      dates.push({
        round: i,
        date: currentDate,
        amount: totalPayout,
      });
    }
    return dates;
  }, [amount, participants, daysPerRound, isValidAmount, isValidParticipants]);

  const formatDate = (date: Date) => {
    return new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", year: "numeric" }).format(date);
  };

  return (
    <div className="bg-[var(--modal)] border border-[var(--border)] rounded-3xl p-6 md:p-8 shadow-sm">
      {!isReadOnly && (
        <div className="flex items-center gap-3 mb-8">
          <div className="w-12 h-12 rounded-xl bg-[#4B6B76]/10 flex items-center justify-center">
            <Calculator className="text-[#4B6B76]" size={24} />
          </div>
          <div>
            <h2 className="text-xl font-bold font-sora text-[var(--text)]">Savings Simulator</h2>
            <p className="text-[var(--muted)] text-sm">Calculate your projected payouts</p>
          </div>
        </div>
      )}

      <div className={`grid gap-8 ${isReadOnly ? 'grid-cols-1' : 'md:grid-cols-2'}`}>
        {/* Controls Section */}
        {!isReadOnly && (
          <div className="space-y-6">
            <div>
              <label className="text-sm font-medium text-[var(--text)] mb-2 block flex justify-between">
                Contribution per round
                <span className="text-[var(--muted)] font-normal">USDT</span>
              </label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                  <DollarSign size={18} className="text-[var(--muted)]" />
                </div>
                <input
                  type="number"
                  min="1"
                  value={localAmount}
                  onChange={(e) => setLocalAmount(e.target.value)}
                  className="w-full bg-[var(--background)] border border-[var(--border)] rounded-xl pl-10 pr-4 py-3 text-[var(--text)] focus:outline-none focus:ring-2 focus:ring-[#4B6B76] transition-shadow"
                />
              </div>
              {!isValidAmount && localAmount !== "" && (
                <p className="text-red-500 text-xs mt-1.5">Amount must be greater than 0</p>
              )}
            </div>

            <div>
              <label className="text-sm font-medium text-[var(--text)] mb-2 block flex justify-between">
                Number of participants
                <span className="text-[var(--muted)] font-normal">2 - 20 max</span>
              </label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                  <Users size={18} className="text-[var(--muted)]" />
                </div>
                <input
                  type="number"
                  min="2"
                  max="20"
                  value={localParticipants}
                  onChange={(e) => setLocalParticipants(e.target.value)}
                  className="w-full bg-[var(--background)] border border-[var(--border)] rounded-xl pl-10 pr-4 py-3 text-[var(--text)] focus:outline-none focus:ring-2 focus:ring-[#4B6B76] transition-shadow"
                />
              </div>
              {!isValidParticipants && localParticipants !== "" && (
                <p className="text-red-500 text-xs mt-1.5">Participants must be between 2 and 20</p>
              )}
            </div>

            <div>
              <label className="text-sm font-medium text-[var(--text)] mb-2 block">
                Round frequency
              </label>
              <div className="grid grid-cols-2 gap-2">
                {(Object.keys(FREQUENCY_DAYS) as Frequency[]).map((freq) => (
                  <button
                    key={freq}
                    onClick={() => setLocalFrequency(freq)}
                    className={`py-2.5 px-4 rounded-xl text-sm font-medium transition-colors border ${
                      localFrequency === freq
                        ? "bg-[#4B6B76] text-white border-[#4B6B76]"
                        : "bg-[var(--background)] text-[var(--text)] border-[var(--border)] hover:border-[#4B6B76]"
                    }`}
                  >
                    {freq}
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* Results Section */}
        <div className={`space-y-6 ${isReadOnly ? '' : 'bg-[var(--background)] p-6 rounded-2xl border border-[var(--border)]'}`}>
          {!isReadOnly && <h3 className="font-semibold text-[var(--text)] mb-4 font-sora">Simulation Results</h3>}
          
          <div className="grid grid-cols-2 gap-4">
            <div className="bg-[var(--ov-0a)] p-4 rounded-xl">
              <p className="text-[var(--muted)] text-xs font-medium mb-1 flex items-center gap-1.5">
                <DollarSign size={14} /> Total Payout
              </p>
              <p className="text-2xl font-bold font-sora text-[var(--text)]">
                {isValidAmount && isValidParticipants ? `$${totalPayout.toLocaleString()}` : '—'}
              </p>
            </div>
            
            <div className="bg-[var(--ov-0a)] p-4 rounded-xl">
              <p className="text-[var(--muted)] text-xs font-medium mb-1 flex items-center gap-1.5">
                <Clock size={14} /> Duration
              </p>
              <p className="text-2xl font-bold font-sora text-[var(--text)]">
                {isValidAmount && isValidParticipants ? `${totalDurationDays} days` : '—'}
              </p>
            </div>
          </div>

          <div className="bg-[#4B6B76]/10 border border-[#4B6B76]/20 rounded-xl p-4 flex items-start gap-3">
            <Info size={18} className="text-[#4B6B76] shrink-0 mt-0.5" />
            <p className="text-sm text-[var(--text)]">
              Each round, all {isValidParticipants ? participants : '—'} members contribute {isValidAmount ? `$${amount}` : '—'}, 
              and one person receives the total pool of {isValidAmount && isValidParticipants ? `$${totalPayout}` : '—'}. 
              Frequency: {isReadOnly ? getFrequencyFromDays(daysPerRound) : localFrequency}.
            </p>
          </div>

          {isValidAmount && isValidParticipants && (
            <div>
              <h4 className="text-sm font-semibold text-[var(--text)] mb-3 flex items-center gap-2">
                <Calendar size={16} className="text-[var(--muted)]" />
                Projected Payout Schedule
              </h4>
              <div className="space-y-2 max-h-[200px] overflow-y-auto pr-2 custom-scrollbar">
                {schedule.map((item) => (
                  <div key={item.round} className="flex items-center justify-between py-2 border-b border-[var(--border)] last:border-0">
                    <div className="flex items-center gap-3">
                      <div className="w-6 h-6 rounded-full bg-[var(--ov-1a)] flex items-center justify-center text-xs font-medium text-[var(--text)]">
                        {item.round}
                      </div>
                      <span className="text-sm text-[var(--muted)]">{formatDate(item.date)}</span>
                    </div>
                    <span className="text-sm font-semibold text-[var(--text)]">${item.amount.toLocaleString()}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { Info, ShieldCheck, X, Zap } from "lucide-react";
import { Toggle } from "@/components/ui/Toggle";
import { useToast } from "@/components/ui/Toast";
import { useFocusTrap } from "@/hooks/useFocusTrap";
import { disableAutoPay, enableAutoPay, getAutoPayConfig } from "@/lib/autoPay";
import type { AutoPayConfig } from "@/types/autoPay";

interface AutoPaySectionProps {
  circleId: string;
  /** Default authorized amount to pre-fill, e.g. "50 USDT" (the circle's contribution). */
  defaultAmount: string;
  /** Human label for the round cadence, e.g. "2 Days". */
  roundDuration: string;
  /** "compact" renders a single toggle row (circle detail page); "manage" renders
   * the fuller authorization + pause/cancel panel (circle settings page). */
  variant?: "compact" | "manage";
}

function EnableConfirmModal({
  open,
  onClose,
  onConfirm,
  amount,
  setAmount,
  frequencyLabel,
}: {
  open: boolean;
  onClose: () => void;
  onConfirm: () => void;
  amount: string;
  setAmount: (v: string) => void;
  frequencyLabel: string;
}) {
  const dialogRef = useRef<HTMLDivElement>(null);
  useFocusTrap(dialogRef, open, onClose);

  if (!open) return null;

  return (
    <div
      className="fixed inset-0 z-200 flex items-center justify-center bg-black/70 backdrop-blur-sm px-4"
      role="dialog"
      aria-modal="true"
      aria-labelledby="autopay-confirm-title"
      onClick={onClose}
    >
      <div
        ref={dialogRef}
        className="w-full max-w-md rounded-2xl bg-[var(--modal)] border border-[var(--ov-14)] p-6 shadow-xl"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between mb-4">
          <h2 id="autopay-confirm-title" className="flex items-center gap-2 text-lg font-semibold text-[var(--text)]">
            <Zap size={18} aria-hidden="true" />
            Enable Auto-Pay
          </h2>
          <button onClick={onClose} aria-label="Close" className="text-[var(--muted)] hover:text-[var(--text)]">
            <X size={20} />
          </button>
        </div>

        <div className="flex items-start gap-2 rounded-xl bg-[var(--ov-05)] p-3 mb-4">
          <Info size={16} className="mt-0.5 shrink-0 text-[var(--muted)]" aria-hidden="true" />
          <p className="text-xs text-[var(--muted)]">
            Turning this on authorizes your connected wallet to automatically send the
            contribution below each round, without asking you to confirm every time. You can
            revoke this authorization and pause or cancel auto-pay at any time from circle
            settings.
          </p>
        </div>

        <div className="mb-4">
          <label htmlFor="autopay-amount" className="block text-xs text-[var(--muted)] mb-1.5">
            Authorized amount per round
          </label>
          <input
            id="autopay-amount"
            type="text"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            className="w-full bg-[var(--ov-0a)] border border-[var(--ov-14)] rounded-xl px-4 py-2.5 text-sm text-[var(--text)] focus:outline-none focus:ring-2 focus:ring-[#4B6B76]"
          />
        </div>

        <dl className="space-y-2 rounded-xl bg-[var(--ov-05)] p-3 text-xs mb-5">
          <div className="flex justify-between">
            <dt className="text-[var(--muted)]">Frequency</dt>
            <dd className="text-[var(--text)] font-medium">{frequencyLabel}</dd>
          </div>
          <div className="flex justify-between">
            <dt className="text-[var(--muted)]">Cancellation</dt>
            <dd className="text-[var(--text)] font-medium">Anytime, from circle settings</dd>
          </div>
        </dl>

        <div className="flex gap-3">
          <button
            onClick={onClose}
            className="flex-1 rounded-xl border border-[var(--ov-1a)] text-[var(--text)] py-2.5 font-medium hover:bg-[var(--ov-0a)] transition-colors"
          >
            Cancel
          </button>
          <button
            onClick={onConfirm}
            className="flex-1 flex items-center justify-center gap-2 rounded-xl bg-[#4B6B76] hover:bg-[#3D5A64] text-white py-2.5 font-semibold transition-colors"
          >
            <ShieldCheck size={16} aria-hidden="true" />
            Authorize
          </button>
        </div>
      </div>
    </div>
  );
}

export default function AutoPaySection({
  circleId,
  defaultAmount,
  roundDuration,
  variant = "compact",
}: AutoPaySectionProps) {
  const { showToast } = useToast();
  const [config, setConfig] = useState<AutoPayConfig | null>(null);
  const [showConfirm, setShowConfirm] = useState(false);
  const [amountInput, setAmountInput] = useState(defaultAmount);
  const [confirmingCancel, setConfirmingCancel] = useState(false);

  const frequencyLabel = `Every round (every ${roundDuration})`;

  useEffect(() => {
    setConfig(getAutoPayConfig(circleId));
  }, [circleId]);

  function handleToggle(next: boolean) {
    if (next) {
      setAmountInput(config?.authorizedAmount ?? defaultAmount);
      setShowConfirm(true);
    } else {
      setConfirmingCancel(true);
    }
  }

  function handleConfirmEnable() {
    const updated = enableAutoPay({ circleId, authorizedAmount: amountInput, frequency: frequencyLabel });
    setConfig(updated);
    setShowConfirm(false);
    showToast({
      title: "Auto-Pay enabled",
      message: `${amountInput} authorized ${frequencyLabel.toLowerCase()}.`,
      variant: "success",
    });
  }

  function handleDisable() {
    disableAutoPay(circleId);
    setConfig((current) => (current ? { ...current, enabled: false } : current));
    setConfirmingCancel(false);
    showToast({ title: "Auto-Pay paused", message: "Your wallet authorization has been revoked.", variant: "success" });
  }

  const enabled = config?.enabled ?? false;

  if (variant === "compact") {
    return (
      <>
        <div className="flex items-center justify-between bg-[var(--content)] p-5 rounded-2xl">
          <div className="flex items-center gap-3">
            <span className={`flex h-9 w-9 items-center justify-center rounded-full ${enabled ? "bg-emerald-500/10 text-emerald-500" : "bg-[var(--ov-0a)] text-[var(--muted)]"}`}>
              <Zap size={16} aria-hidden="true" />
            </span>
            <div>
              <p className="text-sm font-semibold text-[var(--text)]">Auto-Pay</p>
              <p className="text-xs text-[var(--muted)]">
                {enabled
                  ? `Authorized ${config?.authorizedAmount} · ${config?.frequency ?? frequencyLabel}`
                  : "Automatically contribute each round without manual confirmation."}
              </p>
            </div>
          </div>
          <Toggle checked={enabled} onChange={handleToggle} id="autopay-toggle-compact" />
        </div>

        {config?.lastAttempt?.status === "failed" && enabled && (
          <div className="flex items-start gap-3 rounded-2xl border border-amber-300 dark:border-amber-800/60 bg-amber-50 dark:bg-amber-500/10 p-4">
            <Info size={18} className="mt-0.5 shrink-0 text-amber-600 dark:text-amber-400" aria-hidden="true" />
            <div>
              <p className="text-sm font-medium text-amber-800 dark:text-amber-300">Auto-Pay attempt failed</p>
              <p className="text-xs text-amber-700 dark:text-amber-400 mt-0.5">
                {config.lastAttempt.reason ?? "We couldn't complete your automatic contribution this round."}
                {" "}Please make a manual contribution below to avoid missing this round.
              </p>
            </div>
          </div>
        )}

        <EnableConfirmModal
          open={showConfirm}
          onClose={() => setShowConfirm(false)}
          onConfirm={handleConfirmEnable}
          amount={amountInput}
          setAmount={setAmountInput}
          frequencyLabel={frequencyLabel}
        />

        {confirmingCancel && (
          <div className="fixed inset-0 z-200 flex items-center justify-center bg-black/60 backdrop-blur-sm px-4" role="dialog" aria-modal="true" onClick={() => setConfirmingCancel(false)}>
            <div className="w-full max-w-sm rounded-2xl bg-[var(--modal)] border border-[var(--ov-14)] p-6" onClick={(e) => e.stopPropagation()}>
              <h4 className="text-base font-semibold text-[var(--text)]">Turn off Auto-Pay?</h4>
              <p className="mt-2 text-sm text-[var(--muted)]">
                Your wallet authorization will be revoked. You&apos;ll need to make contributions manually until you re-enable it.
              </p>
              <div className="mt-5 flex justify-end gap-2">
                <button type="button" onClick={() => setConfirmingCancel(false)} className="rounded-lg border border-[var(--ov-14)] px-3.5 py-2 text-sm text-[var(--text)] hover:bg-[var(--ov-0a)] transition-colors">
                  Keep it on
                </button>
                <button type="button" onClick={handleDisable} className="rounded-lg bg-[#FF5B5B] px-3.5 py-2 text-sm font-semibold text-white hover:bg-[#e14e4e] transition-colors">
                  Turn off
                </button>
              </div>
            </div>
          </div>
        )}
      </>
    );
  }

  // "manage" variant — used in circle settings for pausing/cancelling at any time.
  return (
    <section className="bg-[var(--content)] p-6 rounded-2xl space-y-4">
      <div>
        <h2 className="text-lg font-bold font-sora text-[var(--text)]">Auto-Pay</h2>
        <p className="text-xs text-[var(--muted)] mt-1">
          Manage this circle&apos;s recurring contribution authorization.
        </p>
      </div>

      {enabled ? (
        <>
          <dl className="grid grid-cols-2 gap-4 rounded-xl bg-[var(--ov-05)] p-4 text-sm">
            <div>
              <dt className="text-xs text-[var(--muted)] mb-1">Authorized amount</dt>
              <dd className="font-medium text-[var(--text)]">{config?.authorizedAmount}</dd>
            </div>
            <div>
              <dt className="text-xs text-[var(--muted)] mb-1">Frequency</dt>
              <dd className="font-medium text-[var(--text)]">{config?.frequency}</dd>
            </div>
          </dl>
          <div className="flex gap-2">
            <button
              type="button"
              onClick={() => setConfirmingCancel(true)}
              className="inline-flex items-center gap-2 px-4 py-2 bg-[#FF5B5B1a] hover:bg-[#FF5B5B29] text-[#FF5B5B] text-sm font-medium rounded-lg transition-colors"
            >
              Pause / Cancel Auto-Pay
            </button>
          </div>
        </>
      ) : (
        <button
          type="button"
          onClick={() => {
            setAmountInput(config?.authorizedAmount ?? defaultAmount);
            setShowConfirm(true);
          }}
          className="inline-flex items-center gap-2 px-4 py-2.5 bg-[#4B6B76] hover:bg-[#3D5A64] text-white text-sm font-medium rounded-lg transition-colors"
        >
          <Zap size={16} aria-hidden="true" />
          Enable Auto-Pay
        </button>
      )}

      <EnableConfirmModal
        open={showConfirm}
        onClose={() => setShowConfirm(false)}
        onConfirm={handleConfirmEnable}
        amount={amountInput}
        setAmount={setAmountInput}
        frequencyLabel={frequencyLabel}
      />

      {confirmingCancel && (
        <div className="fixed inset-0 z-200 flex items-center justify-center bg-black/60 backdrop-blur-sm px-4" role="dialog" aria-modal="true" onClick={() => setConfirmingCancel(false)}>
          <div className="w-full max-w-sm rounded-2xl bg-[var(--modal)] border border-[var(--ov-14)] p-6" onClick={(e) => e.stopPropagation()}>
            <h4 className="text-base font-semibold text-[var(--text)]">Pause or cancel Auto-Pay?</h4>
            <p className="mt-2 text-sm text-[var(--muted)]">
              This revokes the wallet authorization immediately. You can re-enable it later from this page.
            </p>
            <div className="mt-5 flex justify-end gap-2">
              <button type="button" onClick={() => setConfirmingCancel(false)} className="rounded-lg border border-[var(--ov-14)] px-3.5 py-2 text-sm text-[var(--text)] hover:bg-[var(--ov-0a)] transition-colors">
                Keep it on
              </button>
              <button type="button" onClick={handleDisable} className="rounded-lg bg-[#FF5B5B] px-3.5 py-2 text-sm font-semibold text-white hover:bg-[#e14e4e] transition-colors">
                Confirm
              </button>
            </div>
          </div>
        </div>
      )}
    </section>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import {
  RefreshCw,
  Check,
  X,
  Clock,
  Dices,
  ArrowRight,
  ShieldAlert,
  Sparkles,
  Users,
  CheckCircle2,
  AlertCircle,
} from "lucide-react";
import {
  canEnableAutoRenew,
  enableCircleRenewal,
  disableCircleRenewal,
  getCircleRenewal,
  setMemberRenewalOptIn,
  renewCircleCycle,
  getNextCycleName,
  CIRCLE_RENEWAL_UPDATED_EVENT,
  type CircleRenewalConfig,
  type RenewalOptInStatus,
} from "@/lib/circleRenewal";
import { useToast } from "@/components/ui/Toast";
import PayoutDrawModal from "@/components/circles/PayoutDrawModal";
import type { PayoutDraw } from "@/lib/payoutDraw";

interface ParticipantInfo {
  address: string;
  role?: string;
  displayName?: string;
}

interface AutoRenewCircleProps {
  circle: {
    id: string;
    name: string;
    creator: string;
    status: "active" | "completed" | "pending";
    currentRound: number;
    totalRounds: number;
    contribution: string;
    duration: string;
    participants: ParticipantInfo[];
    category?: string;
    description?: string;
    isPrivate?: boolean;
    penaltyEnabled?: boolean;
    penaltyType?: "percentage" | "fixed";
    penaltyValue?: string;
    penalty?: { enabled: boolean; type: "percentage" | "fixed"; value: string };
    totalSlots?: number;
  };
  currentWallet: string;
  onCycleCreated?: (newCircleId: string) => void;
}

function truncate(address: string) {
  return `${address.slice(0, 8)}…${address.slice(-6)}`;
}

export default function CircleAutoRenewCard({
  circle,
  currentWallet,
  onCycleCreated,
}: AutoRenewCircleProps) {
  const { showToast } = useToast();
  const [config, setConfig] = useState<CircleRenewalConfig | null>(() =>
    getCircleRenewal(circle.id)
  );
  const [nextCycleName, setNextCycleName] = useState(() =>
    config?.nextCycleName ?? getNextCycleName(circle.name)
  );
  const [redrawOrder, setRedrawOrder] = useState(() => config?.redrawPayoutOrder ?? true);
  const [isLaunching, setIsLaunching] = useState(false);
  const [showDrawModal, setShowDrawModal] = useState(false);

  useEffect(() => {
    const handleUpdate = () => {
      const updated = getCircleRenewal(circle.id);
      setConfig(updated);
      if (updated?.nextCycleName) {
        setNextCycleName(updated.nextCycleName);
      }
      if (typeof updated?.redrawPayoutOrder === "boolean") {
        setRedrawOrder(updated.redrawPayoutOrder);
      }
    };

    window.addEventListener(CIRCLE_RENEWAL_UPDATED_EVENT, handleUpdate);
    return () => window.removeEventListener(CIRCLE_RENEWAL_UPDATED_EVENT, handleUpdate);
  }, [circle.id]);

  const isOrganizer = circle.creator.toLowerCase() === currentWallet.toLowerCase();
  const isMember = circle.participants.some(
    (p) => p.address.toLowerCase() === currentWallet.toLowerCase()
  );

  const renewalEligibility = canEnableAutoRenew(
    circle.currentRound,
    circle.totalRounds,
    circle.status
  );

  const participantAddresses = useMemo(
    () => circle.participants.map((p) => p.address),
    [circle.participants]
  );

  const optedInAddresses = useMemo(() => {
    if (!config || !config.optIns) return [];
    return Object.entries(config.optIns)
      .filter(([_, status]) => status === "opted_in")
      .map(([addr]) => addr);
  }, [config]);

  const optedInCount = optedInAddresses.length;
  const totalCount = circle.participants.length;

  const userStatus: RenewalOptInStatus = useMemo(() => {
    if (!config) return "pending";
    return config.optIns[currentWallet.toLowerCase()] ?? "pending";
  }, [config, currentWallet]);

  function handleEnable() {
    if (!renewalEligibility.allowed) {
      showToast({
        title: "Auto-renew restricted",
        message: renewalEligibility.reason ?? "Cannot enable auto-renew now.",
        variant: "error",
      });
      return;
    }

    const updated = enableCircleRenewal(
      circle.id,
      participantAddresses,
      circle.creator,
      redrawOrder,
      nextCycleName
    );
    setConfig(updated);
    showToast({
      title: "Auto-Renew Enabled",
      message: `Members have been asked to opt into ${nextCycleName}.`,
      variant: "success",
    });
  }

  function handleDisable() {
    disableCircleRenewal(circle.id);
    setConfig(getCircleRenewal(circle.id));
    showToast({
      title: "Auto-Renew Disabled",
      message: "The auto-renew schedule for this circle has been turned off.",
      variant: "neutral",
    });
  }

  function handleOptIn(status: RenewalOptInStatus) {
    const updated = setMemberRenewalOptIn(circle.id, currentWallet, status);
    setConfig(updated);
    showToast({
      title: status === "opted_in" ? "Opted In" : "Opted Out",
      message:
        status === "opted_in"
          ? "You are opted into the next cycle!"
          : "You opted out of the next cycle.",
      variant: status === "opted_in" ? "success" : "neutral",
    });
  }

  function handleLaunchNextCycle() {
    if (!config) return;
    if (optedInCount < 2) {
      showToast({
        title: "Not Enough Members",
        message: "At least 2 members must opt in to launch the next cycle.",
        variant: "error",
      });
      return;
    }

    try {
      setIsLaunching(true);
      const { newCircle } = renewCircleCycle({
        parentCircle: circle,
        config: {
          ...config,
          redrawPayoutOrder: redrawOrder,
          nextCycleName,
        },
        currentWallet,
      });

      showToast({
        title: "Next Cycle Launched!",
        message: `${newCircle.name} has been created with ${optedInCount} members.`,
        variant: "success",
      });

      setConfig(getCircleRenewal(circle.id));
      if (onCycleCreated) {
        onCycleCreated(newCircle.id);
      }
    } catch (err: any) {
      showToast({
        title: "Failed to Launch Cycle",
        message: err.message || "An unexpected error occurred.",
        variant: "error",
      });
    } finally {
      setIsLaunching(false);
    }
  }

  // Non-members don't see renewal management
  if (!isMember && !isOrganizer) return null;

  // If renewal was completed and new cycle exists
  if (config?.renewedCircleId) {
    return (
      <div className="rounded-2xl border border-emerald-500/20 bg-emerald-500/5 p-6 backdrop-blur-sm">
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-emerald-500/15 text-emerald-600 dark:text-emerald-400">
              <CheckCircle2 size={20} />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <span className="font-semibold text-emerald-700 dark:text-emerald-300">
                  Cycle Renewed Successfully
                </span>
                <span className="rounded-full bg-emerald-500/15 px-2 py-0.5 text-xs font-medium text-emerald-600 dark:text-emerald-400">
                  Live
                </span>
              </div>
              <p className="text-sm text-[var(--muted)]">
                The next cycle with {optedInCount} opted-in members is now active.
              </p>
            </div>
          </div>
          <Link
            href={`/dashboard/circles/${encodeURIComponent(config.renewedCircleId)}`}
            className="inline-flex items-center gap-2 rounded-xl bg-[#4B6B76] px-4 py-2.5 text-sm font-medium text-white transition hover:bg-[#3D5A64]"
          >
            Go to Next Cycle
            <ArrowRight size={16} />
          </Link>
        </div>
      </div>
    );
  }

  // 1. Organizer View when Auto-Renew is not yet enabled
  if (isOrganizer && (!config || !config.enabled)) {
    return (
      <div className="rounded-2xl border border-[var(--ov-10)] bg-[var(--content)] p-6 shadow-sm">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-4">
          <div className="flex items-center gap-3">
            <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[#4B6B76]/10 text-[#4B6B76]">
              <RefreshCw size={20} />
            </div>
            <div>
              <h2 className="font-sora font-semibold text-[var(--text)]">
                Auto-Renew & Next Cycle
              </h2>
              <p className="text-xs text-[var(--muted)]">
                Keep the momentum going by preparing the next cycle with current members.
              </p>
            </div>
          </div>
          <span
            className={`self-start sm:self-auto rounded-full px-2.5 py-1 text-xs font-medium ${
              renewalEligibility.allowed
                ? "bg-blue-500/10 text-blue-600 dark:text-blue-400"
                : "bg-amber-500/10 text-amber-600 dark:text-amber-400"
            }`}
          >
            {renewalEligibility.allowed ? "Eligible before final round" : "Past final round"}
          </span>
        </div>

        {!renewalEligibility.allowed ? (
          <div className="flex items-start gap-2.5 rounded-xl bg-amber-500/10 p-4 text-xs text-amber-700 dark:text-amber-300">
            <AlertCircle size={16} className="shrink-0 mt-0.5" />
            <p>
              {renewalEligibility.reason ??
                "Auto-renew can only be enabled before the final round begins."}
            </p>
          </div>
        ) : (
          <div className="space-y-4 pt-2 border-t border-[var(--ov-08)]">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium text-[var(--muted)] mb-1">
                  Next Cycle Name
                </label>
                <input
                  type="text"
                  value={nextCycleName}
                  onChange={(e) => setNextCycleName(e.target.value)}
                  className="w-full rounded-xl border border-[var(--ov-14)] bg-[var(--background)] px-3.5 py-2 text-sm text-[var(--text)] focus:border-[#4B6B76] focus:outline-none"
                  placeholder={`${circle.name} (Cycle 2)`}
                />
              </div>
              <div className="flex items-center pt-5">
                <label className="flex items-center gap-2 cursor-pointer text-sm text-[var(--text)]">
                  <input
                    type="checkbox"
                    checked={redrawOrder}
                    onChange={(e) => setRedrawOrder(e.target.checked)}
                    className="h-4 w-4 rounded border-gray-300 text-[#4B6B76] focus:ring-[#4B6B76]"
                  />
                  <span>Redraw payout order using Fair Draw tool</span>
                </label>
              </div>
            </div>

            <p className="text-xs text-[var(--muted)]">
              Enabling auto-renew will immediately prompt members to opt in or opt out. The new
              cycle will retain settings ({circle.contribution}, {circle.duration} cadence) and
              launch with only opted-in participants.
            </p>

            <button
              type="button"
              onClick={handleEnable}
              className="inline-flex items-center gap-2 rounded-xl bg-[#4B6B76] px-4 py-2 text-sm font-medium text-white hover:bg-[#3D5A64] transition"
            >
              <RefreshCw size={15} />
              Enable Auto-Renew for Next Cycle
            </button>
          </div>
        )}
      </div>
    );
  }

  // 2. Member & Organizer Active Renewal View
  return (
    <div className="rounded-2xl border border-[#4B6B76]/30 bg-[var(--content)] p-6 shadow-sm space-y-6">
      {/* Top Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-[var(--ov-08)] pb-4">
        <div className="flex items-center gap-3">
          <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[#4B6B76]/15 text-[#4B6B76]">
            <Sparkles size={20} />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h2 className="font-sora font-semibold text-[var(--text)]">
                Next Cycle: {config?.nextCycleName || getNextCycleName(circle.name)}
              </h2>
              <span className="rounded-full bg-emerald-500/10 px-2.5 py-0.5 text-xs font-medium text-emerald-600 dark:text-emerald-400">
                Auto-Renew Active
              </span>
            </div>
            <p className="text-xs text-[var(--muted)]">
              Preserves {circle.contribution} contribution and {circle.duration} cadence.
            </p>
          </div>
        </div>

        {isOrganizer && (
          <button
            type="button"
            onClick={handleDisable}
            className="text-xs text-[var(--muted)] hover:text-rose-500 transition self-start sm:self-auto"
          >
            Turn off auto-renew
          </button>
        )}
      </div>

      {/* Member Opt-In Banner */}
      <div className="rounded-xl border border-[var(--ov-10)] bg-[var(--background)] p-4">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <span className="text-xs font-semibold uppercase tracking-wider text-[#4B6B76]">
              Your Participation
            </span>
            <p className="text-sm font-medium text-[var(--text)] mt-0.5">
              {userStatus === "opted_in"
                ? "You have opted in to the next cycle."
                : userStatus === "opted_out"
                ? "You opted out of the next cycle."
                : "Would you like to participate in the next cycle?"}
            </p>
          </div>

          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => handleOptIn("opted_in")}
              className={`inline-flex items-center gap-1.5 rounded-lg px-3.5 py-2 text-xs font-semibold transition ${
                userStatus === "opted_in"
                  ? "bg-emerald-600 text-white shadow-sm"
                  : "bg-[var(--ov-08)] text-[var(--text)] hover:bg-emerald-500/15 hover:text-emerald-600"
              }`}
            >
              <Check size={14} />
              Opt In
            </button>
            <button
              type="button"
              onClick={() => handleOptIn("opted_out")}
              className={`inline-flex items-center gap-1.5 rounded-lg px-3.5 py-2 text-xs font-semibold transition ${
                userStatus === "opted_out"
                  ? "bg-rose-600 text-white shadow-sm"
                  : "bg-[var(--ov-08)] text-[var(--muted)] hover:bg-rose-500/15 hover:text-rose-600"
              }`}
            >
              <X size={14} />
              Opt Out
            </button>
          </div>
        </div>
      </div>

      {/* Opt-In Roster & Progress */}
      <div className="space-y-3">
        <div className="flex items-center justify-between text-xs text-[var(--muted)]">
          <span className="flex items-center gap-1.5">
            <Users size={14} />
            Member Responses ({optedInCount} of {totalCount} opted in)
          </span>
          <span>{Math.round((optedInCount / (totalCount || 1)) * 100)}% opted in</span>
        </div>

        {/* Progress Bar */}
        <div className="h-2 w-full overflow-hidden rounded-full bg-[var(--ov-08)]">
          <div
            className="h-full bg-emerald-500 transition-all duration-300"
            style={{ width: `${(optedInCount / (totalCount || 1)) * 100}%` }}
          />
        </div>

        {/* Member List */}
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-2 pt-2">
          {circle.participants.map((p) => {
            const status = config?.optIns[p.address.toLowerCase()] ?? "pending";
            const isYou = p.address.toLowerCase() === currentWallet.toLowerCase();
            return (
              <div
                key={p.address}
                className="flex items-center justify-between rounded-lg border border-[var(--ov-08)] bg-[var(--background)] px-3 py-2 text-xs"
              >
                <span className="font-mono text-[var(--text)]">
                  {truncate(p.address)}
                  {isYou && <span className="ml-1 text-[#4B6B76] font-sans font-medium">(you)</span>}
                </span>
                {status === "opted_in" ? (
                  <span className="inline-flex items-center gap-1 text-emerald-600 dark:text-emerald-400 font-medium">
                    <Check size={12} /> Opted In
                  </span>
                ) : status === "opted_out" ? (
                  <span className="inline-flex items-center gap-1 text-rose-500 font-medium">
                    <X size={12} /> Opted Out
                  </span>
                ) : (
                  <span className="inline-flex items-center gap-1 text-amber-500 font-medium">
                    <Clock size={12} /> Pending
                  </span>
                )}
              </div>
            );
          })}
        </div>
      </div>

      {/* Organizer Controls & Launch */}
      {isOrganizer && (
        <div className="border-t border-[var(--ov-08)] pt-4 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div className="flex items-center gap-4 text-xs text-[var(--muted)]">
            <label className="flex items-center gap-2 cursor-pointer text-[var(--text)]">
              <input
                type="checkbox"
                checked={redrawOrder}
                onChange={(e) => setRedrawOrder(e.target.checked)}
                className="h-4 w-4 rounded border-gray-300 text-[#4B6B76] focus:ring-[#4B6B76]"
              />
              <span>Redraw payout order for new cycle</span>
            </label>

            {redrawOrder && (
              <button
                type="button"
                onClick={() => setShowDrawModal(true)}
                className="inline-flex items-center gap-1 text-[#4B6B76] hover:underline"
              >
                <Dices size={13} />
                Preview Fair Draw
              </button>
            )}
          </div>

          <button
            type="button"
            disabled={optedInCount < 2 || isLaunching}
            onClick={handleLaunchNextCycle}
            className="inline-flex items-center justify-center gap-2 rounded-xl bg-[#4B6B76] px-5 py-2.5 text-sm font-semibold text-white shadow-sm transition hover:bg-[#3D5A64] disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <RefreshCw size={15} className={isLaunching ? "animate-spin" : ""} />
            Launch Next Cycle ({optedInCount} members)
          </button>
        </div>
      )}

      {/* Payout Draw Modal */}
      {showDrawModal && (
        <PayoutDrawModal
          open={showDrawModal}
          onClose={() => setShowDrawModal(false)}
          circleId={`${circle.id}-next`}
          participantAddresses={optedInCount >= 2 ? optedInAddresses : participantAddresses}
          onDrawFinalized={(draw: PayoutDraw) => {
            showToast({
              title: "Fair Draw Simulated",
              message: `Simulated order generated with seed ${draw.seed.slice(0, 8)}…`,
              variant: "success",
            });
            setShowDrawModal(false);
          }}
        />
      )}
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";
import Link from "next/link";
import {
  X,
  Columns,
  DollarSign,
  Clock,
  Users,
  Shield,
  Zap,
  ArrowRight,
  TrendingUp,
  RotateCcw,
  Check,
  type LucideIcon,
} from "lucide-react";
import { useCircleComparison } from "@/contexts/CircleComparisonContext";
import { MOCK_CIRCLES, DiscoverCircle, truncateAddress, CURRENT_WALLET } from "@/data/circles";
import CopyButton from "@/components/ui/CopyButton";
import AutoPayStatusBadge from "@/components/circles/AutoPayStatusBadge";
import { useFocusTrap } from "@/hooks/useFocusTrap";

interface CircleComparisonProps {
  allCircles?: DiscoverCircle[];
  onJoinCircle?: (circle: DiscoverCircle) => void;
}

/** Parses numeric contribution amount from string like "50 USDT" */
function parseAmount(str: string): number {
  const match = str.match(/([\d.]+)/);
  return match ? parseFloat(match[1]) : 0;
}

export default function CircleComparison({
  allCircles = MOCK_CIRCLES,
  onJoinCircle,
}: CircleComparisonProps) {
  const {
    selectedCircleIds,
    isComparisonOpen,
    closeComparison,
    removeCircle,
    clearSelection,
    toggleCircle,
  } = useCircleComparison();

  const containerRef = useRef<HTMLDivElement>(null);
  useFocusTrap(containerRef, isComparisonOpen, closeComparison);

  useEffect(() => {
    function handleKeyDown(e: KeyboardEvent) {
      if (e.key === "Escape") closeComparison();
    }
    if (isComparisonOpen) {
      document.addEventListener("keydown", handleKeyDown);
      return () => document.removeEventListener("keydown", handleKeyDown);
    }
  }, [isComparisonOpen, closeComparison]);

  if (!isComparisonOpen) return null;

  const selectedCircles = allCircles.filter((c) =>
    selectedCircleIds.includes(c.id)
  );

  const handleSelectRecommended = () => {
    clearSelection();
    // Select first 3 available circles
    allCircles.slice(0, 3).forEach((c) => toggleCircle(c.id));
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-6 bg-black/75 backdrop-blur-md animate-fade-in"
      role="dialog"
      aria-modal="true"
      aria-labelledby="comparison-dialog-title"
    >
      <div
        ref={containerRef}
        className="relative w-full max-w-5xl max-h-[92vh] flex flex-col rounded-3xl bg-[var(--modal)] border border-[var(--ov-14)] shadow-2xl overflow-hidden text-[var(--text)]"
      >
        {/* Header Row */}
        <div className="flex items-center justify-between px-6 py-5 border-b border-[var(--ov-0f)] shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-[#4B6B76]/15 text-[#4B6B76] flex items-center justify-center">
              <Columns size={20} aria-hidden="true" />
            </div>
            <div>
              <h2
                id="comparison-dialog-title"
                className="text-xl font-bold font-sora text-[var(--text)]"
              >
                Compare Savings Circles
              </h2>
              <p className="text-xs text-[var(--muted)]">
                Side-by-side comparison of pool terms, contribution amounts, and payout schedules.
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            {selectedCircles.length > 0 && (
              <button
                type="button"
                onClick={clearSelection}
                className="hidden sm:inline-flex items-center gap-1 px-3 py-1.5 rounded-xl border border-[var(--ov-10)] text-xs text-[var(--muted)] hover:text-[var(--text)] hover:bg-[var(--ov-08)] transition-colors"
              >
                <RotateCcw size={13} aria-hidden="true" />
                <span>Clear All</span>
              </button>
            )}
            <button
              type="button"
              onClick={closeComparison}
              className="p-2 rounded-full text-[var(--muted)] hover:text-[var(--text)] hover:bg-[var(--ov-0a)] transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76]"
              aria-label="Close comparison"
            >
              <X size={20} aria-hidden="true" />
            </button>
          </div>
        </div>

        {/* Modal Body */}
        <div className="flex-1 overflow-y-auto p-4 sm:p-6">
          {selectedCircles.length < 2 ? (
            /* Empty state when fewer than 2 circles are selected */
            <div className="flex flex-col items-center justify-center py-16 text-center">
              <div className="w-16 h-16 rounded-2xl bg-[var(--ov-08)] border border-[var(--ov-10)] flex items-center justify-center text-[var(--muted)] mb-4">
                <Columns size={30} aria-hidden="true" />
              </div>
              <h3 className="text-lg font-bold font-sora text-[var(--text)]">
                Select at least 2 circles to compare
              </h3>
              <p className="text-xs text-[var(--muted)] mt-1.5 max-w-md">
                You currently have {selectedCircles.length} circle selected. Check the &ldquo;Compare&rdquo; box on circle cards in the discovery page to compare up to 3 circles side by side.
              </p>

              <div className="mt-6 flex flex-wrap items-center justify-center gap-3">
                <button
                  type="button"
                  onClick={handleSelectRecommended}
                  className="px-5 py-2.5 rounded-xl bg-[#4B6B76] hover:bg-[#3D5A64] text-white text-xs font-semibold transition-colors shadow-sm"
                >
                  Select Sample Circles
                </button>
                <button
                  type="button"
                  onClick={closeComparison}
                  className="px-4 py-2.5 rounded-xl border border-[var(--ov-14)] text-xs font-medium text-[var(--text)] hover:bg-[var(--ov-08)] transition-colors"
                >
                  Back to Discovery
                </button>
              </div>
            </div>
          ) : (
            /* Comparison Grid Table */
            <div className="overflow-x-auto">
              <div
                className="grid gap-4 min-w-[620px]"
                style={{
                  gridTemplateColumns: `180px repeat(${selectedCircles.length}, minmax(200px, 1fr))`,
                }}
              >
                {/* Column Headers (Circle identity) */}
                <div className="flex flex-col justify-end pb-3 text-xs font-bold uppercase tracking-wider text-[var(--muted)]">
                  Feature / Metric
                </div>

                {selectedCircles.map((circle) => {
                  const isUserMember = circle.members.includes(CURRENT_WALLET);
                  const isFull = circle.members.length >= circle.totalSlots;
                  return (
                    <div
                      key={circle.id}
                      className="relative p-4 rounded-2xl bg-[var(--content)] border border-[var(--ov-10)] flex flex-col justify-between"
                    >
                      <button
                        type="button"
                        onClick={() => removeCircle(circle.id)}
                        className="absolute top-3 right-3 p-1 rounded-full text-[var(--muted)] hover:text-[var(--text)] hover:bg-[var(--ov-0a)] transition-colors"
                        title="Remove from comparison"
                        aria-label={`Remove ${circle.name}`}
                      >
                        <X size={15} aria-hidden="true" />
                      </button>

                      <div>
                        <div className="flex items-center gap-1.5 mb-1 pr-6">
                          <AutoPayStatusBadge circleId={circle.id} />
                          {isUserMember && (
                            <span className="text-[10px] font-semibold px-2 py-0.5 rounded-full bg-blue-500/10 text-blue-500">
                              Joined
                            </span>
                          )}
                        </div>

                        <Link
                          href={`/dashboard/circles/${circle.id}`}
                          onClick={closeComparison}
                          className="text-base font-bold font-sora text-[var(--text)] hover:underline block truncate"
                        >
                          {circle.name}
                        </Link>

                        <div className="flex items-center gap-1.5 text-xs text-[var(--muted)] mt-1">
                          <span>by</span>
                          <span className="font-mono text-[11px] truncate max-w-[100px]">
                            {truncateAddress(circle.creator)}
                          </span>
                          <CopyButton value={circle.creator} />
                        </div>
                      </div>

                      <div className="mt-4 pt-3 border-t border-[var(--ov-08)]">
                        {isUserMember ? (
                          <Link
                            href={`/dashboard/circles/${circle.id}`}
                            onClick={closeComparison}
                            className="w-full flex items-center justify-center gap-1.5 py-2 px-3 rounded-xl bg-[var(--ov-0a)] hover:bg-[var(--ov-14)] text-xs font-semibold text-[var(--text)] transition-colors"
                          >
                            <span>Open Details</span>
                            <ArrowRight size={13} aria-hidden="true" />
                          </Link>
                        ) : (
                          <button
                            type="button"
                            disabled={isFull || circle.closed}
                            onClick={() => {
                              closeComparison();
                              onJoinCircle?.(circle);
                            }}
                            className={`w-full py-2 px-3 rounded-xl text-xs font-semibold transition-colors ${
                              isFull || circle.closed
                                ? "bg-[var(--ov-08)] text-[var(--muted)] cursor-not-allowed"
                                : "bg-[#4B6B76] hover:bg-[#3D5A64] text-white cursor-pointer"
                            }`}
                          >
                            {circle.closed
                              ? "Closed"
                              : isFull
                              ? "Circle Full"
                              : "Join Circle"}
                          </button>
                        )}
                      </div>
                    </div>
                  );
                })}

                {/* Row 1: Contribution Amount */}
                <div className="py-3.5 px-2 flex items-center gap-2 border-t border-[var(--ov-08)] text-xs font-semibold text-[var(--muted)]">
                  <DollarSign size={15} className="text-[#4B6B76]" aria-hidden="true" />
                  <span>Contribution</span>
                </div>
                {selectedCircles.map((circle) => (
                  <div
                    key={circle.id}
                    className="py-3.5 px-4 flex items-center border-t border-[var(--ov-08)] font-sora font-bold text-sm text-[var(--text)]"
                  >
                    {circle.contribution}
                  </div>
                ))}

                {/* Row 2: Round Duration */}
                <div className="py-3.5 px-2 flex items-center gap-2 border-t border-[var(--ov-08)] text-xs font-semibold text-[var(--muted)]">
                  <Clock size={15} className="text-[#4B6B76]" aria-hidden="true" />
                  <span>Round Duration</span>
                </div>
                {selectedCircles.map((circle) => (
                  <div
                    key={circle.id}
                    className="py-3.5 px-4 flex items-center border-t border-[var(--ov-08)] text-xs font-medium text-[var(--text)]"
                  >
                    {circle.duration}
                  </div>
                ))}

                {/* Row 3: Estimated Pool Pot */}
                <div className="py-3.5 px-2 flex items-center gap-2 border-t border-[var(--ov-08)] text-xs font-semibold text-[var(--muted)]">
                  <TrendingUp size={15} className="text-[#4B6B76]" aria-hidden="true" />
                  <span>Estimated Total Pot</span>
                </div>
                {selectedCircles.map((circle) => {
                  const pot = parseAmount(circle.contribution) * circle.totalSlots;
                  return (
                    <div
                      key={circle.id}
                      className="py-3.5 px-4 flex items-center border-t border-[var(--ov-08)] text-xs font-bold text-emerald-500 font-mono"
                    >
                      {pot > 0 ? `${pot} USDT` : "—"}
                    </div>
                  );
                })}

                {/* Row 4: Participants & Fill Percentage */}
                <div className="py-3.5 px-2 flex items-center gap-2 border-t border-[var(--ov-08)] text-xs font-semibold text-[var(--muted)]">
                  <Users size={15} className="text-[#4B6B76]" aria-hidden="true" />
                  <span>Participants & Slots</span>
                </div>
                {selectedCircles.map((circle) => {
                  const fillPct = Math.round(
                    (circle.members.length / circle.totalSlots) * 100
                  );
                  return (
                    <div
                      key={circle.id}
                      className="py-3.5 px-4 flex flex-col justify-center gap-1.5 border-t border-[var(--ov-08)]"
                    >
                      <div className="flex items-center justify-between text-xs">
                        <span className="font-semibold text-[var(--text)]">
                          {circle.members.length} / {circle.totalSlots} members
                        </span>
                        <span className="text-[10px] text-[var(--muted)] font-mono">
                          {fillPct}%
                        </span>
                      </div>
                      <div
                        className="w-full h-1.5 bg-[var(--ov-0a)] rounded-full overflow-hidden"
                        role="progressbar"
                        aria-valuenow={fillPct}
                        aria-valuemin={0}
                        aria-valuemax={100}
                      >
                        <div
                          className="h-full bg-[#4B6B76] rounded-full"
                          style={{ width: `${fillPct}%` }}
                        />
                      </div>
                    </div>
                  );
                })}

                {/* Row 5: Round Progress */}
                <div className="py-3.5 px-2 flex items-center gap-2 border-t border-[var(--ov-08)] text-xs font-semibold text-[var(--muted)]">
                  <Clock size={15} className="text-[#4B6B76]" aria-hidden="true" />
                  <span>Current Round</span>
                </div>
                {selectedCircles.map((circle) => (
                  <div
                    key={circle.id}
                    className="py-3.5 px-4 flex items-center border-t border-[var(--ov-08)] text-xs font-medium text-[var(--text)]"
                  >
                    {circle.currentRound && circle.totalRounds
                      ? `Round ${circle.currentRound} of ${circle.totalRounds}`
                      : "Round 1"}
                  </div>
                ))}

                {/* Row 6: Next Payout */}
                <div className="py-3.5 px-2 flex items-center gap-2 border-t border-[var(--ov-08)] text-xs font-semibold text-[var(--muted)]">
                  <Zap size={15} className="text-[#4B6B76]" aria-hidden="true" />
                  <span>Next Payout</span>
                </div>
                {selectedCircles.map((circle) => (
                  <div
                    key={circle.id}
                    className="py-3.5 px-4 flex items-center border-t border-[var(--ov-08)] text-xs font-medium text-[var(--text)]"
                  >
                    {circle.nextPayout ?? circle.duration}
                  </div>
                ))}

                {/* Row 7: AutoPay Support */}
                <div className="py-3.5 px-2 flex items-center gap-2 border-t border-[var(--ov-08)] text-xs font-semibold text-[var(--muted)]">
                  <Zap size={15} className="text-[#4B6B76]" aria-hidden="true" />
                  <span>AutoPay Capable</span>
                </div>
                {selectedCircles.map((circle) => (
                  <div
                    key={circle.id}
                    className="py-3.5 px-4 flex items-center gap-1.5 border-t border-[var(--ov-08)] text-xs text-emerald-500 font-medium"
                  >
                    <Check size={14} aria-hidden="true" />
                    <span>Enabled</span>
                  </div>
                ))}

                {/* Row 8: Security & Settlement */}
                <div className="py-3.5 px-2 flex items-center gap-2 border-t border-[var(--ov-08)] text-xs font-semibold text-[var(--muted)]">
                  <Shield size={15} className="text-[#4B6B76]" aria-hidden="true" />
                  <span>Settlement Security</span>
                </div>
                {selectedCircles.map((circle) => (
                  <div
                    key={circle.id}
                    className="py-3.5 px-4 flex items-center border-t border-[var(--ov-08)] text-xs text-[var(--muted)]"
                  >
                    Multi-sig Escrow
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Footer info banner */}
        <div className="px-6 py-3.5 bg-[var(--ov-05)] border-t border-[var(--ov-0f)] flex flex-col sm:flex-row items-center justify-between gap-2 text-xs text-[var(--muted)] shrink-0">
          <span>
            Comparing {selectedCircles.length} of 3 maximum circles.
          </span>
          <button
            type="button"
            onClick={closeComparison}
            className="px-4 py-1.5 rounded-xl border border-[var(--ov-10)] hover:bg-[var(--ov-0a)] text-[var(--text)] transition-colors"
          >
            Close Comparison
          </button>
        </div>
      </div>
    </div>
  );
}

import { AlertTriangle, HeartPulse, ShieldCheck } from "lucide-react";
import type { CircleHealthScore } from "@/lib/circleHealth";

const styles = {
  healthy: {
    icon: ShieldCheck,
    className: "bg-green-500/10 text-green-700 dark:text-green-400",
  },
  attention: {
    icon: HeartPulse,
    className: "bg-amber-500/10 text-amber-700 dark:text-amber-400",
  },
  risk: {
    icon: AlertTriangle,
    className: "bg-red-500/10 text-red-700 dark:text-red-400",
  },
} as const;

export default function CircleHealthIndicator({ health }: { health: CircleHealthScore }) {
  const { icon: Icon, className } = styles[health.level];
  const tooltip = `Health score ${health.score}%. Driven by ${Math.round(health.onTimeRate * 100)}% on-time contributions, ${health.missedContributions} missed contribution${health.missedContributions === 1 ? "" : "s"}, ${Math.round(health.payoutReliability * 100)}% payout reliability, and ${health.disputes} recorded dispute${health.disputes === 1 ? "" : "s"}.`;

  return (
    <span className="group relative inline-flex max-w-full" tabIndex={0} title={tooltip} aria-label={tooltip}>
      <span className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-semibold ${className}`}>
        <Icon size={14} aria-hidden="true" />
        <span>{health.label}</span>
        <span className="font-mono">{health.score}</span>
      </span>
      <span role="tooltip" className="pointer-events-none absolute left-0 top-full z-20 mt-2 hidden w-64 rounded-lg bg-[var(--text)] px-3 py-2 text-left text-xs font-normal leading-5 text-[var(--bg)] shadow-lg group-hover:block group-focus:block">
        {tooltip}
      </span>
    </span>
  );
}

"use client";

import { useEffect, useState } from "react";
import {
    CIRCLE_IMAGES_UPDATED_EVENT,
    getCircleImages,
    getFallbackCircleImage,
    type CircleImageKind,
} from "@/lib/circleImages";

interface CircleImageProps {
    circleId: string;
    circleName: string;
    kind: CircleImageKind;
    className?: string;
    alt?: string;
}

export default function CircleImage({ circleId, circleName, kind, className, alt }: CircleImageProps) {
    const [src, setSrc] = useState(() => getFallbackCircleImage(circleId, circleName));

    useEffect(() => {
        const sync = () => setSrc(getCircleImages(circleId)[kind] ?? getFallbackCircleImage(circleId, circleName));
        sync();
        window.addEventListener(CIRCLE_IMAGES_UPDATED_EVENT, sync);
        window.addEventListener("storage", sync);
        return () => {
            window.removeEventListener(CIRCLE_IMAGES_UPDATED_EVENT, sync);
            window.removeEventListener("storage", sync);
        };
    }, [circleId, circleName, kind]);

    return <img src={src} alt={alt ?? `${circleName} ${kind}`} loading="lazy" decoding="async" className={className} />;
}

"use client";

import { useEffect, useRef, useState, useSyncExternalStore } from "react";
import { ImagePlus, RotateCcw, Trash2, Upload } from "lucide-react";
import { CIRCLE_IMAGES_UPDATED_EVENT, getCircleImages, removeCircleImage, saveCircleImage, type CircleImageKind } from "@/lib/circleImages";
import { useToast } from "@/components/ui/Toast";

const MAX_FILE_SIZE = 5 * 1024 * 1024;
const ACCEPTED_TYPES = ["image/jpeg", "image/png", "image/webp"];

interface CircleImageUploaderProps {
    circleId: string;
    kind: CircleImageKind;
    label: string;
    description: string;
    aspectRatio: number;
}

export default function CircleImageUploader({ circleId, kind, label, description, aspectRatio }: CircleImageUploaderProps) {
    const inputRef = useRef<HTMLInputElement>(null);
    const imageRef = useRef<HTMLImageElement>(null);
    const savedImage = useSyncExternalStore(
        (onChange) => {
            const sync = () => onChange();
            window.addEventListener(CIRCLE_IMAGES_UPDATED_EVENT, sync);
            window.addEventListener("storage", sync);
            return () => {
                window.removeEventListener(CIRCLE_IMAGES_UPDATED_EVENT, sync);
                window.removeEventListener("storage", sync);
            };
        },
        () => getCircleImages(circleId)[kind] ?? null,
        () => null,
    );
    const [source, setSource] = useState<string | null>(null);
    const [zoom, setZoom] = useState(1);
    const [error, setError] = useState<string | null>(null);
    const { showToast } = useToast();

    useEffect(() => {
        return () => {
            if (source) URL.revokeObjectURL(source);
        };
    }, [source]);

    function chooseFile(file: File | null) {
        setError(null);
        if (!file) return;
        if (!ACCEPTED_TYPES.includes(file.type)) {
            setError("Use a JPG, PNG, or WebP image.");
            return;
        }
        if (file.size > MAX_FILE_SIZE) {
            setError("Image must be 5 MB or smaller.");
            return;
        }
        if (source) URL.revokeObjectURL(source);
        setSource(URL.createObjectURL(file));
        setZoom(1);
    }

    function cropAndSave() {
        const image = imageRef.current;
        if (!image || !source) return;
        const outputWidth = kind === "cover" ? 1200 : 800;
        const outputHeight = Math.round(outputWidth / aspectRatio);
        const canvas = document.createElement("canvas");
        canvas.width = outputWidth;
        canvas.height = outputHeight;
        const context = canvas.getContext("2d");
        if (!context || !image.naturalWidth || !image.naturalHeight) return;

        const cropRatio = outputWidth / outputHeight;
        const imageRatio = image.naturalWidth / image.naturalHeight;
        const baseScale = imageRatio > cropRatio ? image.naturalHeight / outputHeight : image.naturalWidth / outputWidth;
        const cropWidth = outputWidth * baseScale / zoom;
        const cropHeight = outputHeight * baseScale / zoom;
        const cropX = (image.naturalWidth - cropWidth) / 2;
        const cropY = (image.naturalHeight - cropHeight) / 2;
        context.drawImage(image, cropX, cropY, cropWidth, cropHeight, 0, 0, outputWidth, outputHeight);
        const dataUrl = canvas.toDataURL("image/jpeg", 0.86);
        saveCircleImage(circleId, kind, dataUrl);
        setSource(null);
        showToast({ title: `${label} saved`, variant: "success" });
    }

    function removeSavedImage() {
        removeCircleImage(circleId, kind);
        showToast({ title: `${label} removed`, variant: "success" });
    }

    return (
        <div className="space-y-3 rounded-xl border border-[var(--ov-14)] bg-[var(--ov-05)] p-4">
            <div className="flex items-start justify-between gap-3">
                <div>
                    <h3 className="text-sm font-semibold text-[var(--text)]">{label}</h3>
                    <p className="mt-1 text-xs text-[var(--muted)]">{description}</p>
                </div>
                {savedImage && !source && (
                    <button type="button" onClick={removeSavedImage} className="inline-flex items-center gap-1 text-xs text-[var(--muted)] hover:text-red-500" aria-label={`Remove ${label}`}>
                        <Trash2 size={13} aria-hidden="true" /> Remove
                    </button>
                )}
            </div>

            {source ? (
                <div className="space-y-3">
                    <div className="overflow-hidden rounded-lg bg-black/20" style={{ aspectRatio }}>
                        <img ref={imageRef} src={source} alt="Crop preview" className="h-full w-full object-cover" style={{ transform: `scale(${zoom})` }} />
                    </div>
                    <div className="flex items-center gap-3">
                        <label htmlFor={`${kind}-zoom`} className="text-xs text-[var(--muted)]">Zoom</label>
                        <input id={`${kind}-zoom`} type="range" min="1" max="3" step="0.05" value={zoom} onChange={(event) => setZoom(Number(event.target.value))} className="w-full accent-[#4B6B76]" />
                    </div>
                    <div className="flex flex-wrap gap-2">
                        <button type="button" onClick={cropAndSave} className="inline-flex items-center gap-2 rounded-lg bg-[#4B6B76] px-3 py-2 text-xs font-medium text-white hover:bg-[#3D5A64]"><ImagePlus size={14} aria-hidden="true" /> Use this crop</button>
                        <button type="button" onClick={() => setSource(null)} className="inline-flex items-center gap-2 rounded-lg border border-[var(--ov-14)] px-3 py-2 text-xs font-medium text-[var(--text)] hover:bg-[var(--ov-0a)]"><RotateCcw size={14} aria-hidden="true" /> Cancel</button>
                    </div>
                </div>
            ) : (
                <div className="flex items-center gap-3">
                    {savedImage && <img src={savedImage} alt="" className="h-16 w-24 rounded-lg object-cover" loading="lazy" />}
                    <button type="button" onClick={() => inputRef.current?.click()} className="inline-flex items-center gap-2 rounded-lg border border-dashed border-[var(--ov-1a)] px-3 py-2 text-xs font-medium text-[var(--text)] hover:bg-[var(--ov-0a)]"><Upload size={14} aria-hidden="true" /> {savedImage ? "Replace image" : "Upload image"}</button>
                    <input ref={inputRef} type="file" accept={ACCEPTED_TYPES.join(",")} className="sr-only" onChange={(event) => { chooseFile(event.target.files?.[0] ?? null); event.target.value = ""; }} />
                </div>
            )}
            {error && <p role="alert" className="text-xs font-medium text-red-600 dark:text-red-400">{error}</p>}
        </div>
    );
}

"use client";

import { Columns, X, ArrowRight, Check } from "lucide-react";
import { useCircleComparison } from "@/contexts/CircleComparisonContext";
import { MOCK_CIRCLES, DiscoverCircle } from "@/data/circles";

interface ComparisonFloatingBarProps {
  allCircles?: DiscoverCircle[];
}

export default function ComparisonFloatingBar({
  allCircles = MOCK_CIRCLES,
}: ComparisonFloatingBarProps) {
  const {
    selectedCircleIds,
    removeCircle,
    clearSelection,
    openComparison,
    maxLimit,
  } = useCircleComparison();

  if (selectedCircleIds.length === 0) return null;

  const selectedCircles = allCircles.filter((c) =>
    selectedCircleIds.includes(c.id)
  );

  const canCompare = selectedCircleIds.length >= 2;

  return (
    <aside
      aria-label="Circle comparison bar"
      className="fixed bottom-6 left-1/2 -translate-x-1/2 z-40 w-[94%] max-w-2xl bg-[var(--modal)] border border-[#4B6B76]/50 shadow-[0_12px_40px_rgba(0,0,0,0.35)] rounded-2xl p-3 sm:p-4 animate-fade-up"
    >
      <div className="flex flex-col sm:flex-row items-center justify-between gap-3">
        {/* Selected circle pills & counter */}
        <div className="flex items-center gap-2 overflow-x-auto w-full sm:w-auto scrollbar-none py-1">
          <div className="flex items-center gap-1.5 px-2.5 py-1 rounded-lg bg-[var(--ov-0a)] border border-[var(--ov-10)] shrink-0">
            <Columns size={14} className="text-[#4B6B76]" aria-hidden="true" />
            <span className="text-xs font-bold font-sora text-[var(--text)]">
              {selectedCircleIds.length}/{maxLimit}
            </span>
          </div>

          <div className="flex items-center gap-1.5 min-w-0">
            {selectedCircles.map((circle) => (
              <span
                key={circle.id}
                className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg bg-[var(--content)] border border-[var(--ov-10)] text-xs text-[var(--text)] font-medium max-w-[140px] truncate group"
              >
                <span className="truncate">{circle.name}</span>
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    removeCircle(circle.id);
                  }}
                  className="p-0.5 rounded-full hover:bg-[var(--ov-14)] text-[var(--muted)] hover:text-[var(--text)] focus-visible:outline-none"
                  aria-label={`Remove ${circle.name} from comparison`}
                >
                  <X size={12} aria-hidden="true" />
                </button>
              </span>
            ))}
          </div>
        </div>

        {/* Action buttons */}
        <div className="flex items-center gap-2 w-full sm:w-auto justify-end shrink-0">
          <button
            type="button"
            onClick={clearSelection}
            className="px-3 py-2 text-xs font-medium text-[var(--muted)] hover:text-[var(--text)] hover:bg-[var(--ov-08)] rounded-xl transition-colors focus-visible:outline-none"
          >
            Clear all
          </button>

          <button
            type="button"
            onClick={openComparison}
            disabled={!canCompare}
            className={`flex items-center gap-1.5 px-4 py-2 text-xs font-semibold rounded-xl transition-all shadow-md focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76] ${
              canCompare
                ? "bg-[#4B6B76] hover:bg-[#3D5A64] text-white shadow-[#4B6B76]/20 cursor-pointer"
                : "bg-[var(--ov-0a)] text-[var(--muted)] cursor-not-allowed opacity-60"
            }`}
          >
            <span>
              {canCompare
                ? `Compare (${selectedCircleIds.length})`
                : "Select 1 more"}
            </span>
            <ArrowRight size={13} aria-hidden="true" />
          </button>
        </div>
      </div>
    </aside>
  );
}

