"use client";

import { useState, useRef, useEffect } from "react";
import { MoreHorizontal, Trash2, Pause, Play, Ban } from "lucide-react";

interface ModerationMenuProps {
  isOrganizer: boolean;
  isMuted: boolean;
  messageId: string;
  authorAddress: string;
  onRemoveMessage: (messageId: string, authorAddress: string, reason?: string) => void;
  onMuteParticipant: (address: string, reason?: string) => void;
  onUnmuteParticipant?: (address: string) => void;
}

export function ModerationMenu({
  isOrganizer,
  isMuted,
  messageId,
  authorAddress,
  onRemoveMessage,
  onMuteParticipant,
  onUnmuteParticipant,
}: ModerationMenuProps) {
  const [isOpen, setIsOpen] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  if (!isOrganizer) return null;

  const handleRemove = () => {
    onRemoveMessage(messageId, authorAddress);
    setIsOpen(false);
  };

  const handleMuteToggle = () => {
    if (isMuted && onUnmuteParticipant) {
      onUnmuteParticipant(authorAddress);
    } else {
      onMuteParticipant(authorAddress);
    }
    setIsOpen(false);
  };

  return (
    <div className="relative" ref={menuRef}>
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="flex h-6 w-6 items-center justify-center rounded hover:bg-[var(--hover)] text-[var(--faint)] hover:text-[var(--text)] transition-colors"
        aria-label="Moderation options"
        aria-expanded={isOpen}
      >
        <MoreHorizontal className="h-4 w-4" />
      </button>

      {isOpen && (
        <div className="absolute right-0 top-full z-50 mt-1 w-48 rounded-lg border border-[var(--border)] bg-[var(--popover)] py-1 shadow-lg">
          <button
            onClick={handleRemove}
            className="flex w-full items-center gap-2 px-3 py-2 text-sm text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20"
          >
            <Trash2 className="h-4 w-4" />
            Remove message
          </button>
          <button
            onClick={handleMuteToggle}
            className={`flex w-full items-center gap-2 px-3 py-2 text-sm hover:bg-[var(--hover)] ${
              isMuted ? "text-green-500" : "text-[var(--text)]"
            }`}
          >
            {isMuted ? <Play className="h-4 w-4" /> : <Pause className="h-4 w-4" />}
            {isMuted ? "Unmute participant" : "Mute participant"}
          </button>
        </div>
      )}
    </div>
  );
}

/**
 * Placeholder shown for removed messages
 */
export function RemovedMessagePlaceholder({ removedBy }: { removedBy?: string }) {
  return (
    <div className="rounded-lg border border-dashed border-[var(--border)] bg-[var(--ov-05)] px-4 py-2">
      <p className="text-xs italic text-[var(--faint)]">
        This message was removed by an organizer
        {removedBy && <span className="text-[var(--muted)]"> ({removedBy.slice(0, 6)}...{removedBy.slice(-4)})</span>}
      </p>
    </div>
  );
}

"use client";

import { useState } from "react";

/**
 * Types — adjust these to match your actual Circle/Member types
 * if you already have them defined elsewhere (e.g. types/circle.ts).
 * Feel free to delete these and import the real ones instead.
 */
export interface CircleMember {
  address: string;
  displayName?: string;
  role?: CircleRole;
}

export type CircleRole = "organizer" | "co-organizer" | "participant";

export interface Circle {
  id: string;
  creatorAddress: string;
  members: CircleMember[];
  status: "active" | "closed";
}

interface OrganizerControlsProps {
  circle: Circle;
  connectedAddress?: string | null;
  onRemoveMember: (address: string) => Promise<void> | void;
  onChangeRole: (address: string, role: CircleRole) => Promise<void> | void;
  onCloseCircle: () => Promise<void> | void;
  onExtendRound: (extraDays: number) => Promise<void> | void;
}

/**
 * Small helper for case-insensitive address comparison.
 */
function isSameAddress(a?: string | null, b?: string | null) {
  if (!a || !b) return false;
  return a.toLowerCase() === b.toLowerCase();
}

/**
 * A two-step confirm wrapper. First click arms the action and shows
 * a confirm prompt; second click (within the same render) fires it.
 * Satisfies "All destructive actions require a second confirmation step".
 */
function useConfirm() {
  const [armedKey, setArmedKey] = useState<string | null>(null);

  function requestConfirm(key: string) {
    setArmedKey(key);
  }

  function cancel() {
    setArmedKey(null);
  }

  function isArmed(key: string) {
    return armedKey === key;
  }

  return { requestConfirm, cancel, isArmed };
}

/**
 * Inline spinner shown while a transaction is pending.
 */
function Spinner() {
  return (
    <span
      aria-hidden="true"
      className="inline-block h-3 w-3 animate-spin rounded-full border-2 border-current border-t-transparent"
    />
  );
}

export function OrganizerControls({
  circle,
  connectedAddress,
  onRemoveMember,
  onChangeRole,
  onCloseCircle,
  onExtendRound,
}: OrganizerControlsProps) {
  const currentMember = circle.members.find((member) => isSameAddress(member.address, connectedAddress));
  const isOrganizer = isSameAddress(connectedAddress, circle.creatorAddress);
  const canManageCircle = isOrganizer || currentMember?.role === "co-organizer";

  const [showCloseModal, setShowCloseModal] = useState(false);
  const [extendDays, setExtendDays] = useState(7);
  const [busy, setBusy] = useState(false);
  const removeConfirm = useConfirm();
  const roleConfirm = useConfirm();

  // Read-only participants see nothing from this component.
  if (!canManageCircle) {
    return null;
  }

  async function handleRemove(address: string) {
    if (busy) return;
    setBusy(true);
    try {
      await onRemoveMember(address);
    } finally {
      setBusy(false);
      removeConfirm.cancel();
    }
  }

  async function handleRoleChange(address: string, role: CircleRole) {
    if (busy) return;
    setBusy(true);
    try {
      await onChangeRole(address, role);
    } finally {
      setBusy(false);
      roleConfirm.cancel();
    }
  }

  async function handleConfirmedClose() {
    if (busy) return;
    setBusy(true);
    try {
      await onCloseCircle();
    } finally {
      setBusy(false);
      setShowCloseModal(false);
    }
  }

  async function handleExtend() {
    if (busy) return;
    setBusy(true);
    try {
      await onExtendRound(extendDays);
    } finally {
      setBusy(false);
    }
  }

  function requestCloseModal() {
    if (busy) return;
    setShowCloseModal(true);
  }

  function dismissCloseModal() {
    // Block closing the modal while a signing request is in flight.
    if (busy) return;
    setShowCloseModal(false);
  }

  return (
    <div className="rounded-lg border border-amber-300 dark:border-amber-800/60 bg-amber-50 dark:bg-amber-500/10 p-4 space-y-4">
      <div className="flex items-center gap-2">
        <span className="text-xs font-semibold uppercase tracking-wide text-amber-700 dark:text-amber-400">
          Organizer Controls
        </span>
        <span className="rounded-full bg-amber-200 dark:bg-amber-500/20 px-2 py-0.5 text-[10px] font-medium text-amber-800 dark:text-amber-300">
          {isOrganizer ? "You created this circle" : "You help manage this circle"}
        </span>
      </div>

      {/* Member management */}
      <div className="space-y-2">
        <div>
          <h3 className="text-sm font-medium text-gray-700 dark:text-[var(--text)]">
            {isOrganizer ? "Manage Roles" : "Participants"}
          </h3>
          {isOrganizer && (
            <p className="mt-1 text-xs text-gray-500 dark:text-[var(--muted)]">
              Promote a trusted participant to help manage this circle.
            </p>
          )}
        </div>
        <ul className="divide-y divide-gray-200 dark:divide-[var(--border)] rounded-md border border-gray-200 dark:border-[var(--border)] bg-white dark:bg-[var(--content)]">
          {circle.members.map((member) => {
            const isCreator = isSameAddress(member.address, circle.creatorAddress);
            const confirmKey = `remove-${member.address}`;
            const role = isCreator ? "organizer" : member.role ?? "participant";
            const nextRole: CircleRole = role === "co-organizer" ? "participant" : "co-organizer";
            const roleConfirmKey = `role-${member.address}-${nextRole}`;
            return (
              <li
                key={member.address}
                className="flex items-center justify-between px-3 py-2"
              >
                <div className="flex items-center gap-2">
                  <span className="text-sm font-mono text-gray-800 dark:text-[var(--text)]">
                    {member.displayName ?? member.address}
                  </span>
                  {isCreator && (
                    <span className="rounded-full bg-blue-100 dark:bg-blue-500/15 px-2 py-0.5 text-[10px] font-semibold text-blue-700 dark:text-blue-300">
                      Organizer
                    </span>
                  )}
                  {!isCreator && (
                    <span className={`rounded-full px-2 py-0.5 text-[10px] font-semibold ${
                      role === "co-organizer"
                        ? "bg-emerald-100 text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-300"
                        : "bg-gray-100 text-gray-600 dark:bg-white/10 dark:text-[var(--muted)]"
                    }`}>
                      {role === "co-organizer" ? "Co-Organizer" : "Participant"}
                    </span>
                  )}
                </div>

                <div className="flex items-center gap-2">
                {!isCreator && isOrganizer &&
                  (roleConfirm.isArmed(roleConfirmKey) ? (
                    <div className="flex items-center gap-2">
                      <span className="text-xs text-amber-700 dark:text-amber-400">
                        {nextRole === "co-organizer" ? "Promote?" : "Demote?"}
                      </span>
                      <button
                        type="button"
                        disabled={busy}
                        onClick={() => handleRoleChange(member.address, nextRole)}
                        className="inline-flex items-center gap-1.5 rounded bg-[#4B6B76] px-2 py-1 text-xs font-medium text-white hover:bg-[#3D5A64] disabled:cursor-not-allowed disabled:opacity-50"
                      >
                        {busy && <Spinner />}
                        {busy ? "Confirming…" : "Confirm"}
                      </button>
                      <button
                        type="button"
                        disabled={busy}
                        onClick={roleConfirm.cancel}
                        className="rounded border border-gray-300 dark:border-[var(--border)] px-2 py-1 text-xs text-gray-600 dark:text-[var(--muted)] hover:bg-gray-50 dark:hover:bg-[var(--ov-0a)] disabled:cursor-not-allowed disabled:opacity-50"
                      >
                        Cancel
                      </button>
                    </div>
                  ) : (
                    <button
                      type="button"
                      disabled={busy}
                      onClick={() => roleConfirm.requestConfirm(roleConfirmKey)}
                      className="rounded border border-[#4B6B76]/50 px-2 py-1 text-xs font-medium text-[#4B6B76] hover:bg-[#4B6B76]/10 disabled:cursor-not-allowed disabled:opacity-50"
                    >
                      {nextRole === "co-organizer" ? "Promote" : "Demote"}
                    </button>
                  ))}
                {!isCreator &&
                  (removeConfirm.isArmed(confirmKey) ? (
                    <div className="flex items-center gap-2">
                      <span className="text-xs text-red-600 dark:text-red-400">
                        Remove?
                      </span>
                      <button
                        type="button"
                        disabled={busy}
                        onClick={() => handleRemove(member.address)}
                        className="inline-flex items-center gap-1.5 rounded bg-red-600 px-2 py-1 text-xs font-medium text-white hover:bg-red-700 disabled:cursor-not-allowed disabled:opacity-50"
                      >
                        {busy && <Spinner />}
                        {busy ? "Confirming…" : "Confirm"}
                      </button>
                      <button
                        type="button"
                        disabled={busy}
                        onClick={removeConfirm.cancel}
                        className="rounded border border-gray-300 dark:border-[var(--border)] px-2 py-1 text-xs text-gray-600 dark:text-[var(--muted)] hover:bg-gray-50 dark:hover:bg-[var(--ov-0a)] disabled:cursor-not-allowed disabled:opacity-50"
                      >
                        Cancel
                      </button>
                    </div>
                  ) : (
                    <button
                      type="button"
                      disabled={busy}
                      onClick={() => removeConfirm.requestConfirm(confirmKey)}
                      className="rounded border border-red-300 dark:border-red-800/60 px-2 py-1 text-xs font-medium text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-500/10 disabled:cursor-not-allowed disabled:opacity-50"
                    >
                      Remove
                    </button>
                  ))}
                </div>
              </li>
            );
          })}
        </ul>
      </div>

      {/* Round management */}
      <div className="flex flex-wrap items-center gap-2">
        <label className="text-xs text-gray-600 dark:text-[var(--muted)]" htmlFor="extend-days">
          Extend round by
        </label>
        <input
          id="extend-days"
          type="number"
          min={1}
          max={90}
          value={extendDays}
          disabled={busy}
          onChange={(e) => setExtendDays(Number(e.target.value) || 1)}
          className="w-16 rounded border border-gray-300 dark:border-[var(--border)] bg-white dark:bg-[var(--content)] px-2 py-1 text-xs text-gray-800 dark:text-[var(--text)] disabled:opacity-50"
        />
        <span className="text-xs text-gray-600 dark:text-[var(--muted)]">days</span>
        <button
          type="button"
          disabled={busy}
          onClick={handleExtend}
          className="inline-flex items-center gap-1.5 rounded bg-[#4B6B76] px-3 py-1 text-xs font-medium text-white hover:bg-[#3D5A64] disabled:cursor-not-allowed disabled:opacity-50"
        >
          {busy && <Spinner />}
          {busy ? "Confirming…" : "Extend Round"}
        </button>
      </div>

      {/* Close circle */}
      <div>
        <button
          type="button"
          disabled={busy}
          onClick={requestCloseModal}
          className="rounded border border-red-300 dark:border-red-800/60 px-3 py-1 text-xs font-medium text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-500/10 disabled:cursor-not-allowed disabled:opacity-50"
        >
          Close Circle
        </button>
      </div>

      {showCloseModal && (
        <div
          role="dialog"
          aria-modal="true"
          aria-busy={busy}
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4"
          onClick={dismissCloseModal}
        >
          <div
            className="w-full max-w-sm rounded-lg bg-white dark:bg-[var(--content)] p-4 space-y-3"
            onClick={(e) => e.stopPropagation()}
          >
            <h3 className="text-sm font-semibold text-gray-800 dark:text-[var(--text)]">
              Close this circle?
            </h3>
            <p className="text-xs text-gray-600 dark:text-[var(--muted)]">
              This will end the circle and cannot be undone.
            </p>
            <div className="flex justify-end gap-2">
              <button
                type="button"
                disabled={busy}
                onClick={dismissCloseModal}
                className="rounded border border-gray-300 dark:border-[var(--border)] px-3 py-1 text-xs text-gray-600 dark:text-[var(--muted)] hover:bg-gray-50 dark:hover:bg-[var(--ov-0a)] disabled:cursor-not-allowed disabled:opacity-50"
              >
                Cancel
              </button>
              <button
                type="button"
                disabled={busy}
                onClick={handleConfirmedClose}
                className="inline-flex items-center gap-1.5 rounded bg-red-600 px-3 py-1 text-xs font-medium text-white hover:bg-red-700 disabled:cursor-not-allowed disabled:opacity-50"
              >
                {busy && <Spinner />}
                {busy ? "Confirming…" : "Confirm"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { Dices, Loader2, Lock, RotateCcw, Shuffle, X } from "lucide-react";
import { useFocusTrap } from "@/hooks/useFocusTrap";
import {
  generateSeed,
  getPayoutDraw,
  savePayoutDraw,
  seededShuffle,
  type PayoutDraw,
} from "@/lib/payoutDraw";

interface PayoutDrawModalProps {
  open: boolean;
  onClose: () => void;
  circleId: string;
  participantAddresses: string[];
  onDrawFinalized: (draw: PayoutDraw) => void;
}

function truncate(address: string) {
  return `${address.slice(0, 8)}…${address.slice(-6)}`;
}

const REVEAL_TICKS = 14;
const TICK_MS = 140;

export default function PayoutDrawModal({
  open,
  onClose,
  circleId,
  participantAddresses,
  onDrawFinalized,
}: PayoutDrawModalProps) {
  const dialogRef = useRef<HTMLDivElement>(null);
  const [phase, setPhase] = useState<"idle" | "shuffling" | "done">("idle");
  const [displayOrder, setDisplayOrder] = useState<string[]>(participantAddresses);
  const [finalDraw, setFinalDraw] = useState<PayoutDraw | null>(null);

  useEffect(() => {
    if (open) {
      setPhase("idle");
      setDisplayOrder(participantAddresses);
      setFinalDraw(null);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  const isPending = phase === "shuffling";

  const close = () => {
    if (isPending) {
      if (!window.confirm("A payout draw is in progress. Close anyway?")) return;
    }
    onClose();
  };

  useFocusTrap(dialogRef, open, close);

  if (!open) return null;

  function runDraw() {
    if (isPending) return;
    setPhase("shuffling");
    const seed = generateSeed();
    const finalOrder = seededShuffle(participantAddresses, seed);

    let tick = 0;
    const interval = setInterval(() => {
      tick += 1;
      if (tick < REVEAL_TICKS) {
        // Cosmetic intermediate permutations — the auditable result is `finalOrder`,
        // seeded above, not any of these random reveal frames.
        setDisplayOrder(seededShuffle(participantAddresses, `${seed}-${tick}`));
      } else {
        clearInterval(interval);
        setDisplayOrder(finalOrder);
        const draw: PayoutDraw = {
          circleId,
          order: finalOrder,
          seed,
          timestamp: new Date().toISOString(),
          locked: true,
        };
        savePayoutDraw(draw);
        setFinalDraw(draw);
        setPhase("done");
        onDrawFinalized(draw);
      }
    }, TICK_MS);
  }

  return (
    <div
      className="fixed inset-0 z-200 flex items-center justify-center bg-black/70 backdrop-blur-sm px-4"
      role="dialog"
      aria-modal="true"
      aria-labelledby="payout-draw-title"
      onClick={close}
    >
      <div
        ref={dialogRef}
        className="w-full max-w-md rounded-2xl bg-[var(--modal)] border border-[var(--ov-14)] p-6 shadow-xl"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between mb-5">
          <h2 id="payout-draw-title" className="flex items-center gap-2 text-lg font-semibold text-[var(--text)]">
            <Dices size={20} aria-hidden="true" />
            Payout Order Draw
          </h2>
          {!isPending && (
            <button onClick={close} aria-label="Close" className="text-[var(--muted)] hover:text-[var(--text)]">
              <X size={20} />
            </button>
          )}
        </div>

        {phase === "idle" && (
          <>
            <p className="text-sm text-[var(--muted)] mb-4">
              Randomly assigns each participant a payout round. The draw is seeded and
              timestamped so anyone can verify the result wasn&apos;t manipulated.
            </p>
            <ul className="space-y-1.5 mb-5">
              {participantAddresses.map((address, i) => (
                <li
                  key={address}
                  className="flex items-center justify-between rounded-lg bg-[var(--ov-05)] px-3 py-2 text-sm"
                >
                  <span className="text-[var(--faint)] text-xs">#{i + 1}</span>
                  <span className="font-mono text-[var(--text)]">{truncate(address)}</span>
                </li>
              ))}
            </ul>
            <button
              onClick={runDraw}
              disabled={isPending}
              className="w-full flex items-center justify-center gap-2 rounded-xl bg-[#4B6B76] hover:bg-[#3D5A64] text-white py-2.5 font-semibold transition-colors disabled:opacity-60 disabled:cursor-not-allowed"
            >
              {isPending ? (
                <>
                  <Loader2 size={16} className="animate-spin" aria-hidden="true" />
                  Confirming…
                </>
              ) : (
                <>
                  <Shuffle size={16} aria-hidden="true" />
                  Run Payout Draw
                </>
              )}
            </button>
          </>
        )}

        {(phase === "shuffling" || phase === "done") && (
          <>
            <ul className="space-y-1.5 mb-5" aria-live={phase === "shuffling" ? "polite" : undefined}>
              {displayOrder.map((address, i) => (
                <li
                  key={address}
                  className={`flex items-center justify-between rounded-lg px-3 py-2 text-sm transition-colors ${
                    phase === "done" ? "bg-[#4B6B76]/10" : "bg-[var(--ov-05)]"
                  }`}
                >
                  <span className="text-[var(--faint)] text-xs">Round {i + 1}</span>
                  <span className="font-mono text-[var(--text)]">{truncate(address)}</span>
                </li>
              ))}
            </ul>

            {phase === "shuffling" && (
              <p className="flex items-center justify-center gap-2 text-center text-sm text-[var(--muted)] animate-pulse">
                <Loader2 size={14} className="animate-spin" aria-hidden="true" />
                Confirming…
              </p>
            )}

            {phase === "done" && finalDraw && (
              <div className="space-y-4">
                <div className="flex items-center gap-2 text-sm text-[var(--success)]">
                  <Lock size={14} aria-hidden="true" />
                  Order locked
                </div>
                <dl className="space-y-1 rounded-lg bg-[var(--ov-05)] p-3 text-xs">
                  <div className="flex justify-between gap-3">
                    <dt className="text-[var(--muted)]">Seed</dt>
                    <dd className="font-mono text-[var(--text)] truncate">{finalDraw.seed}</dd>
                  </div>
                  <div className="flex justify-between gap-3">
                    <dt className="text-[var(--muted)]">Timestamp</dt>
                    <dd className="text-[var(--text)]">{new Date(finalDraw.timestamp).toLocaleString()}</dd>
                  </div>
                </dl>
                <button
                  onClick={onClose}
                  className="w-full rounded-xl bg-[#4B6B76] hover:bg-[#3D5A64] text-white py-2.5 font-semibold transition-colors"
                >
                  Done
                </button>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}

