"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import Link from "next/link";
import { ChevronLeft, ChevronRight, CalendarDays, ArrowDownCircle, ArrowUpCircle, Calendar as CalendarIcon, Download } from "lucide-react";
import type { Circle } from "@/types/circle";
import { useTimezone } from "@/hooks/useTimezone";
import { generateCalendarIcs, downloadIcsFile } from "@/lib/calendarExport";

interface Props {
  circles: Circle[];
}

interface CalendarEntry {
  circleId: string;
  circleName: string;
  date: Date;
  amount: string;
  kind: "due" | "receive";
}

function parseAmount(value: string): number {
  const match = value.match(/([\d.]+)/);
  return match ? parseFloat(match[1]) : 0;
}

/**
 * In this app's rotating-savings model every active member contributes each
 * round, and the round's whole pot goes to whoever's turn it is. So a
 * circle's deadline produces a "due" entry for everyone, plus a "receive"
 * entry (pot = contribution x members) when it's this user's turn.
 */
function buildEntries(circles: Circle[]): CalendarEntry[] {
  const entries: CalendarEntry[] = [];
  for (const circle of circles) {
    if (circle.status !== "active" || !circle.deadline) continue;
    entries.push({
      circleId: circle.id,
      circleName: circle.name,
      date: circle.deadline,
      amount: circle.contribution,
      kind: "due",
    });
    if (circle.isYourTurn) {
      const pot = parseAmount(circle.contribution) * circle.members;
      entries.push({
        circleId: circle.id,
        circleName: circle.name,
        date: circle.deadline,
        amount: `${pot} USDT`,
        kind: "receive",
      });
    }
  }
  return entries;
}

function dateKey(d: Date): string {
  return `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
}

const WEEKDAY_LABELS = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];

export default function UpcomingPayoutsCalendar({ circles }: Props) {
  const { timezone, timezoneAbbr, formatTime } = useTimezone();
  const activeCircles = useMemo(() => circles.filter((c) => c.status === "active"), [circles]);
  const entries = useMemo(() => buildEntries(circles), [circles]);

  const handleExportIcs = () => {
    if (entries.length === 0) return;
    const calendarEvents = entries.map((entry) => ({
      id: `${entry.circleId}-${entry.kind}-${entry.date.getTime()}`,
      title: `${entry.circleName} (${entry.kind === "due" ? "Contribution Due" : "Payout Received"})`,
      description: `${entry.kind === "due" ? "You owe" : "You receive"}: ${entry.amount}. Circle: ${entry.circleName}`,
      startDate: entry.date,
    }));
    const icsData = generateCalendarIcs(calendarEvents, timezone);
    downloadIcsFile("upcoming-payouts.ics", icsData);
  };

  const today = useMemo(() => new Date(), []);
  const [viewDate, setViewDate] = useState(() => new Date(today.getFullYear(), today.getMonth(), 1));
  const [openKey, setOpenKey] = useState<string | null>(null);
  const popoverRef = useRef<HTMLDivElement>(null);

  const entriesByDay = useMemo(() => {
    const map = new Map<string, CalendarEntry[]>();
    for (const entry of entries) {
      const key = dateKey(entry.date);
      const existing = map.get(key);
      if (existing) existing.push(entry);
      else map.set(key, [entry]);
    }
    return map;
  }, [entries]);

  useEffect(() => {
    if (!openKey) return;
    const handleClick = (e: MouseEvent) => {
      if (popoverRef.current && !popoverRef.current.contains(e.target as Node)) {
        setOpenKey(null);
      }
    };
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpenKey(null);
    };
    document.addEventListener("mousedown", handleClick);
    document.addEventListener("keydown", handleKey);
    return () => {
      document.removeEventListener("mousedown", handleClick);
      document.removeEventListener("keydown", handleKey);
    };
  }, [openKey]);

  useEffect(() => {
    setOpenKey(null);
  }, [viewDate]);

  if (activeCircles.length === 0) {
    return (
      <div className="bg-[var(--content)] p-6 rounded-2xl">
        <div className="flex items-center mb-6">
          <h2 className="text-xl font-bold font-sora text-[var(--text)] shrink-0">Upcoming Payouts</h2>
          <div className="ml-4 h-px bg-[var(--ov-1a)] w-full" aria-hidden="true" />
        </div>
        <div className="flex flex-col items-center justify-center py-16 text-center gap-3">
          <CalendarDays size={32} className="text-[var(--muted)]" aria-hidden="true" />
          <p className="text-[var(--muted)] text-base">
            You don&apos;t have any active circles yet. Join or create one to see contribution and payout dates here.
          </p>
        </div>
      </div>
    );
  }

  const year = viewDate.getFullYear();
  const month = viewDate.getMonth();
  const firstOfMonth = new Date(year, month, 1);
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const leadingBlanks = firstOfMonth.getDay();
  const totalCells = Math.ceil((leadingBlanks + daysInMonth) / 7) * 7;

  const cells: (Date | null)[] = [];
  for (let i = 0; i < totalCells; i++) {
    const dayNum = i - leadingBlanks + 1;
    cells.push(dayNum >= 1 && dayNum <= daysInMonth ? new Date(year, month, dayNum) : null);
  }

  const monthLabel = viewDate.toLocaleDateString("en-US", { month: "long", year: "numeric" });

  return (
    <div className="bg-[var(--content)] p-6 rounded-2xl">
      <div className="flex items-center mb-6">
        <h2 className="text-xl font-bold font-sora text-[var(--text)] shrink-0">Upcoming Payouts</h2>
        <div className="ml-4 h-px bg-[var(--ov-1a)] w-full" aria-hidden="true" />
      </div>

      <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-4 gap-2">
        <div className="flex items-center gap-3">
          <span className="text-sm font-semibold text-[var(--text)]">{monthLabel}</span>
          <span className="text-xs text-[var(--muted)]">({timezoneAbbr})</span>
        </div>
        <div className="flex items-center gap-2">
          {entries.length > 0 && (
            <button
              type="button"
              onClick={handleExportIcs}
              className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg border border-[var(--border)] bg-[var(--modal)] text-xs font-medium text-[var(--text)] hover:bg-[var(--ov-0a)] transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76]"
              title={`Export calendar (.ics) in ${timezone}`}
            >
              <Download size={13} aria-hidden="true" />
              Export (.ics)
            </button>
          )}
          <div className="flex items-center gap-1 bg-[var(--modal)] rounded-lg border border-[var(--border)] p-1">
            <button
              type="button"
              onClick={() => setViewDate(new Date(year, month - 1, 1))}
              className="p-1 rounded hover:bg-[var(--ov-0a)] text-[var(--muted)] hover:text-[var(--text)] transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76]"
              aria-label="Previous month"
            >
              <ChevronLeft size={16} />
            </button>
            <button
              type="button"
              onClick={() => setViewDate(new Date(year, month + 1, 1))}
              className="p-1 rounded hover:bg-[var(--ov-0a)] text-[var(--muted)] hover:text-[var(--text)] transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76]"
              aria-label="Next month"
            >
              <ChevronRight size={16} />
            </button>
          </div>
        </div>
      </div>

      <div className="flex items-center gap-4 mb-4 text-xs text-[var(--muted)]">
        <span className="flex items-center gap-1.5">
          <span className="w-2 h-2 rounded-full bg-[#FF5B5B]" aria-hidden="true" />
          You owe
        </span>
        <span className="flex items-center gap-1.5">
          <span className="w-2 h-2 rounded-full bg-[var(--success)]" aria-hidden="true" />
          You receive
        </span>
      </div>

      <div className="grid grid-cols-7 gap-1 mb-1">
        {WEEKDAY_LABELS.map((label) => (
          <div key={label} className="text-center text-[10px] font-semibold uppercase tracking-wider text-[var(--faint)] py-1">
            {label}
          </div>
        ))}
      </div>

      <div className="grid grid-cols-7 gap-1">
        {cells.map((date, idx) => {
          if (!date) return <div key={`blank-${idx}`} className="aspect-square" />;

          const key = dateKey(date);
          const dayEntries = entriesByDay.get(key) ?? [];
          const hasDue = dayEntries.some((e) => e.kind === "due");
          const hasReceive = dayEntries.some((e) => e.kind === "receive");
          const isToday = dateKey(today) === key;
          const isOpen = openKey === key;

          return (
            <div key={key} className="relative aspect-square">
              <button
                type="button"
                disabled={dayEntries.length === 0}
                onClick={() => setOpenKey(isOpen ? null : key)}
                className={`w-full h-full flex flex-col items-center justify-center rounded-lg text-sm transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76] ${
                  dayEntries.length > 0
                    ? "hover:bg-[var(--ov-0a)] cursor-pointer text-[var(--text)]"
                    : "text-[var(--muted)] cursor-default"
                } ${isToday ? "ring-1 ring-[#4B6B76]" : ""} ${isOpen ? "bg-[var(--ov-0a)]" : ""}`}
                aria-label={
                  dayEntries.length > 0
                    ? `${date.toDateString()}: ${dayEntries.length} circle event${dayEntries.length > 1 ? "s" : ""}`
                    : date.toDateString()
                }
              >
                <span>{date.getDate()}</span>
                {(hasDue || hasReceive) && (
                  <span className="flex items-center gap-0.5 mt-0.5" aria-hidden="true">
                    {hasDue && <span className="w-1.5 h-1.5 rounded-full bg-[#FF5B5B]" />}
                    {hasReceive && <span className="w-1.5 h-1.5 rounded-full bg-[var(--success)]" />}
                  </span>
                )}
              </button>

              {isOpen && (
                <div
                  ref={popoverRef}
                  className="absolute z-20 top-full left-1/2 -translate-x-1/2 mt-2 w-64 bg-[var(--modal)] border border-[var(--border)] rounded-xl shadow-xl p-3"
                  role="dialog"
                  aria-label={`Events on ${date.toDateString()}`}
                >
                  <div className="flex items-center justify-between mb-2">
                    <p className="text-xs font-semibold text-[var(--text)]">
                      {date.toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric" })}
                    </p>
                    <span className="text-[10px] text-[var(--muted)] font-mono">{timezoneAbbr}</span>
                  </div>
                  <div className="space-y-2">
                    {dayEntries.map((entry, i) => (
                      <Link
                        key={`${entry.circleId}-${entry.kind}-${i}`}
                        href={`/dashboard/circles/${entry.circleId}`}
                        onClick={() => setOpenKey(null)}
                        className="flex items-start gap-2 p-2 rounded-lg hover:bg-[var(--ov-05)] transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76]"
                      >
                        {entry.kind === "due" ? (
                          <ArrowUpCircle size={16} className="text-[#FF5B5B] shrink-0 mt-0.5" aria-hidden="true" />
                        ) : (
                          <ArrowDownCircle size={16} className="text-[var(--success)] shrink-0 mt-0.5" aria-hidden="true" />
                        )}
                        <span className="min-w-0">
                          <span className="block text-xs font-medium text-[var(--text)] truncate">{entry.circleName}</span>
                          <span
                            className={`block text-xs ${
                              entry.kind === "due" ? "text-[#FF5B5B]" : "text-[var(--success)]"
                            }`}
                          >
                            {entry.kind === "due" ? "You owe" : "You receive"} {entry.amount}
                          </span>
                          <span className="block text-[10px] text-[var(--faint)]">
                            {formatTime(entry.date)}
                          </span>
                        </span>
                      </Link>
                    ))}
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

"use client";

import Link from "next/link";
import { useState, useRef, useEffect, useCallback } from "react";
import { Copy, Check, ChevronDown, X, Search, KeyRound, Loader2 } from "lucide-react";
import GlossaryTerm from "@/components/ui/GlossaryTerm";
import { useWallet, AVAILABLE_WALLETS, truncateAddress, type WalletId } from "@/contexts/WalletContext";
import { APP_NETWORK, NETWORK_LABELS, type StellarNetwork } from "@/config/network";
import { isPasskeySupported } from "@/lib/passkeys";
import { OPEN_COMMAND_PALETTE_EVENT } from "@/components/ui/CommandPalette";
import ThemeToggle from "@/components/ui/ThemeToggle";
import InstallPWAButton from "@/components/ui/InstallPWAButton";
import PendingTransactionsTracker from "@/components/layout/Navbar/PendingTransactionsTracker";
import { hasUnseenChangelog as checkUnseenChangelog } from "@/data/changelog";

const navLinks = [
  { label: "Home", href: "#" },
  { label: "How it Works", href: "#how" },
  { label: "Features", href: "#why" },
  { label: "FAQs", href: "#faq" },
  { label: "What's New", href: "/changelog" },
];

function WalletSelectModal({
  onClose,
  onSelect,
  onPasskey,
}: {
  onClose: () => void;
  onSelect: (id: WalletId) => void;
  onPasskey: () => Promise<void>;
}) {
  const modalRef = useRef<HTMLDivElement>(null);
  const [passkeyBusy, setPasskeyBusy] = useState(false);
  const [passkeyError, setPasskeyError] = useState<string | null>(null);
  const passkeySupported = isPasskeySupported();

  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => { if (e.key === "Escape") onClose(); };
    document.addEventListener("keydown", handleKey);
    return () => document.removeEventListener("keydown", handleKey);
  }, [onClose]);

  return (
    <div
      className="fixed inset-0 z-200 flex items-center justify-center"
      role="dialog"
      aria-modal="true"
      aria-labelledby="wallet-modal-title"
    >
      <div
        className="absolute inset-0 bg-black/60 backdrop-blur-sm"
        onClick={onClose}
        aria-hidden="true"
      />
      <div
        ref={modalRef}
        className="relative z-10 w-full max-w-sm mx-4 rounded-2xl border border-[var(--ov-14)] p-6"
        style={{ background: "var(--modal)" }}
      >
        <div className="flex items-center justify-between mb-6">
          <h2 id="wallet-modal-title" className="text-lg font-bold text-[var(--text)] font-sora">
            Connect Wallet
          </h2>
          <button
            onClick={onClose}
            className="p-1.5 rounded-lg text-[var(--muted)] hover:text-[var(--text)] hover:bg-[var(--ov-0f)] transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76]"
            aria-label="Close wallet selector"
          >
            <X size={18} />
          </button>
        </div>

        <p className="text-[var(--muted)] text-sm mb-5">
          Choose a <GlossaryTerm term="starknet">Starknet</GlossaryTerm>-compatible{" "}
          <GlossaryTerm term="wallet">wallet</GlossaryTerm> to connect.
        </p>

        <div className="space-y-3">
          {AVAILABLE_WALLETS.map((wallet) => (
            <button
              key={wallet.id}
              onClick={() => onSelect(wallet.id)}
              className="w-full flex items-center gap-4 px-4 py-3.5 rounded-xl bg-[var(--ov-08)] hover:bg-[var(--ov-12)] border border-[var(--ov-0f)] hover:border-[#4B6B76] text-[var(--text)] text-sm font-medium transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76]"
            >
              <span className="w-8 h-8 rounded-full bg-[var(--ov-14)] flex items-center justify-center text-base" aria-hidden="true">
                {wallet.id === "freighter" ? "🔷" : "🔶"}
              </span>
              <span>{wallet.name}</span>
            </button>
          ))}
        </div>

        <div className="my-5 flex items-center gap-3 text-[10px] font-semibold uppercase tracking-wider text-[var(--faint)]">
          <span className="h-px flex-1 bg-[var(--ov-10)]" />
          <span>or</span>
          <span className="h-px flex-1 bg-[var(--ov-10)]" />
        </div>

        <button
          type="button"
          disabled={!passkeySupported || passkeyBusy}
          onClick={async () => {
            setPasskeyBusy(true);
            setPasskeyError(null);
            try {
              await onPasskey();
            } catch (error) {
              setPasskeyError(error instanceof Error ? error.message : "Passkey sign-in failed.");
            } finally {
              setPasskeyBusy(false);
            }
          }}
          className="flex w-full items-center justify-center gap-2 rounded-xl border border-[#4B6B76]/50 px-4 py-3.5 text-sm font-semibold text-[var(--text)] transition-colors hover:bg-[#4B6B76]/10 disabled:cursor-not-allowed disabled:opacity-50"
        >
          {passkeyBusy ? <Loader2 size={16} className="animate-spin" aria-hidden="true" /> : <KeyRound size={16} aria-hidden="true" />}
          {passkeyBusy ? "Waiting for passkey..." : "Sign in with passkey"}
        </button>
        <p className="mt-2 flex items-center justify-center gap-1 text-[11px] text-[var(--muted)]">
          New to passkeys? <GlossaryTerm term="passkey" iconOnly />
        </p>
        {passkeyError && <p role="alert" className="mt-2 text-xs leading-relaxed text-red-500">{passkeyError}</p>}
        {!passkeySupported && (
          <p className="mt-2 text-center text-[11px] text-[var(--muted)]">
            Passkeys are unavailable here. Choose a wallet above instead.
          </p>
        )}
      </div>
    </div>
  );
}

function ConnectedDropdown({ address, onCopy, onDisconnect, onClose }: {
  address: string;
  onCopy: () => void;
  onDisconnect: () => void;
  onClose: () => void;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const { linkedWallets, setWalletNetwork } = useWallet();
  const network = linkedWallets.find((w) => w.address === address)?.network ?? APP_NETWORK;
  const mismatched = network !== APP_NETWORK;

  useEffect(() => {
    const handleClick = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) onClose();
    };
    const handleKey = (e: KeyboardEvent) => { if (e.key === "Escape") onClose(); };
    document.addEventListener("mousedown", handleClick);
    document.addEventListener("keydown", handleKey);
    return () => {
      document.removeEventListener("mousedown", handleClick);
      document.removeEventListener("keydown", handleKey);
    };
  }, [onClose]);

  return (
    <div ref={ref} className="relative">
      <div
        className="absolute right-0 top-3 w-52 rounded-xl border border-[var(--ov-14)] overflow-hidden z-150"
        style={{ background: "var(--modal)" }}
        role="menu"
        aria-label="Wallet options"
      >
        <div className="px-4 py-3 border-b border-[var(--ov-0f)]">
          <p className="text-xs text-[var(--muted)] mb-0.5">Connected</p>
          <p className="text-sm text-[var(--text)] font-mono">{truncateAddress(address)}</p>
          <div className="mt-2 flex items-center justify-between gap-2">
            <span className={`text-xs ${mismatched ? "font-semibold text-amber-400" : "text-[var(--muted)]"}`}>
              Network: {NETWORK_LABELS[network]}
              {mismatched && " (mismatch)"}
            </span>
            {/* #220: demo-only — there's no real wallet extension here
                whose network could actually differ, so this is how the
                guard gets exercised/tested. A real integration wouldn't
                have this control; the wallet's own network just is
                whatever it is. */}
            <button
              type="button"
              onClick={() =>
                setWalletNetwork(address, mismatched ? APP_NETWORK : (APP_NETWORK === "testnet" ? "mainnet" : "testnet") as StellarNetwork)
              }
              className="text-xs text-[#4B6B76] underline-offset-2 hover:underline"
            >
              {mismatched ? "Fix" : "Simulate mismatch"}
            </button>
          </div>
        </div>
        <button
          onClick={onCopy}
          className="w-full flex items-center gap-2.5 px-4 py-3 text-sm text-[var(--muted2)] hover:text-[var(--text)] hover:bg-[var(--ov-0a)] transition-colors focus-visible:outline-none focus-visible:ring-inset focus-visible:ring-2 focus-visible:ring-[#4B6B76]"
          role="menuitem"
        >
          <Copy size={14} aria-hidden="true" />
          Copy Address
        </button>
        <button
          onClick={onDisconnect}
          className="w-full flex items-center gap-2.5 px-4 py-3 text-sm text-[#FF5B5B] hover:bg-[#ff5b5b12] transition-colors focus-visible:outline-none focus-visible:ring-inset focus-visible:ring-2 focus-visible:ring-[#FF5B5B]"
          role="menuitem"
        >
          Disconnect
        </button>
      </div>
    </div>
  );
}

export default function Navbar() {
  const [menuOpen, setMenuOpen] = useState(false);
  const [showWalletModal, setShowWalletModal] = useState(false);
  const [showDropdown, setShowDropdown] = useState(false);
  const [copied, setCopied] = useState(false);
  const [hasUnseenChangelog, setHasUnseenChangelog] = useState(false);

  useEffect(() => {
    const sync = () => setHasUnseenChangelog(checkUnseenChangelog());
    sync();
  }, []);

  const { address, isConnected, connect, signInWithPasskey, disconnect } = useWallet();

  const handleSelectWallet = useCallback(async (walletId: WalletId) => {
    await connect(walletId);
    setShowWalletModal(false);
  }, [connect]);

  const handlePasskeySignIn = useCallback(async () => {
    await signInWithPasskey();
    setShowWalletModal(false);
  }, [signInWithPasskey]);

  const handleCopyAddress = useCallback(() => {
    if (!address) return;
    try {
      navigator.clipboard.writeText(address);
    } catch {
      const el = document.createElement("textarea");
      el.value = address;
      el.style.cssText = "position:fixed;opacity:0";
      document.body.appendChild(el);
      el.select();
      document.execCommand("copy");
      document.body.removeChild(el);
    }
    setCopied(true);
    setTimeout(() => setCopied(false), 1500);
    setShowDropdown(false);
  }, [address]);

  const handleDisconnect = useCallback(() => {
    disconnect();
    setShowDropdown(false);
  }, [disconnect]);

  return (
    <>
      <nav
        className="fixed top-0 left-0 right-0 z-100 backdrop-blur-[20px] border-b border-[var(--border)]"
        style={{ background: "var(--nav-bg)" }}
      >

        <div className="max-w-[1200px] mx-auto flex items-center justify-between px-10 py-[18px] max-md:px-6 max-md:py-4">
          {/* Logo */}
