                  aria-haspopup="menu"
                  aria-expanded={showDropdown}
                >
                  <span className="w-2 h-2 rounded-full bg-[#4ADE80] shrink-0" aria-hidden="true" />
                  <span className="font-mono">{truncateAddress(address)}</span>
                  {copied ? (
