          </div>

          {/* Mobile search + hamburger */}
          <div className="hidden max-md:flex items-center gap-3">
          <PendingTransactionsTracker />
          <button
            onClick={() => window.dispatchEvent(new Event(OPEN_COMMAND_PALETTE_EVENT))}
