"use client";

import { useState, useEffect, useRef } from "react";
import { X, Users, Coins, Gift, ArrowRight } from "lucide-react";
import Link from "next/link";
import { useFocusTrap } from "@/hooks/useFocusTrap";

const STORAGE_KEY = "onboarding_complete";

const HOW_IT_WORKS = [
  { Icon: Users, label: "Create or Join", desc: "Start a savings circle or join an existing one with people you trust." },
  { Icon: Coins, label: "Contribute", desc: "Each member contributes the agreed amount every round." },
  { Icon: Gift, label: "Receive Payout", desc: "Members take turns receiving the full pool payout." },
];

const TOTAL_STEPS = 3;

export default function OnboardingModal() {
  const [open, setOpen] = useState(false);
  const [step, setStep] = useState(0);
  const ref = useRef<HTMLDivElement>(null);

  useFocusTrap(ref, open, dismiss);

  useEffect(() => {
    if (!localStorage.getItem(STORAGE_KEY)) setOpen(true);
  }, []);

  function dismiss() {
    localStorage.setItem(STORAGE_KEY, "true");
    setOpen(false);
  }

  if (!open) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 px-4">
      <div
        ref={ref}
        className="bg-[var(--modal)] rounded-2xl w-full max-w-md p-8 relative"
        role="dialog"
        aria-modal="true"
        aria-labelledby="onboarding-title"
      >
        <button
          onClick={dismiss}
          className="absolute top-4 end-4 text-[var(--muted)] hover:text-[var(--text)] transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76] rounded"
          aria-label="Skip onboarding"
        >
          <X size={20} />
        </button>

        {/* Progress dots */}
        <div className="flex gap-2 justify-center mb-8" role="progressbar" aria-valuenow={step + 1} aria-valuemax={TOTAL_STEPS} aria-label={`Step ${step + 1} of ${TOTAL_STEPS}`}>
          {Array.from({ length: TOTAL_STEPS }).map((_, i) => (
            <div
              key={i}
              className={`h-2 rounded-full transition-all duration-300 ${i === step ? "w-6 bg-[#4B6B76]" : "w-2 bg-[var(--ov-1a)]"}`}
            />
          ))}
        </div>

        {/* Step 0: Welcome */}
        {step === 0 && (
          <div className="text-center space-y-4">
            <div className="w-16 h-16 rounded-full bg-[#4B6B76]/20 flex items-center justify-center mx-auto mb-4" aria-hidden="true">
              <span className="text-3xl font-bold text-[#4B6B76]">$</span>
            </div>
            <h2 id="onboarding-title" className="text-2xl font-bold font-sora text-[var(--text)]">
              Welcome to Ahjoor
            </h2>
            <p className="text-[var(--muted)] text-sm leading-relaxed">
              Ahjoor is a{" "}
              <span className="text-[var(--text)] font-medium">trustless community savings</span>{" "}
              platform. Pool funds with people you trust, take turns receiving payouts — all secured by smart contracts.
            </p>
          </div>
        )}

        {/* Step 1: How it works */}
        {step === 1 && (
          <div className="space-y-5">
            <h2 id="onboarding-title" className="text-2xl font-bold font-sora text-[var(--text)] text-center">
              How It Works
            </h2>
            <div className="space-y-3">
              {HOW_IT_WORKS.map(({ Icon, label, desc }, i) => (
                <div key={i} className="flex items-start gap-4 bg-[var(--ov-0a)] rounded-xl p-4">
                  <div className="w-9 h-9 rounded-full bg-[#4B6B76]/20 flex items-center justify-center shrink-0" aria-hidden="true">
                    <Icon size={18} className="text-[#4B6B76]" />
                  </div>
                  <div>
                    <p className="font-semibold text-[var(--text)] text-sm">{label}</p>
                    <p className="text-[var(--muted)] text-xs mt-0.5">{desc}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Step 2: Choose path */}
        {step === 2 && (
          <div className="space-y-6 text-center">
            <h2 id="onboarding-title" className="text-2xl font-bold font-sora text-[var(--text)]">
              How would you like to start?
            </h2>
            <p className="text-[var(--muted)] text-sm">Choose your path to begin your savings journey.</p>
            <div className="flex flex-col gap-3">
              <Link
                href="/dashboard/circles"
                onClick={dismiss}
                className="w-full py-3 bg-[#4B6B76] hover:bg-[#3D5A64] text-white font-medium rounded-xl transition-colors text-center focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--modal)]"
              >
                Create a Circle
              </Link>
              <Link
                href="/dashboard/circles?tab=discover"
                onClick={dismiss}
                className="w-full py-3 bg-[var(--ov-0a)] hover:bg-[var(--ov-14)] text-[var(--text)] font-medium rounded-xl transition-colors text-center focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--modal)]"
              >
                Browse Circles
              </Link>
            </div>
          </div>
        )}

        {/* Navigation */}
        <div className="flex items-center justify-between mt-8">
          <button
            onClick={dismiss}
            className="text-sm text-[var(--muted)] hover:text-[var(--text)] transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76] rounded px-2 py-1"
          >
            Skip
          </button>
          {step < TOTAL_STEPS - 1 ? (
            <button
              onClick={() => setStep((s) => s + 1)}
              className="flex items-center gap-2 px-5 py-2.5 bg-[#4B6B76] hover:bg-[#3D5A64] text-white text-sm font-medium rounded-lg transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--modal)]"
            >
              Next <ArrowRight size={16} aria-hidden="true" />
            </button>
          ) : (
            <button
              onClick={dismiss}
              className="px-5 py-2.5 bg-[#4B6B76] hover:bg-[#3D5A64] text-white text-sm font-medium rounded-lg transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76]"
            >
              Get Started
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { Loader2, CheckCircle2, XCircle, ExternalLink, X } from "lucide-react";
import { addPendingTransaction } from "@/lib/pendingTransactions";
import GasFeeEstimate from "@/components/modals/GasFeeEstimate";
import GlossaryTerm from "@/components/ui/GlossaryTerm";
import { useGasFeeEstimate } from "@/hooks/useGasFeeEstimate";
import type { GasFeeEstimate as GasFeeEstimateData, GasFeeRequest } from "@/lib/gasFee";

export type TxType = "contribute" | "claim";
export type TxStatus = "idle" | "pending" | "success" | "error";

export interface TxFailure {
  reason: string;
  hash?: string;
  code?: string;
  attempt: number;
}

export interface TxAttempt {
  isRetry: boolean;
  attempt: number;
  fee: GasFeeEstimateData | null;
  previousFailure?: TxFailure;
}

interface TxConfirmModalProps {
  isOpen: boolean;
  onClose: () => void;
  type: TxType;
  circleName: string;
  amount: number; // USDT amount
  /**
   * Submits the actual on-chain transaction.
   * Should resolve with the tx hash on success, or throw on failure.
   */
  onConfirm: (attempt: TxAttempt) => Promise<string>;
  walletAddress?: string;
  estimateFee?: (request: GasFeeRequest) => Promise<GasFeeEstimateData | null>;
  onFailure?: (failure: TxFailure) => void;
  retryFailure?: TxFailure;
}

const EXPLORER_BASE_URL = "https://starkscan.co/tx";

export default function TxConfirmModal({
  isOpen,
  onClose,
  type,
  circleName,
  amount,
  onConfirm,
  walletAddress,
  estimateFee,
  onFailure,
  retryFailure,
}: TxConfirmModalProps) {
  const [status, setStatus] = useState<TxStatus>("idle");
  const [txHash, setTxHash] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [failure, setFailure] = useState<TxFailure | null>(null);
  const attemptRef = useRef(0);
  const feeRequest = useMemo(() => ({ operation: type, walletAddress }), [type, walletAddress]);
  const { fee, loading: feeLoading, refresh } = useGasFeeEstimate(isOpen, feeRequest, estimateFee);

  useEffect(() => {
    if (isOpen) {
      const resetId = window.setTimeout(() => {
        setStatus("idle");
        setTxHash(null);
        setErrorMessage(null);
        setFailure(null);
        attemptRef.current = 0;
      }, 0);
      return () => window.clearTimeout(resetId);
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const actionLabel = type === "contribute" ? "Make Contribution" : "Claim Reward";
  const actionVerb = type === "contribute" ? "contributing" : "claiming";

  const handleConfirm = async () => {
    if (status === "pending") return;
    const isRetry = status === "error" || Boolean(retryFailure);
    const attempt = attemptRef.current + 1;
    attemptRef.current = attempt;
    setStatus("pending");
    setErrorMessage(null);
    try {
      const latestFee = isRetry ? await refresh() : fee;
      const hash = await onConfirm({
        isRetry,
        attempt,
        fee: latestFee,
        previousFailure: failure ?? retryFailure,
      });
      setTxHash(hash);
      addPendingTransaction({
        hash,
        network: "starknet",
        label: type === "contribute" ? `Contribution to ${circleName}` : `Claim from ${circleName}`,
        amount: `${amount.toLocaleString()} USDT`,
      });
      setStatus("success");
    } catch (err) {
      const candidate = err as { message?: unknown; hash?: unknown; txHash?: unknown; code?: unknown };
      const nextFailure: TxFailure = {
        reason: typeof candidate.message === "string" ? candidate.message : "The wallet or network rejected the transaction.",
        hash: typeof candidate.hash === "string" ? candidate.hash : typeof candidate.txHash === "string" ? candidate.txHash : undefined,
        code: typeof candidate.code === "string" ? candidate.code : undefined,
        attempt,
      };
      setFailure(nextFailure);
      setErrorMessage(nextFailure.reason);
      onFailure?.(nextFailure);
      setStatus("error");
    }
  };

  const handleClose = () => {
    if (status === "pending") return; // prevent closing mid-transaction
    onClose();
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm px-4"
      role="dialog"
      aria-modal="true"
      aria-labelledby="tx-confirm-title"
      onClick={handleClose}
    >
      <div
        className="w-full max-w-md rounded-2xl bg-[var(--modal)] border border-[var(--ov-14)] p-6 shadow-xl font-sora"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between mb-5">
          <h2 id="tx-confirm-title" className="text-lg font-semibold text-[var(--text)]">
            Confirm {actionLabel}
          </h2>
          {status !== "pending" && (
            <button
              onClick={handleClose}
              aria-label="Close"
              className="text-[var(--muted)] hover:text-[var(--text)] transition-colors"
            >
              <X size={20} />
            </button>
          )}
        </div>

        {/* IDLE / PENDING REVIEW STATE */}
        {(status === "idle" || status === "pending") && (
          <>
            <dl className="space-y-3 mb-6">
              <div className="flex justify-between text-sm">
                <dt className="text-[var(--muted)]">Action</dt>
                <dd className="font-medium text-[var(--text)]">{actionLabel}</dd>
              </div>
              <div className="flex justify-between text-sm">
                <dt className="text-[var(--muted)]">Circle</dt>
                <dd className="font-medium text-[var(--text)]">{circleName}</dd>
              </div>
              <div className="flex justify-between text-sm">
                <dt className="text-[var(--muted)]">Amount</dt>
                <dd className="font-medium text-[var(--text)]">{amount.toLocaleString()} USDT</dd>
              </div>
            </dl>
            <GasFeeEstimate fee={fee} loading={feeLoading} />
            <p className="mt-3 mb-6 text-xs leading-5 text-[var(--muted)]">
              Your wallet will ask for a{" "}
              <GlossaryTerm term="wallet-signature">wallet signature</GlossaryTerm> to approve this.
              It&apos;s complete once it receives a{" "}
              <GlossaryTerm term="block-confirmation">block confirmation</GlossaryTerm>.
            </p>

            <div className="flex gap-3">
              <button
                onClick={handleClose}
                disabled={status === "pending"}
                className="flex-1 rounded-xl border border-[var(--ov-1a)] text-[var(--text)] py-2.5 font-medium hover:bg-[var(--ov-0a)] transition-colors disabled:opacity-50"
              >
                Cancel
              </button>
              <button
                onClick={handleConfirm}
                disabled={status === "pending"}
                className="flex-1 flex items-center justify-center gap-2 rounded-xl bg-[#4ADE80] text-[#0A0A0A] py-2.5 font-semibold hover:bg-[#3fc873] transition-colors disabled:opacity-70"
              >
                {status === "pending" ? (
                  <>
                    <Loader2 size={18} className="animate-spin" />
                    Confirming...
                  </>
                ) : (
                  "Confirm"
                )}
              </button>
            </div>
          </>
        )}

        {/* SUCCESS STATE */}
        {status === "success" && (
          <div className="text-center py-2">
            <CheckCircle2 className="mx-auto mb-3 text-[var(--success)]" size={48} />
            <p className="font-medium text-[var(--text)] mb-1">
              {type === "contribute" ? "Contribution successful" : "Reward claimed"}
            </p>
            <p className="text-sm text-[var(--muted)] mb-4">
              Your {actionVerb} of {amount.toLocaleString()} USDT to {circleName} was confirmed.
            </p>
            {txHash && (
              <a
                href={`${EXPLORER_BASE_URL}/${txHash}`}
                target="_blank"
                rel="noopener noreferrer"
                className="inline-flex items-center gap-1 text-[var(--success)] hover:underline text-sm"
              >
                View on Starkscan <ExternalLink size={14} />
              </a>
            )}
            {txHash && (
              <span className="ml-1 align-middle">
                <GlossaryTerm term="block-explorer" iconOnly />
              </span>
            )}
            <button
              onClick={onClose}
              className="mt-6 w-full rounded-xl bg-[#4ADE80] text-[#0A0A0A] py-2.5 font-semibold hover:bg-[#3fc873] transition-colors"
            >
              Done
            </button>
          </div>
        )}

        {/* ERROR STATE */}
        {status === "error" && (
          <div className="text-center py-2">
            <XCircle className="mx-auto mb-3 text-red-500" size={48} />
            <p className="font-medium text-[var(--text)] mb-1">Transaction failed</p>
            <p className="text-sm text-[var(--muted)] mb-2">{errorMessage}</p>
            {failure?.code && <p className="text-xs text-[var(--muted)] mb-2">Error code: {failure.code}</p>}
            {failure?.hash && (
              <a
                href={`${EXPLORER_BASE_URL}/${failure.hash}`}
                target="_blank"
                rel="noopener noreferrer"
                className="inline-flex items-center gap-1 text-sm text-[var(--muted)] hover:underline mb-4"
              >
                View failed transaction {failure.hash.slice(0, 10)}... <ExternalLink size={14} />
              </a>
            )}
            <div className="flex gap-3">
              <button
                onClick={onClose}
                className="flex-1 rounded-xl border border-[var(--ov-1a)] text-[var(--text)] py-2.5 font-medium hover:bg-[var(--ov-0a)] transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={handleConfirm}
                className="flex-1 rounded-xl bg-[#4ADE80] text-[#0A0A0A] py-2.5 font-semibold hover:bg-[#3fc873] transition-colors"
              >
                Retry
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import {
  Monitor,
  Smartphone,
  Tablet,
  Laptop,
  Globe,
  Shield,
  LogOut,
  AlertTriangle,
  CheckCircle2,
  X,
  Radio,
  Lock,
} from "lucide-react";
import { ActiveSession, DeviceType } from "@/types/session";
import { MOCK_SESSIONS } from "@/data/sessions";

const DEVICE_ICONS: Record<DeviceType, React.ElementType> = {
  desktop: Monitor,
  laptop: Laptop,
  mobile: Smartphone,
  tablet: Tablet,
};

export default function ActiveSessionsManager() {
  const [sessions, setSessions] = useState<ActiveSession[]>(MOCK_SESSIONS);
  const [sessionToRevoke, setSessionToRevoke] = useState<ActiveSession | null>(null);
  const [showRevokeAllModal, setShowRevokeAllModal] = useState(false);
  const [toastMessage, setToastMessage] = useState<string | null>(null);
  const [revoking, setRevoking] = useState(false);

  const triggerToast = (msg: string) => {
    setToastMessage(msg);
    setTimeout(() => setToastMessage(null), 3500);
  };

  const handleRevokeSingle = async () => {
    if (!sessionToRevoke) return;
    setRevoking(true);
    await new Promise((res) => setTimeout(res, 400));
    setSessions((prev) => prev.filter((s) => s.id !== sessionToRevoke.id));
    setRevoking(false);
    triggerToast(`Session for ${sessionToRevoke.deviceName} (${sessionToRevoke.location.city}) was revoked.`);
    setSessionToRevoke(null);
  };

  const handleRevokeAllOther = async () => {
    setRevoking(true);
    await new Promise((res) => setTimeout(res, 500));
    setSessions((prev) => prev.filter((s) => s.isCurrent));
    setRevoking(false);
    triggerToast("All other active sessions have been signed out.");
    setShowRevokeAllModal(false);
  };

  const otherSessionsCount = sessions.filter((s) => !s.isCurrent).length;

  return (
    <div className="space-y-6">
      {/* Toast feedback */}
      {toastMessage && (
        <div
          role="status"
          aria-live="polite"
          className="p-3.5 rounded-xl bg-emerald-500/10 border border-emerald-500/30 text-emerald-500 flex items-center gap-2 text-xs font-medium animate-fade-up"
        >
          <CheckCircle2 size={16} aria-hidden="true" />
          <span>{toastMessage}</span>
        </div>
      )}

      {/* Header card with action */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 p-5 rounded-2xl bg-[var(--content)] border border-[var(--ov-10)]">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-[#4B6B76]/15 text-[#4B6B76] flex items-center justify-center">
            <Shield size={20} aria-hidden="true" />
          </div>
          <div>
            <h3 className="text-base font-bold font-sora text-[var(--text)]">
              Connected Devices & Sessions
            </h3>
            <p className="text-xs text-[var(--muted)]">
              Review browsers and mobile devices currently signed into your wallet account.
            </p>
          </div>
        </div>

        {otherSessionsCount > 0 && (
          <button
            type="button"
            onClick={() => setShowRevokeAllModal(true)}
            className="inline-flex items-center justify-center gap-1.5 px-3.5 py-2 rounded-xl border border-red-500/30 text-red-500 hover:bg-red-500/10 text-xs font-semibold transition-colors shrink-0"
          >
            <LogOut size={14} aria-hidden="true" />
            <span>Sign Out All Other Sessions</span>
          </button>
        )}
      </div>

      {/* Sessions List */}
      <div className="p-5 rounded-2xl bg-[var(--modal)] border border-[var(--ov-10)] space-y-3">
        <div className="flex items-center justify-between pb-2 border-b border-[var(--ov-08)]">
          <h4 className="text-xs font-semibold uppercase tracking-wider text-[var(--muted)]">
            Active Devices ({sessions.length})
          </h4>
          <span className="text-[11px] text-[var(--muted)]">
            {otherSessionsCount} other {otherSessionsCount === 1 ? "device" : "devices"} connected
          </span>
        </div>

        <div className="divide-y divide-[var(--ov-08)]">
          {sessions.map((session) => {
            const Icon = DEVICE_ICONS[session.deviceType] || Monitor;
            return (
              <div
                key={session.id}
                className="py-4 flex flex-col sm:flex-row sm:items-center justify-between gap-3 first:pt-2 last:pb-2"
              >
                {/* Device & Location Meta */}
                <div className="flex items-start gap-3.5">
                  <div
                    className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 border ${
                      session.isCurrent
                        ? "bg-emerald-500/10 border-emerald-500/30 text-emerald-500"
                        : "bg-[var(--ov-05)] border-[var(--ov-10)] text-[var(--muted)]"
                    }`}
                  >
                    <Icon size={20} aria-hidden="true" />
                  </div>

                  <div>
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="text-sm font-bold font-sora text-[var(--text)]">
                        {session.deviceName}
                      </span>
                      {session.isCurrent ? (
                        <span className="inline-flex items-center gap-1 text-[10px] font-bold px-2 py-0.5 rounded-full bg-emerald-500/10 text-emerald-500 border border-emerald-500/20">
                          <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                          This Device (Current)
                        </span>
                      ) : (
                        <span className="text-[10px] text-[var(--muted)] font-medium">
                          {session.lastActiveDisplay}
                        </span>
                      )}
                    </div>

                    <div className="flex flex-wrap items-center gap-x-2 gap-y-1 text-xs text-[var(--muted)] mt-1">
                      <span>{session.browser}</span>
                      <span>·</span>
                      <span>{session.os}</span>
                      <span>·</span>
                      <span className="flex items-center gap-1">
                        <Globe size={11} aria-hidden="true" />
                        <span>
                          {session.location.city}, {session.location.country}
                        </span>
                      </span>
                      <span>·</span>
                      <span className="font-mono text-[11px] text-[var(--faint)]">
                        {session.ipAddress}
                      </span>
                    </div>
                  </div>
                </div>

                {/* Revoke Action */}
                <div className="flex items-center justify-end">
                  {session.isCurrent ? (
                    <span className="text-xs text-[var(--muted)] px-3 py-1.5 rounded-lg bg-[var(--ov-05)]">
                      Current Session
                    </span>
                  ) : (
                    <button
                      type="button"
                      onClick={() => setSessionToRevoke(session)}
                      className="px-3 py-1.5 rounded-xl border border-red-500/20 text-red-500 hover:bg-red-500/10 text-xs font-semibold transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-red-500"
                    >
                      Revoke
                    </button>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Confirmation Modal: Single Session Revoke */}
      {sessionToRevoke && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm animate-fade-in"
          role="dialog"
          aria-modal="true"
          aria-labelledby="revoke-modal-title"
        >
          <div className="relative w-full max-w-md rounded-3xl bg-[var(--modal)] border border-[var(--ov-14)] shadow-2xl p-6 text-[var(--text)]">
            <button
              type="button"
              onClick={() => setSessionToRevoke(null)}
              className="absolute top-5 right-5 p-1.5 rounded-full text-[var(--muted)] hover:text-[var(--text)]"
              aria-label="Close"
            >
              <X size={18} aria-hidden="true" />
            </button>

            <div className="w-12 h-12 rounded-2xl bg-red-500/10 text-red-500 flex items-center justify-center mb-4">
              <AlertTriangle size={24} aria-hidden="true" />
            </div>

            <h3 id="revoke-modal-title" className="text-lg font-bold font-sora">
              Revoke Session Access?
            </h3>
            <p className="text-xs text-[var(--muted)] mt-1.5">
              Are you sure you want to sign out <strong>{sessionToRevoke.deviceName}</strong> ({sessionToRevoke.location.city}, {sessionToRevoke.location.country})? Any unconfirmed transactions on that device will be canceled.
            </p>

            <div className="mt-6 flex items-center justify-end gap-2.5">
              <button
                type="button"
                onClick={() => setSessionToRevoke(null)}
                className="px-4 py-2 text-xs font-medium rounded-xl border border-[var(--ov-10)] hover:bg-[var(--ov-08)] transition-colors"
              >
                Cancel
              </button>
              <button
                type="button"
                disabled={revoking}
                onClick={handleRevokeSingle}
                className="px-4 py-2 text-xs font-semibold rounded-xl bg-red-600 hover:bg-red-700 text-white transition-colors disabled:opacity-50"
              >
                {revoking ? "Revoking..." : "Yes, Revoke Session"}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Confirmation Modal: Revoke All Other Sessions */}
      {showRevokeAllModal && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm animate-fade-in"
          role="dialog"
          aria-modal="true"
          aria-labelledby="revoke-all-modal-title"
        >
          <div className="relative w-full max-w-md rounded-3xl bg-[var(--modal)] border border-[var(--ov-14)] shadow-2xl p-6 text-[var(--text)]">
            <button
              type="button"
              onClick={() => setShowRevokeAllModal(false)}
              className="absolute top-5 right-5 p-1.5 rounded-full text-[var(--muted)] hover:text-[var(--text)]"
              aria-label="Close"
            >
              <X size={18} aria-hidden="true" />
            </button>

            <div className="w-12 h-12 rounded-2xl bg-red-500/10 text-red-500 flex items-center justify-center mb-4">
              <LogOut size={24} aria-hidden="true" />
            </div>

            <h3 id="revoke-all-modal-title" className="text-lg font-bold font-sora">
              Sign Out All Other Sessions?
            </h3>
            <p className="text-xs text-[var(--muted)] mt-1.5">
              This will immediately invalidate session tokens across all {otherSessionsCount} other connected devices. You will stay signed in on this device.
            </p>

            <div className="mt-6 flex items-center justify-end gap-2.5">
              <button
                type="button"
                onClick={() => setShowRevokeAllModal(false)}
                className="px-4 py-2 text-xs font-medium rounded-xl border border-[var(--ov-10)] hover:bg-[var(--ov-08)] transition-colors"
              >
                Cancel
              </button>
              <button
                type="button"
                disabled={revoking}
                onClick={handleRevokeAllOther}
                className="px-4 py-2 text-xs font-semibold rounded-xl bg-red-600 hover:bg-red-700 text-white transition-colors disabled:opacity-50"
              >
                {revoking ? "Signing Out..." : "Sign Out All Other Devices"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

