"use client";

import { useEffect, useState } from "react";
import { Moon } from "lucide-react";
import { Toggle } from "@/components/ui/Toggle";
import { useToast } from "@/components/ui/Toast";
import {
  DEFAULT_DND_SCHEDULE,
  DND_EXEMPTABLE_TYPES,
  getDndSchedule,
  getLocalTimezone,
  isWithinQuietHours,
  saveDndSchedule,
  type DndSchedule,
} from "@/lib/doNotDisturb";
import type { NotificationType } from "@/types/notification";

const DAYS = [
  { value: 1, short: "Mon", long: "Monday" },
  { value: 2, short: "Tue", long: "Tuesday" },
  { value: 3, short: "Wed", long: "Wednesday" },
  { value: 4, short: "Thu", long: "Thursday" },
  { value: 5, short: "Fri", long: "Friday" },
  { value: 6, short: "Sat", long: "Saturday" },
  { value: 0, short: "Sun", long: "Sunday" },
];

export default function DoNotDisturbPreferences() {
  const { showToast } = useToast();
  const [schedule, setSchedule] = useState<DndSchedule>(DEFAULT_DND_SCHEDULE);
  const [savedSchedule, setSavedSchedule] = useState<DndSchedule>(DEFAULT_DND_SCHEDULE);
  const [timezone, setTimezone] = useState("local time");

  useEffect(() => {
    const stored = getDndSchedule();
    setSchedule(stored);
    setSavedSchedule(stored);
    setTimezone(getLocalTimezone());
  }, []);

  const update = (patch: Partial<DndSchedule>) => setSchedule((s) => ({ ...s, ...patch }));

  const toggleDay = (day: number) =>
    update({
      days: schedule.days.includes(day) ? schedule.days.filter((d) => d !== day) : [...schedule.days, day],
    });

  const toggleExempt = (type: NotificationType, exempt: boolean) =>
    update({
      exemptTypes: exempt
        ? [...schedule.exemptTypes, type]
        : schedule.exemptTypes.filter((t) => t !== type),
    });

  const invalid = schedule.enabled && (schedule.start === schedule.end || schedule.days.length === 0);
  const dirty = JSON.stringify(schedule) !== JSON.stringify(savedSchedule);
  const activeNow = isWithinQuietHours(savedSchedule);

  const handleSave = () => {
    if (invalid) return;
    saveDndSchedule(schedule);
    setSavedSchedule(schedule);
    showToast({
      title: schedule.enabled ? "Do Not Disturb scheduled" : "Do Not Disturb turned off",
      message: schedule.enabled
        ? `Quiet hours ${schedule.start}–${schedule.end} (${timezone}).`
        : "You'll receive push and sound alerts as they happen.",
      variant: "success",
    });
  };

  return (
    <section className="p-6 rounded-2xl bg-[var(--content)] border border-[var(--ov-10)] space-y-5">
      <div className="flex items-start justify-between gap-3">
        <div>
          <h2 className="text-base font-bold font-sora text-[var(--text)] flex items-center gap-2">
            <Moon size={18} aria-hidden="true" />
            Do Not Disturb
          </h2>
          <p className="mt-1 text-sm text-[var(--muted)]">
            Silence push and sound alerts during quiet hours. Anything that arrives is held and
            shows up in your notification center when quiet hours end.
          </p>
        </div>
        {activeNow && (
          <span className="shrink-0 rounded-full bg-[#4B6B76]/15 px-2.5 py-1 text-xs font-medium text-[#4B6B76]">
            Active now
          </span>
        )}
      </div>

      <Toggle
        id="dnd-enabled"
        checked={schedule.enabled}
        onChange={(enabled) => update({ enabled })}
        label="Enable quiet hours"
        description={`Times use your timezone: ${timezone}`}
      />

      <fieldset disabled={!schedule.enabled} className="space-y-5 disabled:opacity-50">
        <div className="flex flex-wrap gap-4">
          <div>
            <label htmlFor="dnd-start" className="block text-xs text-[var(--muted)] mb-1.5">
              Starts
            </label>
            <input
              id="dnd-start"
              type="time"
              value={schedule.start}
              onChange={(e) => update({ start: e.target.value })}
              className="bg-[var(--ov-0a)] border border-[var(--ov-14)] rounded-xl px-4 py-2.5 text-[var(--text)] text-sm focus:outline-none focus:ring-2 focus:ring-[#4B6B76]"
            />
          </div>
          <div>
            <label htmlFor="dnd-end" className="block text-xs text-[var(--muted)] mb-1.5">
              Ends
            </label>
            <input
              id="dnd-end"
              type="time"
              value={schedule.end}
              onChange={(e) => update({ end: e.target.value })}
              className="bg-[var(--ov-0a)] border border-[var(--ov-14)] rounded-xl px-4 py-2.5 text-[var(--text)] text-sm focus:outline-none focus:ring-2 focus:ring-[#4B6B76]"
            />
          </div>
        </div>
        {schedule.end < schedule.start && (
          <p className="-mt-3 text-xs text-[var(--muted)]">Overnight: ends the following morning.</p>
        )}

        <fieldset>
          <legend className="text-xs text-[var(--muted)] mb-2">On these days</legend>
          <div className="flex flex-wrap gap-2">
            {DAYS.map((day) => {
              const selected = schedule.days.includes(day.value);
              return (
                <button
                  key={day.value}
                  type="button"
                  onClick={() => toggleDay(day.value)}
                  aria-pressed={selected}
                  aria-label={day.long}
                  className={`rounded-full px-3 py-1.5 text-xs font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76] ${
                    selected
                      ? "bg-[#4B6B76] text-white"
                      : "bg-[var(--ov-0a)] text-[var(--muted)] hover:text-[var(--text)]"
                  }`}
                >
                  {day.short}
                </button>
              );
            })}
          </div>
        </fieldset>

        <fieldset className="space-y-1">
          <legend className="text-xs text-[var(--muted)] mb-1">Critical alerts that still come through</legend>
          {DND_EXEMPTABLE_TYPES.map((item) => (
            <Toggle
              key={item.type}
              id={`dnd-exempt-${item.type}`}
              checked={schedule.exemptTypes.includes(item.type)}
              onChange={(checked) => toggleExempt(item.type, checked)}
              label={item.label}
              description={item.description}
            />
          ))}
        </fieldset>
      </fieldset>

      {invalid && (
        <p role="alert" className="text-xs text-red-400">
          {schedule.days.length === 0 ? "Pick at least one day." : "Start and end times must be different."}
        </p>
      )}

      <button
        type="button"
        onClick={handleSave}
        disabled={!dirty || invalid}
        className="rounded-lg bg-[#4B6B76] px-4 py-2 text-sm font-medium text-white transition-colors hover:bg-[#3D5A64] disabled:cursor-not-allowed disabled:opacity-50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76]"
      >
        Save quiet hours
      </button>
    </section>
  );
}

"use client";

import { useEffect, useState } from "react";
import {
  Bell,
  Mail,
  DollarSign,
  Shield,
  Users,
  Clock,
  CheckCircle2,
  AlertCircle,
  Save,
  Radio,
} from "lucide-react";
import { Toggle } from "@/components/ui/Toggle";
import { useEmailVerification } from "@/hooks/useEmailVerification";

const NOTIFICATIONS_STORAGE_KEY = "ahjoorxmr:notification-settings";

export interface GroupedNotificationSettings {
  // Contributions & Circles
  emailRoundCompletions: boolean;
  emailContributionReminders: boolean;
  emailMissedContributions: boolean;
  emailCircleStatusUpdates: boolean;

  // Payouts & Treasury
  emailPayoutConfirmations: boolean;
  emailUpcomingPayoutAlerts: boolean;
  emailEscrowReleases: boolean;

  // Disputes & Governance
  emailDisputeUpdates: boolean;
  emailGovernanceVotes: boolean;

  // Social & Referrals
  emailReferralActivity: boolean;
  emailAchievementUnlocks: boolean;

  // In-app mirrors
  inAppRoundCompletions: boolean;
  inAppContributionReminders: boolean;
  inAppMissedContributions: boolean;
  inAppPayoutConfirmations: boolean;
  inAppDisputeUpdates: boolean;
  inAppReferralActivity: boolean;

  // Reminder offsets & digest
  reminderOffsets: number[];
  emailFrequency: "instant" | "daily-digest" | "weekly-summary";
}

export const defaultNotificationSettings: GroupedNotificationSettings = {
  emailRoundCompletions: true,
  emailContributionReminders: true,
  emailMissedContributions: true,
  emailCircleStatusUpdates: true,

  emailPayoutConfirmations: true,
  emailUpcomingPayoutAlerts: true,
  emailEscrowReleases: true,

  emailDisputeUpdates: true,
  emailGovernanceVotes: false,

  emailReferralActivity: true,
  emailAchievementUnlocks: true,

  inAppRoundCompletions: true,
  inAppContributionReminders: true,
  inAppMissedContributions: true,
  inAppPayoutConfirmations: true,
  inAppDisputeUpdates: true,
  inAppReferralActivity: true,

  reminderOffsets: [3, 1],
  emailFrequency: "instant",
};

const reminderOptions = [
  { offset: 3, label: "3 days before", description: "Advance heads-up before the round deadline" },
  { offset: 1, label: "1 day before", description: "Urgent reminder the day before contribution is due" },
  { offset: 0, label: "On the day", description: "Day-of notice when round window is closing" },
];

export default function EmailNotificationPreferences() {
  const [settings, setSettings] = useState<GroupedNotificationSettings>(
    defaultNotificationSettings
  );
  const [saveStatus, setSaveStatus] = useState<"idle" | "saving" | "success" | "error">(
    "idle"
  );
  const { isVerified } = useEmailVerification();

  useEffect(() => {
    try {
      const raw = localStorage.getItem(NOTIFICATIONS_STORAGE_KEY);
      if (raw) {
        const stored = JSON.parse(raw);
        setSettings({ ...defaultNotificationSettings, ...stored });
      }
    } catch {
      // ignore
    }
  }, []);

  const updateSetting = (key: keyof GroupedNotificationSettings, value: boolean) => {
    setSettings((prev) => ({ ...prev, [key]: value }));
  };

  const updateReminderOffset = (offset: number, checked: boolean) => {
    setSettings((prev) => {
      const offsets = checked
        ? [...prev.reminderOffsets, offset]
        : prev.reminderOffsets.filter((v) => v !== offset);
      return {
        ...prev,
        reminderOffsets: offsets.sort((a, b) => b - a),
      };
    });
  };

  const handleSave = async () => {
    setSaveStatus("saving");
    try {
      localStorage.setItem(
        NOTIFICATIONS_STORAGE_KEY,
        JSON.stringify(settings)
      );
      // Simulate network save if endpoint exists
      await new Promise((resolve) => setTimeout(resolve, 400));
      setSaveStatus("success");
    } catch {
      setSaveStatus("error");
    } finally {
      setTimeout(() => setSaveStatus("idle"), 3500);
    }
  };

  return (
    <div className="space-y-6">
      {/* Header Banner */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 p-5 rounded-2xl bg-[var(--content)] border border-[var(--ov-10)]">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-[#4B6B76]/15 text-[#4B6B76] flex items-center justify-center">
            <Mail size={20} aria-hidden="true" />
          </div>
          <div>
            <h3 className="text-base font-bold font-sora text-[var(--text)]">
              Email Notification Events
            </h3>
            <p className="text-xs text-[var(--muted)]">
              Choose which circle milestones, payouts, and security events trigger email updates.
            </p>
          </div>
        </div>

        <button
          type="button"
          onClick={handleSave}
          disabled={saveStatus === "saving"}
          className="inline-flex items-center justify-center gap-2 px-4 py-2 rounded-xl bg-[#4B6B76] hover:bg-[#3D5A64] text-white text-xs font-semibold transition-colors disabled:opacity-50 shrink-0 shadow-sm"
        >
          {saveStatus === "saving" ? (
            <span>Saving...</span>
          ) : (
            <>
              <Save size={14} aria-hidden="true" />
              <span>Save Preferences</span>
            </>
          )}
        </button>
      </div>

      {saveStatus === "success" && (
        <div className="p-3.5 rounded-xl bg-emerald-500/10 border border-emerald-500/30 text-emerald-500 flex items-center gap-2 text-xs font-medium animate-fade-up">
          <CheckCircle2 size={16} aria-hidden="true" />
          <span>Your notification preferences have been successfully updated and saved.</span>
        </div>
      )}

      {saveStatus === "error" && (
        <div className="p-3.5 rounded-xl bg-red-500/10 border border-red-500/30 text-red-500 flex items-center gap-2 text-xs font-medium animate-fade-up">
          <AlertCircle size={16} aria-hidden="true" />
          <span>Failed to save preferences. Please try again.</span>
        </div>
      )}

       {!isVerified && (
        <div className="p-3.5 rounded-xl bg-blue-500/10 border border-blue-500/30 text-blue-600 dark:text-blue-400 flex items-center gap-2 text-xs font-medium">
          <AlertCircle size={16} aria-hidden="true" />
          <span>Email delivery is paused until you verify your email address.</span>
        </div>
      )}

      {/* Group 1: Contributions & Circles */}
      <section className="p-5 rounded-2xl bg-[var(--modal)] border border-[var(--ov-10)] space-y-4">
        <div className="flex items-center gap-2.5 pb-2 border-b border-[var(--ov-08)]">
          <Clock size={16} className="text-[#4B6B76]" aria-hidden="true" />
          <h4 className="text-sm font-bold font-sora text-[var(--text)]">
            Contributions & Rotating Rounds
          </h4>
        </div>

        <div className="divide-y divide-[var(--ov-08)]">
          <Toggle
            id="emailContributionReminders"
            label="Upcoming contribution reminders"
            checked={settings.emailContributionReminders}
            onChange={(v) => updateSetting("emailContributionReminders", v)}
          />
          <Toggle
            id="emailRoundCompletions"
            label="Round completion & rotation notices"
            checked={settings.emailRoundCompletions}
            onChange={(v) => updateSetting("emailRoundCompletions", v)}
          />
          <Toggle
            id="emailMissedContributions"
            label="Missed contributions & grace period alerts"
            checked={settings.emailMissedContributions}
            onChange={(v) => updateSetting("emailMissedContributions", v)}
          />
          <Toggle
            id="emailCircleStatusUpdates"
            label="Circle fill and activation status changes"
            checked={settings.emailCircleStatusUpdates}
            onChange={(v) => updateSetting("emailCircleStatusUpdates", v)}
          />
        </div>

        {/* Contribution Reminder Schedule Offsets */}
        {settings.emailContributionReminders && (
          <div className="mt-4 pt-4 border-t border-[var(--ov-08)]">
            <h5 className="text-xs font-semibold uppercase tracking-wider text-[var(--muted)] mb-2">
              Reminder Schedule Timing
            </h5>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-2.5">
              {reminderOptions.map(({ offset, label, description }) => (
                <label
                  key={offset}
                  htmlFor={`reminder-setting-${offset}`}
                  className="flex items-start gap-2.5 p-3 rounded-xl border border-[var(--ov-10)] bg-[var(--ov-03)] hover:bg-[var(--ov-06)] cursor-pointer transition-colors has-[:checked]:border-[#4B6B76] has-[:checked]:bg-[#4B6B76]/5"
                >
                  <input
                    id={`reminder-setting-${offset}`}
                    type="checkbox"
                    checked={settings.reminderOffsets.includes(offset)}
                    onChange={(e) => updateReminderOffset(offset, e.target.checked)}
                    className="mt-0.5 rounded border-[var(--ov-1a)] text-[#4B6B76] focus:ring-[#4B6B76] w-3.5 h-3.5"
                  />
                  <div>
                    <span className="block text-xs font-semibold text-[var(--text)]">
                      {label}
                    </span>
                    <span className="block text-[10px] text-[var(--muted)] mt-0.5">
                      {description}
                    </span>
                  </div>
                </label>
              ))}
            </div>
          </div>
        )}
      </section>

      {/* Group 2: Payouts & Treasury */}
      <section className="p-5 rounded-2xl bg-[var(--modal)] border border-[var(--ov-10)] space-y-4">
        <div className="flex items-center gap-2.5 pb-2 border-b border-[var(--ov-08)]">
          <DollarSign size={16} className="text-emerald-500" aria-hidden="true" />
          <h4 className="text-sm font-bold font-sora text-[var(--text)]">
            Payouts & Treasury
          </h4>
        </div>

        <div className="divide-y divide-[var(--ov-08)]">
          <Toggle
            id="emailPayoutConfirmations"
            label="Payout confirmations & wallet deposit receipts"
            checked={settings.emailPayoutConfirmations}
            onChange={(v) => updateSetting("emailPayoutConfirmations", v)}
          />
          <Toggle
            id="emailUpcomingPayoutAlerts"
            label="Upcoming payout turn reminders"
            checked={settings.emailUpcomingPayoutAlerts}
            onChange={(v) => updateSetting("emailUpcomingPayoutAlerts", v)}
          />
          <Toggle
            id="emailEscrowReleases"
            label="Collateral return & escrow release confirmations"
            checked={settings.emailEscrowReleases}
            onChange={(v) => updateSetting("emailEscrowReleases", v)}
          />
        </div>
      </section>

      {/* Group 3: Disputes & Governance */}
      <section className="p-5 rounded-2xl bg-[var(--modal)] border border-[var(--ov-10)] space-y-4">
        <div className="flex items-center gap-2.5 pb-2 border-b border-[var(--ov-08)]">
          <Shield size={16} className="text-amber-500" aria-hidden="true" />
          <h4 className="text-sm font-bold font-sora text-[var(--text)]">
            Disputes & Pool Governance
          </h4>
        </div>

        <div className="divide-y divide-[var(--ov-08)]">
          <Toggle
            id="emailDisputeUpdates"
            label="Dispute filed and arbitrator resolution updates"
            checked={settings.emailDisputeUpdates}
            onChange={(v) => updateSetting("emailDisputeUpdates", v)}
          />
          <Toggle
            id="emailGovernanceVotes"
            label="Circle organizer calls and parameter vote requests"
            checked={settings.emailGovernanceVotes}
            onChange={(v) => updateSetting("emailGovernanceVotes", v)}
          />
        </div>
      </section>

      {/* Group 4: Social & Referrals */}
      <section className="p-5 rounded-2xl bg-[var(--modal)] border border-[var(--ov-10)] space-y-4">
        <div className="flex items-center gap-2.5 pb-2 border-b border-[var(--ov-08)]">
          <Users size={16} className="text-purple-400" aria-hidden="true" />
          <h4 className="text-sm font-bold font-sora text-[var(--text)]">
            Social, Referrals & Achievements
          </h4>
        </div>

        <div className="divide-y divide-[var(--ov-08)]">
          <Toggle
            id="emailReferralActivity"
            label="Referral bonuses earned and new referee circle joins"
            checked={settings.emailReferralActivity}
            onChange={(v) => updateSetting("emailReferralActivity", v)}
          />
          <Toggle
            id="emailAchievementUnlocks"
            label="Achievement milestone badges unlocked"
            checked={settings.emailAchievementUnlocks}
            onChange={(v) => updateSetting("emailAchievementUnlocks", v)}
          />
        </div>
      </section>

      {/* Group 5: Delivery Frequency */}
      <section className="p-5 rounded-2xl bg-[var(--modal)] border border-[var(--ov-10)] space-y-3">
        <h4 className="text-sm font-bold font-sora text-[var(--text)]">
          Email Delivery Digest Frequency
        </h4>
        <p className="text-xs text-[var(--muted)]">
          Control whether emails are delivered instantly upon occurrence or bundled into a periodic summary.
        </p>

        <div className="grid grid-cols-1 sm:grid-cols-3 gap-2.5 pt-1">
          {[
            {
              id: "instant",
              label: "Instant Real-Time",
              desc: "Immediate delivery for all enabled events",
            },
            {
              id: "daily-digest",
              label: "Daily Digest",
              desc: "One compiled morning email summarizing activities",
            },
            {
              id: "weekly-summary",
              label: "Weekly Summary",
              desc: "Consolidated weekend digest of pool status",
            },
          ].map((item) => (
            <label
              key={item.id}
              className={`p-3 rounded-xl border cursor-pointer transition-colors flex flex-col justify-between ${
                settings.emailFrequency === item.id
                  ? "border-[#4B6B76] bg-[#4B6B76]/10"
                  : "border-[var(--ov-10)] bg-[var(--ov-03)] hover:bg-[var(--ov-06)]"
              }`}
            >
              <div className="flex items-center justify-between mb-1">
                <span className="text-xs font-semibold text-[var(--text)]">
                  {item.label}
                </span>
                <input
                  type="radio"
                  name="emailFrequency"
                  value={item.id}
                  checked={settings.emailFrequency === item.id}
                  onChange={() =>
                    setSettings((prev) => ({
                      ...prev,
                      emailFrequency: item.id as GroupedNotificationSettings["emailFrequency"],
                    }))
                  }
                  className="text-[#4B6B76] focus:ring-[#4B6B76]"
                />
              </div>
              <span className="text-[10px] text-[var(--muted)]">
                {item.desc}
              </span>
            </label>
          ))}
        </div>
      </section>

      {/* Save Button Footer */}
      <div className="flex items-center gap-3 pt-2">
        <button
          type="button"
          onClick={handleSave}
          disabled={saveStatus === "saving"}
          className="px-6 py-2.5 rounded-xl bg-[#4B6B76] hover:bg-[#3D5A64] text-white text-sm font-semibold transition-colors disabled:opacity-50 shadow-sm"
        >
          {saveStatus === "saving" ? "Saving..." : "Save Changes"}
        </button>
        {saveStatus === "success" && (
          <span className="text-xs font-semibold text-emerald-500 flex items-center gap-1">
            <CheckCircle2 size={14} aria-hidden="true" />
            <span>Settings saved successfully.</span>
          </span>
        )}
      </div>
    </div>
  );
}

"use client";

import { useRef, useState } from "react";
import { Bell, BellOff, BellRing, ShieldAlert, ExternalLink } from "lucide-react";
import { Toggle } from "@/components/ui/Toggle";
import { usePushNotifications } from "@/hooks/usePushNotifications";
import { useFocusTrap } from "@/hooks/useFocusTrap";

// ---------------------------------------------------------------------------
// Explanation dialog shown before the native browser prompt fires
// ---------------------------------------------------------------------------
function PermissionExplainerDialog({
  onConfirm,
  onCancel,
  isRequesting,
}: {
  onConfirm: () => void;
  onCancel: () => void;
  isRequesting: boolean;
}) {
  const dialogRef = useRef<HTMLDivElement>(null);
  useFocusTrap(dialogRef, true, onCancel);

  return (
    // Backdrop
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm"
      role="presentation"
      onClick={(e) => {
        if (e.target === e.currentTarget) onCancel();
      }}
    >
      <div
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby="push-dialog-title"
        aria-describedby="push-dialog-desc"
        className="w-full max-w-sm rounded-2xl border border-[var(--ov-14)] p-6 shadow-2xl"
        style={{ background: "var(--modal)" }}
      >
        {/* Icon */}
        <div className="flex items-center justify-center w-12 h-12 rounded-xl bg-[var(--accent-soft)] mb-5 mx-auto">
          <BellRing size={22} className="text-[var(--accent)]" aria-hidden="true" />
        </div>

        <h2
          id="push-dialog-title"
          className="text-base font-semibold text-center text-[var(--text)] mb-2"
        >
          Enable push notifications?
        </h2>
        <p
          id="push-dialog-desc"
          className="text-sm text-center text-[var(--muted)] mb-6 leading-relaxed"
        >
          Ahjoor will ask for your browser's permission to send you
          notifications. We'll only send alerts for the categories you turn on —
          contribution reminders, payout alerts, and dispute updates.
        </p>

        <div className="space-y-2">
          <button
            type="button"
            onClick={onConfirm}
            disabled={isRequesting}
            className="w-full rounded-xl py-2.5 text-sm font-semibold text-white bg-[var(--accent)] hover:opacity-90 disabled:opacity-50 transition-opacity focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--modal)]"
          >
            {isRequesting ? "Requesting permission…" : "Allow notifications"}
          </button>
          <button
            type="button"
            onClick={onCancel}
            disabled={isRequesting}
            className="w-full rounded-xl py-2.5 text-sm font-medium text-[var(--muted)] bg-[var(--ov-07)] hover:bg-[var(--ov-0f)] disabled:opacity-50 transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76]"
          >
            Not now
          </button>
        </div>
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Status banner shown when permission is denied or browser is unsupported
// ---------------------------------------------------------------------------
function UnsupportedBanner({ isDenied }: { isDenied: boolean }) {
  return (
    <div
      role="status"
      aria-live="polite"
      className="flex items-start gap-3 p-4 rounded-xl border border-[var(--ov-14)] bg-[var(--ov-05)]"
    >
      <ShieldAlert
        size={18}
        className="text-[var(--muted)] shrink-0 mt-0.5"
        aria-hidden="true"
      />
      <div className="flex-1 min-w-0">
        {isDenied ? (
          <>
            <p className="text-sm font-medium text-[var(--text)]">
              Browser notifications are blocked
            </p>
            <p className="text-xs text-[var(--muted)] mt-0.5">
              You've previously denied permission. To enable push notifications,
              update the site permissions in your browser settings and then
              return here.
            </p>
            <a
              href="https://support.google.com/chrome/answer/3220216"
              target="_blank"
              rel="noopener noreferrer"
              className="inline-flex items-center gap-1 text-xs text-[#4B6B76] hover:underline mt-1.5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76] rounded"
            >
              How to update permissions
              <ExternalLink size={11} aria-hidden="true" />
            </a>
          </>
        ) : (
          <>
            <p className="text-sm font-medium text-[var(--text)]">
              Push notifications aren't supported
            </p>
            <p className="text-xs text-[var(--muted)] mt-0.5">
              Your current browser doesn't support push notifications. Try
              Chrome, Edge, Firefox, or Safari 16.4+.
            </p>
          </>
        )}
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Main exported component
// ---------------------------------------------------------------------------
export default function PushNotificationPreferences() {
  const {
    isSupported,
    permission,
    isSubscribed,
    isRequesting,
    prefs,
    requestPermission,
    unsubscribe,
    updatePref,
  } = usePushNotifications();

  const [showExplainer, setShowExplainer] = useState(false);

  // What state is the opt-in button in?
  const isGranted = permission === "granted";
  const isDenied = permission === "denied";
  const canRequest = isSupported && permission === "default";

  async function handleMainToggle(enabled: boolean) {
    if (!enabled) {
      await unsubscribe();
      return;
    }
    // Show the explainer before triggering the native prompt
    if (canRequest) {
      setShowExplainer(true);
    }
  }

  async function handleConfirmPermission() {
    setShowExplainer(false);
    await requestPermission();
  }

  function handleCancelExplainer() {
    setShowExplainer(false);
  }

  // The master toggle is "on" when we have permission and are subscribed
  const masterToggleChecked = isGranted && isSubscribed;

  // Preference toggles are only interactive when push is active
  const prefsDisabled = !masterToggleChecked;

  return (
    <>
      {showExplainer && (
        <PermissionExplainerDialog
          onConfirm={handleConfirmPermission}
          onCancel={handleCancelExplainer}
          isRequesting={isRequesting}
        />
      )}

      <section
        aria-labelledby="push-notif-heading"
        className="rounded-lg border border-gray-200 dark:border-[var(--border)] bg-white dark:bg-[var(--content)] p-5 lg:col-span-2"
      >
        {/* Section header */}
        <div className="flex items-center gap-2 mb-1">
          {isGranted && isSubscribed ? (
            <BellRing size={16} className="text-[var(--accent)] shrink-0" aria-hidden="true" />
          ) : (
            <Bell size={16} className="text-[var(--muted)] shrink-0" aria-hidden="true" />
          )}
          <h2
            id="push-notif-heading"
            className="text-base font-semibold text-gray-900 dark:text-[var(--text)]"
          >
            Browser push notifications
          </h2>
        </div>
        <p className="text-xs text-gray-500 dark:text-[var(--muted)] mb-4 ml-6">
          Receive real-time alerts even when Ahjoor isn't open in your browser.
          Distinct from in-app notifications.
        </p>

        {/* Unsupported / denied banner */}
        {(!isSupported || isDenied) && (
          <div className="mb-4">
            <UnsupportedBanner isDenied={isDenied} />
          </div>
        )}

        {/* Master opt-in toggle */}
        <div className="rounded-xl border border-gray-100 dark:border-[var(--ov-0f)] bg-gray-50 dark:bg-[var(--ov-03)] px-4 py-1 mb-4">
          <Toggle
            id="push-master"
            label="Enable browser push notifications"
            description={
              isGranted && isSubscribed
                ? "You're opted in. Toggle off to unsubscribe."
                : isDenied
                ? "Permission was denied — update your browser settings to enable this."
                : !isSupported
                ? "Not available in this browser."
                : "Click to request permission from your browser."
            }
            checked={masterToggleChecked}
            onChange={handleMainToggle}
            disabled={!isSupported || isDenied || isRequesting}
          />
        </div>

        {/* Per-type preference toggles */}
        <div
          aria-label="Push notification type preferences"
          className={prefsDisabled ? "opacity-50 pointer-events-none select-none" : ""}
        >
          <h3 className="text-xs font-semibold uppercase tracking-wide text-gray-400 dark:text-[var(--muted)] mb-1">
            Notify me about
          </h3>
          <div className="divide-y divide-gray-100 dark:divide-[var(--border)]">
            <Toggle
              id="push-contribution-reminders"
              label="Contribution reminders"
              description="Alerts when your next contribution is due or overdue."
              checked={prefs.contributionReminders}
              onChange={(v) => updatePref("contributionReminders", v)}
              disabled={prefsDisabled}
            />
            <Toggle
              id="push-payout-alerts"
              label="Payout alerts"
              description="Notifications when a payout is ready to claim."
              checked={prefs.payoutAlerts}
              onChange={(v) => updatePref("payoutAlerts", v)}
              disabled={prefsDisabled}
            />
            <Toggle
              id="push-dispute-updates"
              label="Dispute updates"
              description="Updates on disputes in circles you participate in."
              checked={prefs.disputeUpdates}
              onChange={(v) => updatePref("disputeUpdates", v)}
              disabled={prefsDisabled}
            />
          </div>
        </div>

        {/* Granted + subscribed confirmation pill */}
        {isGranted && isSubscribed && (
          <div
            role="status"
            aria-live="polite"
            className="mt-4 inline-flex items-center gap-1.5 text-xs font-medium text-[var(--success)] bg-[var(--success)]/10 rounded-full px-3 py-1"
          >
            <span
              className="w-1.5 h-1.5 rounded-full bg-[var(--success)]"
              aria-hidden="true"
            />
            Push notifications active
          </div>
        )}
      </section>
    </>
  );
}

"use client";

import { useId } from "react";
import { Globe } from "lucide-react";
import { useTimezone } from "@/hooks/useTimezone";
import {
  COMMON_TIMEZONES,
  getDefaultTimezone,
  getTimezoneAbbreviation,
  formatTimeWithTz,
} from "@/lib/timezone";

export default function TimezoneSetting() {
  const { timezone, setTimezone, timezoneAbbr } = useTimezone();
  const selectId = useId();
  const browserDefault = getDefaultTimezone();

  // Ensure current timezone and browser default are in the list
  const options = [...COMMON_TIMEZONES];
  if (!options.some((opt) => opt.value === timezone)) {
    options.unshift({ value: timezone, label: `${timezone} (Current)` });
  }
  if (!options.some((opt) => opt.value === browserDefault)) {
    options.unshift({ value: browserDefault, label: `${browserDefault} (Browser Default)` });
  }

  const now = new Date();
  const currentTimeDisplay = formatTimeWithTz(now, timezone);

  return (
    <div className="pt-4 border-t border-[var(--ov-10)]">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-3">
        <div className="flex items-start gap-2">
          <Globe size={16} className="text-[var(--muted)] mt-0.5 shrink-0" aria-hidden="true" />
          <div>
            <span className="block text-sm font-semibold text-[var(--text)]">
              Timezone
            </span>
            <span className="block text-xs text-[var(--muted)] mt-0.5">
              All deadlines, countdowns, and payout times will display in this timezone.
            </span>
          </div>
        </div>

        <div className="text-left sm:text-right">
          <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium bg-[var(--ov-0a)] text-[var(--text)] border border-[var(--ov-10)]">
            <span className="w-1.5 h-1.5 rounded-full bg-[var(--success)]" aria-hidden="true" />
            {currentTimeDisplay}
          </span>
        </div>
      </div>

      <div className="mt-2">
        <label htmlFor={selectId} className="sr-only">
          Select timezone
        </label>
        <select
          id={selectId}
          value={timezone}
          onChange={(e) => setTimezone(e.target.value)}
          className="w-full sm:w-auto min-w-[280px] bg-[var(--modal)] border border-[var(--ov-14)] rounded-xl px-3.5 py-2 text-sm text-[var(--text)] focus:outline-none focus:ring-2 focus:ring-[#4B6B76] cursor-pointer"
        >
          {options.map((opt) => (
            <option key={opt.value} value={opt.value}>
              {opt.label} {opt.value === browserDefault ? "★ (Browser)" : ""}
            </option>
          ))}
        </select>
        <p className="mt-1.5 text-xs text-[var(--faint)]">
          Abbreviation: <strong className="text-[var(--text)]">{timezoneAbbr}</strong> &middot; Default: {browserDefault}
        </p>
      </div>
    </div>
  );
}

