"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { PartyPopper, Trophy, Users, X } from "lucide-react";
import {
  CELEBRATE_EVENT,
  attachCelebrationOverlay,
  detachCelebrationOverlay,
  type CelebrationKind,
  type CelebrationMilestone,
} from "@/lib/milestoneCelebrations";
import { usePrefersReducedMotion } from "@/hooks/usePrefersReducedMotion";

const DISPLAY_MS = 5000;
const CONFETTI_MS = 2800;
const COLORS = ["#4ADE80", "#4B6B76", "#FBBF24", "#60A5FA", "#F472B6", "#A78BFA"];

const ICONS: Record<CelebrationKind, typeof Trophy> = {
  round_completed: PartyPopper,
  circle_fully_funded: Users,
  final_payout_completed: Trophy,
};

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  size: number;
  rotation: number;
  spin: number;
  color: string;
}

/** Runs a canvas confetti burst; returns a function that stops it early. */
function runConfetti(canvas: HTMLCanvasElement): () => void {
  // Guards the first render, before usePrefersReducedMotion has read the preference.
  if (window.matchMedia?.("(prefers-reduced-motion: reduce)").matches) return () => {};
  const ctx = canvas.getContext("2d");
  if (!ctx) return () => {};

  const dpr = window.devicePixelRatio || 1;
  const resize = () => {
    canvas.width = window.innerWidth * dpr;
    canvas.height = window.innerHeight * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  };
  resize();
  window.addEventListener("resize", resize);

  // Fewer particles on small screens keeps mobile smooth.
  const count = window.innerWidth < 640 ? 80 : 150;
  const particles: Particle[] = Array.from({ length: count }, () => ({
    x: window.innerWidth / 2 + (Math.random() - 0.5) * window.innerWidth * 0.3,
    y: window.innerHeight * 0.35,
    vx: (Math.random() - 0.5) * 12,
    vy: -Math.random() * 12 - 4,
    size: Math.random() * 6 + 4,
    rotation: Math.random() * Math.PI,
    spin: (Math.random() - 0.5) * 0.3,
    color: COLORS[Math.floor(Math.random() * COLORS.length)],
  }));

  const startedAt = performance.now();
  let frame = 0;

  const tick = (now: number) => {
    const elapsed = now - startedAt;
    ctx.clearRect(0, 0, window.innerWidth, window.innerHeight);
    ctx.globalAlpha = Math.max(0, 1 - elapsed / CONFETTI_MS);
    for (const p of particles) {
      p.vy += 0.35; // gravity
      p.vx *= 0.99;
      p.x += p.vx;
      p.y += p.vy;
      p.rotation += p.spin;
      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.rotate(p.rotation);
      ctx.fillStyle = p.color;
      ctx.fillRect(-p.size / 2, -p.size / 4, p.size, p.size / 2);
      ctx.restore();
    }
    if (elapsed < CONFETTI_MS) frame = requestAnimationFrame(tick);
    else ctx.clearRect(0, 0, window.innerWidth, window.innerHeight);
  };
  frame = requestAnimationFrame(tick);

  return () => {
    cancelAnimationFrame(frame);
    window.removeEventListener("resize", resize);
    ctx.clearRect(0, 0, window.innerWidth, window.innerHeight);
  };
}

/**
 * Global overlay that plays when a milestone is celebrated. It's fixed and
 * pointer-transparent (except the card), so it never shifts layout or blocks
 * the page. Multiple milestones queue and play one after another.
 */
export default function MilestoneCelebration() {
  const [queue, setQueue] = useState<CelebrationMilestone[]>([]);
  const reducedMotion = usePrefersReducedMotion();
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const current = queue[0] ?? null;

  const dismiss = useCallback(() => setQueue((q) => q.slice(1)), []);

  useEffect(() => {
    const onCelebrate = (e: Event) => {
      const milestone = (e as CustomEvent<CelebrationMilestone>).detail;
      if (milestone) setQueue((q) => (q.some((m) => m.key === milestone.key) ? q : [...q, milestone]));
    };
    window.addEventListener(CELEBRATE_EVENT, onCelebrate);
    const pending = attachCelebrationOverlay();
    if (pending.length) setQueue((q) => [...q, ...pending.filter((m) => !q.some((x) => x.key === m.key))]);
    return () => {
      detachCelebrationOverlay();
      window.removeEventListener(CELEBRATE_EVENT, onCelebrate);
    };
  }, []);

  useEffect(() => {
    if (!current) return;
    const stopConfetti = !reducedMotion && canvasRef.current ? runConfetti(canvasRef.current) : () => {};
    const timer = window.setTimeout(dismiss, DISPLAY_MS);
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") dismiss();
    };
    document.addEventListener("keydown", onKey);
    return () => {
      stopConfetti();
      window.clearTimeout(timer);
      document.removeEventListener("keydown", onKey);
    };
  }, [current, reducedMotion, dismiss]);

  if (!current) return null;
  const Icon = ICONS[current.kind];

  return (
    <div className="pointer-events-none fixed inset-0 z-[90]" aria-live="polite">
      {!reducedMotion && <canvas ref={canvasRef} className="absolute inset-0 h-full w-full" aria-hidden="true" />}

      <div
        role="status"
        className={`pointer-events-auto absolute inset-x-4 bottom-24 mx-auto flex max-w-sm items-start gap-3 rounded-2xl border border-[var(--ov-14)] bg-[var(--modal)] p-4 shadow-2xl sm:bottom-auto sm:top-6 ${
          reducedMotion ? "" : "animate-[celebrate-pop_300ms_ease-out]"
        }`}
      >
        <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-[#4ADE80]/15 text-[#4ADE80]">
          <Icon size={20} aria-hidden="true" />
        </span>
        <div className="min-w-0 flex-1">
          <p className="text-sm font-semibold text-[var(--text)]">{current.title}</p>
          <p className="mt-0.5 text-sm text-[var(--muted)]">{current.message}</p>
        </div>
        <button
          type="button"
          onClick={dismiss}
          className="rounded-full p-1 text-[var(--muted)] transition-colors hover:bg-[var(--ov-0a)] hover:text-[var(--text)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76]"
          aria-label="Dismiss celebration"
        >
          <X size={16} aria-hidden="true" />
        </button>
      </div>
    </div>
  );
}

"use client";

import { useRef, useState, useCallback } from "react";
import {
  Share2,
  Download,
  Copy,
  Check,
  X,
  Loader2,
  AlertCircle,
  ExternalLink,
} from "lucide-react";
import { useShareCard } from "@/hooks/useShareCard";
import { useFocusTrap } from "@/hooks/useFocusTrap";
import type { MilestoneData, MilestoneType } from "@/types/milestone";

// ---------------------------------------------------------------------------
// Milestone type display helpers
// ---------------------------------------------------------------------------
const TYPE_LABELS: Record<MilestoneType, string> = {
  circle_completed: "Circle Completed",
  payout_received: "Payout Received",
  savings_goal: "Savings Goal Hit",
  streak: "Streak Achieved",
  annual_summary: "Annual Savings Wrapped",
};

const TYPE_ACCENT: Record<MilestoneType, string> = {
  circle_completed: "text-[var(--success)]",
  payout_received: "text-[#FBBF24]",
  savings_goal: "text-[var(--accent)]",
  streak: "text-[#FF5B5B]",
  annual_summary: "text-[#6c5ce7]",
};

// ---------------------------------------------------------------------------
// Props
// ---------------------------------------------------------------------------
interface ShareMilestoneButtonProps {
  milestone: MilestoneData;
  /** Optional URL to share/copy; defaults to current page URL */
  shareUrl?: string;
  /** Visual variant of the trigger button */
  variant?: "default" | "icon" | "subtle";
  className?: string;
}

// ---------------------------------------------------------------------------
// Main component
// ---------------------------------------------------------------------------
export default function ShareMilestoneButton({
  milestone,
  shareUrl,
  variant = "default",
  className = "",
}: ShareMilestoneButtonProps) {
  const [modalOpen, setModalOpen] = useState(false);
  const [copied, setCopied] = useState(false);

  const { status, previewUrl, openShare, download, nativeShare, copyLink, reset, errorMessage } =
    useShareCard();

  const modalRef = useRef<HTMLDivElement>(null);
  useFocusTrap(modalRef, modalOpen, handleClose);

  function handleClose() {
    reset();
    setModalOpen(false);
  }

  async function handleOpen() {
    setModalOpen(true);
    await openShare(milestone);
  }

  async function handleNativeShare() {
    await nativeShare(milestone, shareUrl);
  }

  async function handleCopyLink() {
    const ok = await copyLink(shareUrl);
    if (ok) {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  }

  function handleDownload() {
    const slug = milestone.circleName.toLowerCase().replace(/\s+/g, "-");
    download(`ahjoor-${milestone.type}-${slug}.png`);
  }

  const supportsNativeShare = typeof navigator !== "undefined" && "share" in navigator;

  // ---------------------------------------------------------------------------
  // Trigger button styles
  // ---------------------------------------------------------------------------
  const triggerBase =
    "inline-flex items-center gap-2 font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76]";

  const triggerStyles = {
    default: `${triggerBase} px-4 py-2 text-sm rounded-lg bg-[var(--ov-0a)] hover:bg-[var(--ov-14)] text-[var(--text)]`,
    icon: `${triggerBase} w-9 h-9 justify-center rounded-lg bg-[var(--ov-0a)] hover:bg-[var(--ov-14)] text-[var(--muted)] hover:text-[var(--text)]`,
    subtle: `${triggerBase} px-3 py-1.5 text-xs rounded-lg text-[#4B6B76] hover:bg-[var(--ov-0a)]`,
  };

  return (
    <>
      {/* Trigger */}
      <button
        type="button"
        onClick={handleOpen}
        className={`${triggerStyles[variant]} ${className}`}
        aria-label={`Share ${TYPE_LABELS[milestone.type]} milestone for ${milestone.circleName}`}
      >
        <Share2 size={variant === "icon" ? 16 : 14} aria-hidden="true" />
        {variant !== "icon" && <span>Share</span>}
      </button>

      {/* Modal */}
      {modalOpen && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm"
          role="presentation"
          onClick={(e) => {
            if (e.target === e.currentTarget) handleClose();
          }}
        >
          <div
            ref={modalRef}
            role="dialog"
            aria-modal="true"
            aria-labelledby="share-modal-title"
            className="w-full max-w-lg rounded-2xl border border-[var(--ov-14)] shadow-2xl overflow-hidden"
            style={{ background: "var(--modal)" }}
          >
            {/* Header */}
            <div className="flex items-center justify-between px-5 py-4 border-b border-[var(--ov-0f)]">
              <div>
                <h2
                  id="share-modal-title"
                  className="text-sm font-semibold text-[var(--text)]"
                >
                  Share milestone
                </h2>
                <p className={`text-xs mt-0.5 ${TYPE_ACCENT[milestone.type]}`}>
                  {TYPE_LABELS[milestone.type]} · {milestone.circleName}
                </p>
              </div>
              <button
                type="button"
                onClick={handleClose}
                className="p-1.5 rounded-lg text-[var(--muted)] hover:text-[var(--text)] hover:bg-[var(--ov-0a)] transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76]"
                aria-label="Close share dialog"
              >
                <X size={16} />
              </button>
            </div>

            {/* Card Preview */}
            <div className="px-5 pt-5">
              <div
                className="relative w-full rounded-xl overflow-hidden border border-[var(--ov-0f)]"
                style={{ aspectRatio: "1200 / 630" }}
                aria-label="Share card preview"
              >
                {/* Loading state */}
                {status === "rendering" && (
                  <div className="absolute inset-0 flex flex-col items-center justify-center bg-[var(--bg)] gap-3">
                    <Loader2 size={28} className="text-[var(--muted)] animate-spin" aria-hidden="true" />
                    <p className="text-xs text-[var(--muted)]">Generating card…</p>
                  </div>
                )}

                {/* Error state */}
                {status === "error" && (
                  <div className="absolute inset-0 flex flex-col items-center justify-center bg-[var(--bg)] gap-3 p-6 text-center">
                    <AlertCircle size={28} className="text-[#FF5B5B]" aria-hidden="true" />
                    <p className="text-xs text-[var(--muted)]">
                      {errorMessage ?? "Could not generate the share card."}
                    </p>
                    <button
                      type="button"
                      onClick={() => openShare(milestone)}
                      className="text-xs text-[#4B6B76] hover:underline focus-visible:outline-none"
                    >
                      Try again
                    </button>
                  </div>
                )}

                {/* Rendered preview */}
                {previewUrl && status !== "error" && (
                  // eslint-disable-next-line @next/next/no-img-element
                  <img
                    src={previewUrl}
                    alt={`Share card for ${milestone.circleName} ${TYPE_LABELS[milestone.type]}`}
                    className="w-full h-full object-cover"
                    draggable={false}
                  />
                )}
              </div>
            </div>

            {/* Actions */}
            <div className="px-5 pb-5 pt-4 space-y-3">
              {/* Primary row */}
              <div className="flex gap-2">
                {/* Download */}
                <button
                  type="button"
                  onClick={handleDownload}
                  disabled={status === "rendering" || status === "error"}
                  className="flex-1 inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-xl text-sm font-semibold text-white bg-[var(--accent)] hover:opacity-90 disabled:opacity-40 transition-opacity focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--modal)]"
                >
                  <Download size={15} aria-hidden="true" />
                  Download PNG
                </button>

                {/* Native Share (when supported) */}
                {supportsNativeShare && (
                  <button
                    type="button"
                    onClick={handleNativeShare}
                    disabled={status === "rendering" || status === "sharing" || status === "error"}
                    className="flex-1 inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-xl text-sm font-semibold text-[var(--text)] bg-[var(--ov-0f)] hover:bg-[var(--ov-1a)] disabled:opacity-40 transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76]"
                  >
                    {status === "sharing" ? (
                      <Loader2 size={15} className="animate-spin" aria-hidden="true" />
                    ) : (
                      <ExternalLink size={15} aria-hidden="true" />
                    )}
                    Share
                  </button>
                )}
              </div>

              {/* Copy link row */}
              <button
                type="button"
                onClick={handleCopyLink}
                className="w-full inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-xl text-sm font-medium text-[var(--muted)] bg-[var(--ov-07)] hover:bg-[var(--ov-0f)] hover:text-[var(--text)] transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76]"
              >
                {copied ? (
                  <>
                    <Check size={15} className="text-[var(--success)]" aria-hidden="true" />
                    <span className="text-[var(--success)]">Link copied!</span>
                  </>
                ) : (
                  <>
                    <Copy size={15} aria-hidden="true" />
                    Copy link
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

"use client";

/**
 * Issue #218 – Add Friendbot Testnet Funding Button.
 *
 * Renders a "Fund with Friendbot" button only when the active network is
 * "testnet".  Calls the Stellar Friendbot faucet for the connected address,
 * shows a toast on success or failure, and triggers a balance refresh.
 * Hidden entirely on mainnet builds.
 */

import { useState, useCallback } from "react";
import { useWallet } from "@/contexts/WalletContext";

const FRIENDBOT_URL = "https://friendbot.stellar.org";

interface FriendbotButtonProps {
  /** Extra Tailwind classes */
  className?: string;
}

export function FriendbotButton({ className = "" }: FriendbotButtonProps) {
  const { address, isConnected, network, refreshBalance } = useWallet();
  const [isLoading, setIsLoading] = useState(false);
  const [toast, setToast] = useState<{ message: string; type: "success" | "error" } | null>(null);

  const showToast = (message: string, type: "success" | "error") => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 4000);
  };

  const handleFundWithFriendbot = useCallback(async () => {
    if (!address) return;
    setIsLoading(true);
    try {
      const url = `${FRIENDBOT_URL}/?addr=${encodeURIComponent(address)}`;
      const res = await fetch(url);
      if (res.ok) {
        showToast("Account funded successfully via Friendbot!", "success");
        await refreshBalance();
      } else {
        const body = await res.text().catch(() => "");
        const detail = body ? ` (${body.slice(0, 80)})` : "";
        showToast(`Friendbot request failed: ${res.status}${detail}`, "error");
      }
    } catch (err) {
      showToast(
        err instanceof Error ? err.message : "Friendbot request failed",
        "error"
      );
    } finally {
      setIsLoading(false);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [address, refreshBalance]);

  // Only show on testnet. Kept below every hook so the hook order never changes between renders.
  if (network !== "testnet") return null;
  if (!isConnected || !address) return null;

  return (
    <div className={`relative inline-block ${className}`}>
      <button
        type="button"
        onClick={handleFundWithFriendbot}
        disabled={isLoading}
        className="flex items-center gap-1.5 rounded-md border border-yellow-400 bg-yellow-50 px-3 py-1.5 text-sm font-medium text-yellow-800 transition hover:bg-yellow-100 disabled:cursor-not-allowed disabled:opacity-60 dark:border-yellow-600 dark:bg-yellow-900/20 dark:text-yellow-300 dark:hover:bg-yellow-900/40"
        title="Fund your testnet account with 10 000 XLM via Stellar Friendbot"
      >
        {isLoading ? (
          <span className="inline-block h-4 w-4 animate-spin rounded-full border-2 border-current border-t-transparent" />
        ) : (
          <span aria-hidden="true">⭐</span>
        )}
        {isLoading ? "Funding…" : "Fund with Friendbot"}
      </button>

      {toast && (
        <div
          role="status"
          aria-live="polite"
          className={`absolute left-0 top-full z-50 mt-2 w-72 rounded-md p-3 text-sm shadow-lg ${
            toast.type === "success"
              ? "bg-green-50 text-green-800 dark:bg-green-900/40 dark:text-green-200"
              : "bg-red-50 text-red-800 dark:bg-red-900/40 dark:text-red-200"
          }`}
        >
          {toast.message}
        </div>
      )}
    </div>
  );
}

