"use client";

import { useState, useEffect, useMemo, useCallback } from "react";
import { AlertTriangle, X, Bell, BellOff, ExternalLink } from "lucide-react";

export interface LowBalanceAlertProps {
  /** Current wallet balance */
  balance: number;
  /** Upcoming contribution amount */
  upcomingContribution?: number;
  /** Days until contribution is due */
  daysUntilContribution?: number;
  /** Callback to navigate to deposit/top-up flow */
  onNavigateToDeposit?: () => void;
  /** Test mode - bypass date checks */
  testMode?: boolean;
}

const LOW_BALANCE_STORAGE_KEY = "ahjoor-low-balance-settings";

interface LowBalanceSettings {
  enabled: boolean;
  customThreshold?: number;
  dismissedAlerts: string[]; // timestamps of dismissed alerts
}

const DEFAULT_SETTINGS: LowBalanceSettings = {
  enabled: true,
  customThreshold: undefined,
  dismissedAlerts: [],
};

/**
 * Low-balance alert banner that warns users when their balance is insufficient
 * for an upcoming contribution.
 */
export function useLowBalanceAlert(
  balance: number,
  upcomingContribution: number = 0,
  daysUntilContribution: number = 7,
  testMode: boolean = false
) {
  const [settings, setSettings] = useState<LowBalanceSettings>(DEFAULT_SETTINGS);
  const [showAlert, setShowAlert] = useState(false);

  // Load settings from localStorage
  useEffect(() => {
    try {
      const stored = localStorage.getItem(LOW_BALANCE_STORAGE_KEY);
      if (stored) {
        setSettings({ ...DEFAULT_SETTINGS, ...JSON.parse(stored) });
      }
    } catch {
      // ignore
    }
  }, []);

  // Determine threshold (custom or auto-derived from contribution)
  const threshold = useMemo(() => {
    if (settings.customThreshold !== undefined && settings.customThreshold > 0) {
      return settings.customThreshold;
    }
    // Auto-derive: use upcoming contribution amount, default to $50 minimum
    return upcomingContribution > 0 ? upcomingContribution : 50;
  }, [settings.customThreshold, upcomingContribution]);

  // Check if alert should show
  useEffect(() => {
    if (!settings.enabled) {
      setShowAlert(false);
      return;
    }

    const isLowBalance = balance < threshold;
    const isDueSoon = testMode || daysUntilContribution <= 7;

    // Check if recently dismissed (within last 24 hours)
    const oneDayAgo = Date.now() - 24 * 60 * 60 * 1000;
    const recentlyDismissed = settings.dismissedAlerts.some(
      (ts) => parseInt(ts) > oneDayAgo
    );

    if (isLowBalance && isDueSoon && !recentlyDismissed) {
      setShowAlert(true);
    } else {
      setShowAlert(false);
    }
  }, [balance, threshold, daysUntilContribution, settings.enabled, settings.dismissedAlerts, testMode]);

  const dismissAlert = useCallback(() => {
    const newDismissed = [...settings.dismissedAlerts, Date.now().toString()];
    const newSettings = { ...settings, dismissedAlerts: newDismissed };
    setSettings(newSettings);
    setShowAlert(false);
    localStorage.setItem(LOW_BALANCE_STORAGE_KEY, JSON.stringify(newSettings));
  }, [settings]);

  const toggleEnabled = useCallback((enabled: boolean) => {
    const newSettings = { ...settings, enabled };
    setSettings(newSettings);
    localStorage.setItem(LOW_BALANCE_STORAGE_KEY, JSON.stringify(newSettings));
  }, [settings]);

  const setCustomThreshold = useCallback((value: number | undefined) => {
    const newSettings = { ...settings, customThreshold: value };
    setSettings(newSettings);
    localStorage.setItem(LOW_BALANCE_STORAGE_KEY, JSON.stringify(newSettings));
  }, [settings]);

  return {
    showAlert,
    threshold,
    dismissAlert,
    isEnabled: settings.enabled,
    toggleEnabled,
    setCustomThreshold,
  };
}

/**
 * Low-balance alert banner component
 */
export function LowBalanceAlertBanner({
  balance,
  upcomingContribution = 50,
  daysUntilContribution = 7,
  onNavigateToDeposit,
  testMode = false,
}: LowBalanceAlertProps) {
  const {
    showAlert,
    threshold,
    dismissAlert,
  } = useLowBalanceAlert(balance, upcomingContribution, daysUntilContribution, testMode);

  if (!showAlert) return null;

  const deficit = threshold - balance;

  return (
    <div
      className="flex items-start gap-3 p-4 rounded-xl bg-amber-500/10 border border-amber-500/30 mb-6"
      role="alert"
    >
      <AlertTriangle
        size={20}
        className="text-amber-500 shrink-0 mt-0.5"
        aria-hidden="true"
      />
      <div className="flex-1 min-w-0">
        <p className="text-sm font-semibold text-amber-600 dark:text-amber-400">
          Low Balance Warning
        </p>
        <p className="text-xs text-[var(--muted)] mt-1">
          Your balance (${balance.toFixed(2)}) is below the recommended threshold (${threshold}).
          {upcomingContribution > 0 && (
            <>
              {" "}A contribution of ${upcomingContribution} is due in {daysUntilContribution} day
              {daysUntilContribution !== 1 ? "s" : ""}.
            </>
          )}
        </p>
        {deficit > 0 && onNavigateToDeposit && (
          <button
            onClick={onNavigateToDeposit}
            className="inline-flex items-center gap-1.5 mt-2 text-xs font-medium text-amber-600 dark:text-amber-400 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-amber-500"
          >
            <ExternalLink size={12} aria-hidden="true" />
            Top up now
          </button>
        )}
      </div>
      <button
        onClick={dismissAlert}
        className="p-1 text-[var(--muted)] hover:text-[var(--text)] rounded transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-amber-500"
        aria-label="Dismiss warning"
      >
        <X size={16} />
      </button>
    </div>
  );
}

/**
 * Settings component for low-balance alerts
 */
export function LowBalanceAlertSettings() {
  const [settings, setSettings] = useState<LowBalanceSettings>(DEFAULT_SETTINGS);
  const [customThreshold, setCustomThreshold] = useState<string>("");

  useEffect(() => {
    try {
      const stored = localStorage.getItem(LOW_BALANCE_STORAGE_KEY);
      if (stored) {
        const parsed = JSON.parse(stored);
        setSettings(parsed);
        if (parsed.customThreshold !== undefined) {
          setCustomThreshold(parsed.customThreshold.toString());
        }
      }
    } catch {
      // ignore
    }
  }, []);

  const handleToggle = (enabled: boolean) => {
    const newSettings = { ...settings, enabled };
    setSettings(newSettings);
    localStorage.setItem(LOW_BALANCE_STORAGE_KEY, JSON.stringify(newSettings));
  };

  const handleThresholdChange = (value: string) => {
    setCustomThreshold(value);
    const threshold = parseFloat(value);
    const newSettings = {
      ...settings,
      customThreshold: isNaN(threshold) || threshold <= 0 ? undefined : threshold,
    };
    setSettings(newSettings);
    localStorage.setItem(LOW_BALANCE_STORAGE_KEY, JSON.stringify(newSettings));
  };

  return (
    <div className="p-6 rounded-2xl bg-[var(--content)] border border-[var(--ov-10)] space-y-4">
      <h3 className="text-base font-bold font-sora text-[var(--text)] flex items-center gap-2">
        <Bell size={18} className="text-[#4B6B76]" aria-hidden="true" />
        <span>Low Balance Alerts</span>
      </h3>

      <p className="text-xs text-[var(--muted)] leading-relaxed">
        Get notified when your wallet balance is too low to cover an upcoming contribution,
        so you never miss a deadline and incur penalties.
      </p>

      {/* Enable Toggle */}
      <div className="flex items-center justify-between pt-2">
        <div className="flex items-center gap-2">
          {settings.enabled ? (
            <Bell size={16} className="text-[var(--muted)]" aria-hidden="true" />
          ) : (
            <BellOff size={16} className="text-[var(--muted)]" aria-hidden="true" />
          )}
          <span className="text-sm font-semibold text-[var(--text)]">
            Enable Alerts
          </span>
        </div>
        <button
          onClick={() => handleToggle(!settings.enabled)}
          role="switch"
          aria-checked={settings.enabled}
          className={`relative inline-flex h-6 w-11 shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76] ${
            settings.enabled ? "bg-[#4B6B76]" : "bg-[var(--ov-1a)]"
          }`}
        >
          <span
            className={`pointer-events-none inline-block h-5 w-5 transform rounded-full bg-white shadow-lg transition-transform ${
              settings.enabled ? "translate-x-5" : "translate-x-0"
            }`}
          />
        </button>
      </div>

      {/* Custom Threshold */}
      {settings.enabled && (
        <div className="pt-4 border-t border-[var(--ov-10)]">
          <label
            htmlFor="lowBalanceThreshold"
            className="block text-sm font-semibold text-[var(--text)] mb-2"
          >
            Custom threshold (optional)
          </label>
          <div className="flex items-center gap-2">
            <span className="text-sm text-[var(--muted)]">$</span>
            <input
              id="lowBalanceThreshold"
              type="number"
              min="0"
              step="1"
              value={customThreshold}
              onChange={(e) => handleThresholdChange(e.target.value)}
              placeholder="Auto-calculated"
              className="flex-1 h-10 px-3 rounded-xl bg-[var(--modal)] border border-[var(--ov-10)] text-sm text-[var(--text)] placeholder:text-[var(--faint)] focus:outline-none focus:ring-2 focus:ring-[#4B6B76] transition-colors"
            />
          </div>
          <p className="text-[11px] text-[var(--muted)] mt-1.5">
            Leave empty to automatically calculate from your upcoming contribution amount.
          </p>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { AlertTriangle, X } from "lucide-react";
import { publicEnv } from "@/lib/env";

/**
 * Issue #217 – Network Switcher Guard (Testnet vs Mainnet Mismatch)
 *
 * Detects whether the connected Freighter wallet's network passphrase
 * matches the app's configured network passphrase.  When there is a
 * mismatch a blocking modal is rendered and all transaction triggers
 * are disabled until the user switches networks.
 *
 * The hook `useNetworkGuard` is exported so any component that initiates
 * a transaction can check `networkMismatch` before proceeding.
 */

// The app's canonical network passphrase comes from the environment.
// Falls back to Stellar testnet so the guard works in development.
const APP_NETWORK_PASSPHRASE = publicEnv.stellarNetworkPassphrase;
const APP_NETWORK_LABEL = publicEnv.stellarNetworkLabel;

// ---------------------------------------------------------------------------
// Freighter browser-extension shim
// ---------------------------------------------------------------------------

interface FreighterAPI {
  getNetworkDetails?: () => Promise<{
    network: string;
    networkPassphrase: string;
    networkUrl: string;
  }>;
  isConnected?: () => Promise<boolean>;
}

function getFreighter(): FreighterAPI | null {
  if (typeof window === "undefined") return null;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  return (window as any).freighterApi ?? null;
}

// ---------------------------------------------------------------------------
// Hook
// ---------------------------------------------------------------------------

export interface NetworkGuardState {
  /** true while the first check hasn't resolved yet */
  loading: boolean;
  /** true when wallet network ≠ app network */
  networkMismatch: boolean;
  /** The passphrase the wallet is currently on */
  walletPassphrase: string | null;
  /** Re-run the check (useful after the user says they switched) */
  recheck: () => Promise<void>;
}

export function useNetworkGuard(): NetworkGuardState {
  const [loading, setLoading] = useState(true);
  const [walletPassphrase, setWalletPassphrase] = useState<string | null>(null);

  const check = async () => {
    setLoading(true);
    try {
      const freighter = getFreighter();
      if (!freighter?.getNetworkDetails) {
        // Extension not present – treat as no mismatch so we don't block non-Freighter users.
        setWalletPassphrase(APP_NETWORK_PASSPHRASE);
        return;
      }
      const connected = await freighter.isConnected?.();
      if (!connected) {
        setWalletPassphrase(APP_NETWORK_PASSPHRASE);
        return;
      }
      const details = await freighter.getNetworkDetails();
      setWalletPassphrase(details.networkPassphrase);
    } catch {
      setWalletPassphrase(APP_NETWORK_PASSPHRASE);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    check();
    // Re-check whenever the user might switch networks in the extension.
    window.addEventListener("freighter_network_changed", check);
    return () => window.removeEventListener("freighter_network_changed", check);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const networkMismatch =
    !loading &&
    walletPassphrase !== null &&
    walletPassphrase !== APP_NETWORK_PASSPHRASE;

  return { loading, networkMismatch, walletPassphrase, recheck: check };
}

// ---------------------------------------------------------------------------
// Blocking modal
// ---------------------------------------------------------------------------

interface NetworkMismatchModalProps {
  walletPassphrase: string;
  onRecheck: () => Promise<void>;
}

function passphraseToLabel(passphrase: string): string {
  if (passphrase.includes("Public Global Stellar Network")) return "Mainnet";
  if (passphrase.includes("Test SDF Network")) return "Testnet";
  return passphrase.slice(0, 30) + "…";
}

function NetworkMismatchModal({ walletPassphrase, onRecheck }: NetworkMismatchModalProps) {
  const [rechecking, setRechecking] = useState(false);

  const handleRecheck = async () => {
    setRechecking(true);
    await onRecheck();
    setRechecking(false);
  };

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-labelledby="network-mismatch-title"
      className="fixed inset-0 z-[200] flex items-center justify-center bg-black/70 backdrop-blur-sm p-4"
    >
      <div className="w-full max-w-md rounded-2xl border border-white/10 bg-[#161616] p-6 shadow-2xl">
        <div className="flex items-start gap-4">
          <div className="flex h-12 w-12 flex-shrink-0 items-center justify-center rounded-full bg-amber-500/15">
            <AlertTriangle size={24} className="text-amber-400" aria-hidden="true" />
          </div>
          <div className="flex-1 min-w-0">
            <h2
              id="network-mismatch-title"
              className="text-lg font-semibold text-white"
            >
              Wrong Network Detected
            </h2>
            <p className="mt-2 text-sm text-[#A1A1AA] leading-relaxed">
              Your Freighter wallet is connected to{" "}
              <span className="font-medium text-amber-300">
                {passphraseToLabel(walletPassphrase)}
              </span>
              , but this app requires{" "}
              <span className="font-medium text-white">{APP_NETWORK_LABEL}</span>.
              Transactions are disabled until you switch.
            </p>

            <div className="mt-4 rounded-xl bg-[#1E1E1E] border border-white/5 p-4 space-y-2 text-sm">
              <p className="text-[#A1A1AA] font-medium">How to switch networks in Freighter:</p>
              <ol className="list-decimal list-inside text-[#A1A1AA] space-y-1">
                <li>Open the Freighter extension.</li>
                <li>Click the network selector in the top-right corner.</li>
                <li>
                  Choose{" "}
                  <span className="text-white font-medium">{APP_NETWORK_LABEL}</span>.
                </li>
                <li>Return here and click &ldquo;I&apos;ve switched&rdquo; below.</li>
              </ol>
            </div>

            <div className="mt-5 flex gap-3">
              <button
                type="button"
                onClick={handleRecheck}
                disabled={rechecking}
                className="flex-1 rounded-xl bg-[#4B6B76] px-4 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-[#5a7f8c] disabled:opacity-50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#4B6B76]"
              >
                {rechecking ? "Checking…" : "I've switched"}
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Guard wrapper
// ---------------------------------------------------------------------------

/**
 * Wrap any subtree that should be blocked during a network mismatch.
 *
 * ```tsx
 * <NetworkGuard>
 *   <SendTransferModal />
 * </NetworkGuard>
 * ```
 */
export default function NetworkGuard({ children }: { children: React.ReactNode }) {
  const { loading, networkMismatch, walletPassphrase, recheck } = useNetworkGuard();

  if (loading) return <>{children}</>;

  return (
    <>
      {children}
      {networkMismatch && walletPassphrase && (
        <NetworkMismatchModal
          walletPassphrase={walletPassphrase}
          onRecheck={recheck}
        />
      )}
    </>
  );
}

"use client";

import { useRef, useState } from "react";
import { CheckCircle2, ChevronDown, Loader2, X, XCircle } from "lucide-react";
import { useFocusTrap } from "@/hooks/useFocusTrap";
import { truncateAddress } from "@/contexts/WalletContext";
import { getContacts, isValidAddressFormat } from "@/lib/addressBook";
import type { AddressBookContact } from "@/types/addressBook";
import { isKnownExchangeAddress, validateMemo, type MemoType } from "@/lib/sendTransfer";

interface SendTransferModalProps {
  open: boolean;
  onClose: () => void;
  fromAddress: string;
  onSent: (transfer: { recipient: string; amount: number; memo?: string; memoType: MemoType }) => void;
}

type Status = "idle" | "review" | "pending" | "success" | "error";

export default function SendTransferModal({ open, onClose, fromAddress, onSent }: SendTransferModalProps) {
  const dialogRef = useRef<HTMLDivElement>(null);
  const [contacts] = useState<AddressBookContact[]>(() => getContacts());
  const [showContacts, setShowContacts] = useState(false);
  const [recipient, setRecipient] = useState("");
  const [amount, setAmount] = useState("");
  const [memo, setMemo] = useState("");
  const [memoType, setMemoType] = useState<MemoType>("text");
  const [status, setStatus] = useState<Status>("idle");
  const [error, setError] = useState<string | null>(null);

  const close = () => {
    if (status === "pending") return;
    onClose();
  };

  useFocusTrap(dialogRef, open, close);

  if (!open) return null;

  function handleReview() {
    if (!isValidAddressFormat(recipient)) {
      setError("Enter a valid recipient address.");
      return;
    }
    const numericAmount = Number(amount);
    if (!numericAmount || numericAmount <= 0) {
      setError("Enter an amount greater than 0.");
      return;
    }
    const memoError = validateMemo(memo, memoType);
    if (memoError) {
      setError(memoError);
      return;
    }
    setError(null);
    setStatus("review");
  }

  async function handleSend() {
    setError(null);
    setStatus("pending");
    try {
      await new Promise((resolve) => setTimeout(resolve, 900));
      onSent({ recipient: recipient.trim(), amount: Number(amount), memo: memo || undefined, memoType });
      setStatus("success");
    } catch {
      setStatus("error");
    }
  }

  return (
    <div
      className="fixed inset-0 z-200 flex items-center justify-center bg-black/70 backdrop-blur-sm px-4"
      role="dialog"
      aria-modal="true"
      aria-labelledby="send-transfer-title"
      onClick={close}
    >
      <div
        ref={dialogRef}
        className="w-full max-w-md rounded-2xl bg-[var(--modal)] border border-[var(--ov-14)] p-6 shadow-xl font-sora"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between mb-5">
          <h2 id="send-transfer-title" className="text-lg font-semibold text-[var(--text)]">
            Send Funds
          </h2>
          {status !== "pending" && (
            <button onClick={close} aria-label="Close" className="text-[var(--muted)] hover:text-[var(--text)]">
              <X size={20} />
            </button>
          )}
        </div>

        {(status === "idle" || status === "pending") && (
          <div className="space-y-4">
            <div>
              <div className="flex items-center justify-between mb-1.5">
                <label htmlFor="send-recipient" className="block text-xs text-[var(--muted)]">
                  Recipient address
                </label>
                {contacts.length > 0 && (
                  <button
                    type="button"
                    onClick={() => setShowContacts((v) => !v)}
                    className="flex items-center gap-1 text-xs text-[#4B6B76] hover:underline"
                  >
                    Saved contacts <ChevronDown size={12} aria-hidden="true" />
                  </button>
                )}
              </div>
              {showContacts && (
                <div className="mb-2 max-h-40 overflow-y-auto rounded-xl border border-[var(--ov-14)] bg-[var(--ov-05)]">
                  {contacts.map((contact) => (
                    <button
                      key={contact.id}
                      type="button"
                      onClick={() => {
                        setRecipient(contact.address);
                        setShowContacts(false);
                      }}
                      className="w-full flex flex-col items-start px-3 py-2 text-left hover:bg-[var(--ov-0a)] transition-colors"
                    >
                      <span className="text-sm font-medium text-[var(--text)]">{contact.label}</span>
                      <span className="text-xs font-mono text-[var(--muted)]">
                        {truncateAddress(contact.address)}
                      </span>
                    </button>
                  ))}
                </div>
              )}
              <input
                id="send-recipient"
                type="text"
                value={recipient}
                onChange={(e) => setRecipient(e.target.value)}
                placeholder="0x…"
                disabled={status === "pending"}
                className="w-full bg-[var(--ov-0a)] border border-[var(--ov-14)] rounded-xl px-4 py-2.5 text-sm font-mono text-[var(--text)] placeholder:text-[var(--faint)] focus:outline-none focus:ring-2 focus:ring-[#4B6B76]"
              />
              {isKnownExchangeAddress(recipient, contacts) && !memo && (
                <p className="mt-1.5 text-xs text-amber-500" role="status">
                  This is a saved exchange address. A memo may be required to credit your deposit.
                </p>
              )}
            </div>

            <div>
              <label htmlFor="send-amount" className="block text-xs text-[var(--muted)] mb-1.5">
                Amount (USDT)
              </label>
              <input
                id="send-amount"
                type="number"
                min="0"
                step="0.01"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                disabled={status === "pending"}
                placeholder="0.00"
                className="w-full bg-[var(--ov-0a)] border border-[var(--ov-14)] rounded-xl px-4 py-2.5 text-sm text-[var(--text)] placeholder:text-[var(--faint)] focus:outline-none focus:ring-2 focus:ring-[#4B6B76]"
              />
            </div>

            <div>
              <div className="flex items-center justify-between mb-1.5">
                <label htmlFor="send-memo" className="block text-xs text-[var(--muted)]">
                  Memo <span className="text-[var(--faint)]">(optional)</span>
                </label>
                <label htmlFor="send-memo-type" className="sr-only">
                  Memo type
                </label>
                <select
                  id="send-memo-type"
                  value={memoType}
                  onChange={(e) => setMemoType(e.target.value as MemoType)}
                  disabled={status === "pending"}
                  className="rounded-lg border border-[var(--ov-14)] bg-[var(--ov-0a)] px-2 py-1 text-xs text-[var(--text)] focus:outline-none focus:ring-2 focus:ring-[#4B6B76]"
                >
                  <option value="text">Text</option>
                  <option value="id">ID</option>
                </select>
              </div>
              <input
                id="send-memo"
                type="text"
                value={memo}
                onChange={(e) => setMemo(e.target.value)}
                disabled={status === "pending"}
                maxLength={memoType === "text" ? 28 : 20}
                placeholder={memoType === "text" ? "Up to 28 bytes" : "Unsigned 64-bit number"}
                className="w-full bg-[var(--ov-0a)] border border-[var(--ov-14)] rounded-xl px-4 py-2.5 text-sm text-[var(--text)] placeholder:text-[var(--faint)] focus:outline-none focus:ring-2 focus:ring-[#4B6B76]"
              />
              {memoType === "text" && (
                <p className="mt-1 text-xs text-[var(--faint)]">Maximum 28 UTF-8 bytes.</p>
              )}
            </div>

            <p className="text-xs text-[var(--faint)]">
              From {truncateAddress(fromAddress)}
            </p>

            {error && <p className="text-xs text-red-500">{error}</p>}

            <div className="flex gap-3 pt-1">
              <button
                onClick={close}
                disabled={status === "pending"}
                className="flex-1 rounded-xl border border-[var(--ov-1a)] text-[var(--text)] py-2.5 font-medium hover:bg-[var(--ov-0a)] transition-colors disabled:opacity-50"
              >
                Cancel
              </button>
              <button
                onClick={handleReview}
                disabled={status === "pending"}
                className="flex-1 flex items-center justify-center gap-2 rounded-xl bg-[#4ADE80] text-[#0A0A0A] py-2.5 font-semibold hover:bg-[#3fc873] transition-colors disabled:opacity-70"
              >
                {status === "pending" ? (
                  <>
                    <Loader2 size={18} className="animate-spin" /> Sending...
                  </>
                ) : (
                  "Review transfer"
                )}
              </button>
            </div>
          </div>
        )}

        {status === "review" && (
          <div className="space-y-4">
            <h3 className="font-semibold text-[var(--text)]">Confirm transfer details</h3>
            <dl className="space-y-3 rounded-xl bg-[var(--ov-05)] p-4 text-sm">
              <div className="flex justify-between gap-4">
                <dt className="text-[var(--muted)]">Recipient</dt>
                <dd className="font-mono text-[var(--text)]">{truncateAddress(recipient.trim())}</dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-[var(--muted)]">Amount</dt>
                <dd className="font-medium text-[var(--text)]">{amount} USDT</dd>
              </div>
              <div className="flex justify-between gap-4">
                <dt className="text-[var(--muted)]">Memo</dt>
                <dd className="break-all text-right text-[var(--text)]">
                  {memo ? `${memo} (${memoType === "id" ? "ID" : "text"})` : "None"}
                </dd>
              </div>
            </dl>
            {isKnownExchangeAddress(recipient, contacts) && !memo && (
              <p className="text-xs text-amber-500" role="alert">
                You selected a saved exchange address without a memo. The exchange may not credit your deposit.
              </p>
            )}
            <div className="flex gap-3">
              <button
                onClick={() => setStatus("idle")}
                className="flex-1 rounded-xl border border-[var(--ov-1a)] text-[var(--text)] py-2.5 font-medium hover:bg-[var(--ov-0a)] transition-colors"
              >
                Back
              </button>
              <button
                onClick={handleSend}
                className="flex-1 rounded-xl bg-[#4ADE80] text-[#0A0A0A] py-2.5 font-semibold hover:bg-[#3fc873] transition-colors"
              >
                Confirm &amp; send
              </button>
            </div>
          </div>
        )}

        {status === "success" && (
          <div className="text-center py-2">
            <CheckCircle2 className="mx-auto mb-3 text-[var(--success)]" size={48} />
            <p className="font-medium text-[var(--text)] mb-1">Transfer sent</p>
            <p className="text-sm text-[var(--muted)] mb-6">
              {amount} USDT sent to {truncateAddress(recipient)}.
              {memo && <span className="block mt-2">Memo ({memoType}): {memo}</span>}
            </p>
            <button
              onClick={onClose}
              className="w-full rounded-xl bg-[#4ADE80] text-[#0A0A0A] py-2.5 font-semibold hover:bg-[#3fc873] transition-colors"
            >
              Done
            </button>
          </div>
        )}

        {status === "error" && (
          <div className="text-center py-2">
            <XCircle className="mx-auto mb-3 text-red-500" size={48} />
            <p className="font-medium text-[var(--text)] mb-1">Transfer failed</p>
            <p className="text-sm text-[var(--muted)] mb-6">Something went wrong. Please try again.</p>
            <div className="flex gap-3">
              <button
                onClick={onClose}
                className="flex-1 rounded-xl border border-[var(--ov-1a)] text-[var(--text)] py-2.5 font-medium hover:bg-[var(--ov-0a)] transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={handleSend}
                className="flex-1 rounded-xl bg-[#4ADE80] text-[#0A0A0A] py-2.5 font-semibold hover:bg-[#3fc873] transition-colors"
              >
                Retry
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

