  amount: string;
  completedAt: string;
}

export interface StoredCycleCircle extends DiscoverCircle {
  participants: StoredParticipant[];
  createdAt: string;
  roundHistory: StoredRoundHistoryRow[];
  nextPayoutRecipient?: string;
  nextPayoutDeadline?: Date | null;
  isOrganizer?: boolean;
  isCoOrganizer?: boolean;
  isMember?: boolean;
