export function getStoredCircles(): StoredCycleCircle[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = safeStorage.getItem(STORED_CIRCLES_STORAGE_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
}

export function saveStoredCircle(circle: StoredCycleCircle): void {
  const current = getStoredCircles().filter((c) => c.id !== circle.id);
  current.unshift(circle);
  try {
    safeStorage.setItem(STORED_CIRCLES_STORAGE_KEY, JSON.stringify(current));
    if (typeof window !== "undefined") {
      window.dispatchEvent(new CustomEvent(CIRCLE_RENEWAL_UPDATED_EVENT));
    }
  } catch {
    // Ignore storage errors
  }
}

export function getStoredCircle(id: string): StoredCycleCircle | null {
  const circles = getStoredCircles();
  return circles.find((c) => c.id === id) ?? null;
}

/**
 * Derives the next cycle name from an existing name.
 * e.g. "Family savings" -> "Family savings (Cycle 2)"
 * e.g. "Family savings (Cycle 2)" -> "Family savings (Cycle 3)"
 */
export function getNextCycleName(currentName: string): string {
  const cycleMatch = currentName.match(/\(Cycle (\d+)\)$/i);
  if (cycleMatch) {
    const nextNum = parseInt(cycleMatch[1], 10) + 1;
    return currentName.replace(/\(Cycle \d+\)$/i, `(Cycle ${nextNum})`);
  }
  return `${currentName} (Cycle 2)`;
}

export interface RenewCircleCycleParams {
  parentCircle: {
    id: string;
    name: string;
    creator: string;
    contribution: string;
    duration: string;
    category?: string;
    description?: string;
    isPrivate?: boolean;
    penaltyEnabled?: boolean;
    penaltyType?: "percentage" | "fixed";
    penaltyValue?: string;
    penalty?: { enabled: boolean; type: "percentage" | "fixed"; value: string };
    totalSlots?: number;
  };
  config: CircleRenewalConfig;
  currentWallet?: string;
}

/**
 * Creates a new cycle circle preserving settings and only including opted-in members.
 * Reuses circle duplicate / clone logic and the fair draw tool.
 */
export function renewCircleCycle({
  parentCircle,
  config,
  currentWallet,
}: RenewCircleCycleParams): {
  newCircle: StoredCycleCircle;
  draw: PayoutDraw | null;
} {
  // Collect all addresses that opted in
  const optedInAddresses = Object.entries(config.optIns)
    .filter(([_, status]) => status === "opted_in")
    .map(([address]) => address);

  if (optedInAddresses.length < 2) {
    throw new Error("At least 2 members must opt in to create a new cycle.");
  }

  const cycleName = config.nextCycleName || getNextCycleName(parentCircle.name);
  const newCircleId =
    typeof crypto !== "undefined" && crypto.randomUUID
      ? crypto.randomUUID()
      : `circle-cycle-${Date.now()}`;

  // Fair Draw Tool integration:
  // Redraw payout order for the new cycle using seeded shuffle or preserve previous order
  let finalPayoutOrder: string[] = [];
  let draw: PayoutDraw | null = null;

  if (config.redrawPayoutOrder) {
    const seed = generateSeed();
    finalPayoutOrder = seededShuffle(optedInAddresses, seed);
    draw = {
      circleId: newCircleId,
      order: finalPayoutOrder,
      seed,
      timestamp: new Date().toISOString(),
      locked: true,
    };
    savePayoutDraw(draw);
  } else {
    finalPayoutOrder = [...optedInAddresses];
    draw = {
      circleId: newCircleId,
      order: finalPayoutOrder,
      seed: "preserved-order",
      timestamp: new Date().toISOString(),
      locked: true,
    };
    savePayoutDraw(draw);
  }

  // Build participant slots based on payout order
  const participants: StoredParticipant[] = finalPayoutOrder.map((address, index) => {
    const isCreator = address.toLowerCase() === parentCircle.creator.toLowerCase();
    return {
      address,
      slot: index + 1,
      paid: false,
      role: isCreator ? "organizer" : "participant",
    };
  });

  const penaltyEnabled =
    parentCircle.penaltyEnabled ?? parentCircle.penalty?.enabled ?? false;
  const penaltyType =
    parentCircle.penaltyType ?? parentCircle.penalty?.type ?? "percentage";
  const penaltyValue =
    parentCircle.penaltyValue ?? parentCircle.penalty?.value ?? "10";

  const newCircle: StoredCycleCircle = {
    id: newCircleId,
    name: cycleName,
    creator: parentCircle.creator,
    members: optedInAddresses,
    totalSlots: optedInAddresses.length,
    contribution: parentCircle.contribution,
    duration: parentCircle.duration,
    category: (parentCircle.category as any) ?? "family",
    description: parentCircle.description ?? "",
    isPrivate: parentCircle.isPrivate ?? false,
    penaltyEnabled,
    penaltyType,
    penaltyValue,
    currentRound: 1,
    totalRounds: optedInAddresses.length,
    status: "active",
    participants,
    createdAt: new Date().toLocaleDateString("en-US", {
      month: "short",
      day: "numeric",
      year: "numeric",
    }),
    roundHistory: [],
    nextPayoutRecipient: finalPayoutOrder[0],
    nextPayoutDeadline: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
    isOrganizer: currentWallet
      ? parentCircle.creator.toLowerCase() === currentWallet.toLowerCase()
      : false,
    isCoOrganizer: false,
    isMember: currentWallet
      ? optedInAddresses.some((a) => a.toLowerCase() === currentWallet.toLowerCase())
      : false,
    parentCircleId: parentCircle.id,
  };

  // Persist the new circle
  saveStoredCircle(newCircle);

  // Update the renewal config with the new circle link
  const updatedConfig: CircleRenewalConfig = {
    ...config,
    renewedCircleId: newCircleId,
    renewedAt: new Date().toISOString(),
  };
  saveCircleRenewal(updatedConfig);

  return { newCircle, draw };
}

export type ContributionCreditEntryType = "payment" | "overpayment" | "applied" | "refund" | "reserve_contribution" | "reserve_coverage" | "reserve_distribution";

export interface ContributionCreditEntry {
  id: string;
  circleId: string;
  memberAddress: string;
  type: ContributionCreditEntryType;
  amount: number;
  round: number | null;
  paymentId?: string;
  /** For reserve entries: which member's missed payment was covered (reserve_coverage) or who received distribution (reserve_distribution) */
  relatedMember?: string;
}

export interface RecordContributionInput {
  circleId: string;
  memberAddress: string;
  round: number;
  requiredAmount: number;
  paidAmount: number;
  paymentId: string;
  /** Reserve percentage (0-100) to split from each contribution. */
  reservePercentage?: number;
  /** Current reserve balance available for coverage. */
  reserveBalance?: number;
  /** Whether this member is missing this round's contribution (reserve coverage). */
  isMissedPayment?: boolean;
  /** Address of the member whose missed payment is being covered (when isMissedPayment is true). */
  coveredMemberAddress?: string;
}

export interface RecordContributionResult {
  entries: ContributionCreditEntry[];
  creditApplied: number;
  amountDue: number;
  overpayment: number;
  remainingCredit: number;
  /** Amount contributed to reserve this payment. */
  reserveContributed: number;
  /** Amount used from reserve to cover a missed payment (if any). */
  reserveUsed: number;
  /** New reserve balance after this transaction. */
  newReserveBalance: number;
}

function roundAmount(amount: number): number {
  return Math.round((amount + Number.EPSILON) * 100) / 100;
}

function validateAmount(label: string, amount: number, allowZero = true): void {
  if (!Number.isFinite(amount) || amount < 0 || (!allowZero && amount === 0)) {
    throw new RangeError(`${label} must be a ${allowZero ? "non-negative" : "positive"} finite amount.`);
  }
}

export function getContributionCreditBalance(
  entries: ContributionCreditEntry[],
  circleId: string,
  memberAddress: string
): number {
  const address = memberAddress.toLowerCase();
  const balance = entries.reduce((sum, entry) => {
    if (entry.circleId !== circleId || entry.memberAddress.toLowerCase() !== address) return sum;
    if (entry.type === "overpayment") return sum + entry.amount;
    if (entry.type === "applied" || entry.type === "refund") return sum - entry.amount;
    return sum;
  }, 0);
  return roundAmount(balance);
}

/** Returns the total reserve balance for a circle from the ledger. */
export function getReserveBalance(
  entries: ContributionCreditEntry[],
  circleId: string
): number {
  const balance = entries
    .filter((entry) => entry.circleId === circleId)
    .reduce((sum, entry) => {
      if (entry.type === "reserve_contribution") return sum + entry.amount;
      if (entry.type === "reserve_coverage") return sum - entry.amount;
      return sum;
    }, 0);
  return roundAmount(balance);
}

/** Returns the total reserve contributed by a specific member. */
export function getMemberReserveContributed(
  entries: ContributionCreditEntry[],
  circleId: string,
  memberAddress: string
): number {
  const address = memberAddress.toLowerCase();
  const balance = entries
    .filter(
      (entry) =>
        entry.circleId === circleId &&
        entry.memberAddress.toLowerCase() === address &&
        entry.type === "reserve_contribution"
    )
    .reduce((sum, entry) => sum + entry.amount, 0);
  return roundAmount(balance);
}

/** Returns the amount the member needs to pay after automatically applying credit. */
export function getContributionAmountDue(
  entries: ContributionCreditEntry[],
  circleId: string,
  memberAddress: string,
  requiredAmount: number
): number {
  validateAmount("Required contribution", requiredAmount, false);
  const creditApplied = Math.max(
    0,
    Math.min(getContributionCreditBalance(entries, circleId, memberAddress), requiredAmount)
  );
  return roundAmount(requiredAmount - creditApplied);
}

export function recordContributionPayment(
  entries: ContributionCreditEntry[],
  input: RecordContributionInput
): RecordContributionResult {
  const {
    circleId,
    memberAddress,
    round,
    requiredAmount,
    paidAmount,
    paymentId,
    reservePercentage = 0,
    reserveBalance = 0,
    isMissedPayment = false,
    coveredMemberAddress,
  } = input;
  validateAmount("Required contribution", requiredAmount, false);
  validateAmount("Payment", paidAmount);
  const normalizedRequiredAmount = roundAmount(requiredAmount);
  const normalizedPaidAmount = roundAmount(paidAmount);
  if (!circleId || !memberAddress || !paymentId || !Number.isInteger(round) || round < 1) {
    throw new Error("Circle, member, payment ID, and a positive round are required.");
  }
  if (entries.some((entry) => entry.paymentId === paymentId)) {
    throw new Error("This payment has already been recorded.");
  }

  const address = memberAddress.toLowerCase();
  if (entries.some(
    (entry) =>
      entry.type === "payment" &&
      entry.circleId === circleId &&
      entry.memberAddress.toLowerCase() === address &&
      entry.round === round
  )) {
    throw new Error("A contribution for this member and round has already been recorded.");
  }

  const balance = getContributionCreditBalance(entries, circleId, memberAddress);
  const creditApplied = roundAmount(Math.max(0, Math.min(balance, normalizedRequiredAmount)));
  const amountDue = roundAmount(normalizedRequiredAmount - creditApplied);
  if (normalizedPaidAmount < amountDue) {
    throw new RangeError(`Payment is below the amount due (${amountDue}).`);
  }

  const overpayment = roundAmount(normalizedPaidAmount - amountDue);
  const nextEntries = [...entries];

  // --- Reserve coverage for missed payments ---
  // When a member misses a payment, the organizer can use the reserve to
  // cover the shortfall so the payout still goes out on time.
  let reserveUsed = 0;
  let newReserveBalance = getReserveBalance(entries, circleId);

  if (isMissedPayment && coveredMemberAddress) {
    const coveredAddress = coveredMemberAddress.toLowerCase();
    // Check that the caller is authorized (organizer/co-organizer) - handled by caller
    const availableReserve = newReserveBalance;
    const shortfall = normalizedRequiredAmount; // full amount needed to keep payout on time
    reserveUsed = roundAmount(Math.min(availableReserve, shortfall));
    if (reserveUsed > 0) {
      nextEntries.push({
        id: `${paymentId}:reserve-coverage`,
        circleId,
        memberAddress: address,
        type: "reserve_coverage",
        amount: reserveUsed,
        round,
        paymentId,
        relatedMember: coveredAddress,
      });
      newReserveBalance = roundAmount(newReserveBalance - reserveUsed);
    }
  }

  // --- Reserve contribution from this payment ---
  // A small percentage of the actual contribution goes into the reserve.
  let reserveContributed = 0;
  if (reservePercentage > 0 && !isMissedPayment) {
    // Reserve is taken from the actual paid amount (after credit applied)
    const baseForReserve = normalizedPaidAmount;
    reserveContributed = roundAmount(baseForReserve * (reservePercentage / 100));
    if (reserveContributed > 0) {
      nextEntries.push({
        id: `${paymentId}:reserve`,
        circleId,
        memberAddress: address,
        type: "reserve_contribution",
        amount: reserveContributed,
        round,
        paymentId,
      });
      newReserveBalance = roundAmount(newReserveBalance + reserveContributed);
    }
  }

  // --- Standard contribution entries ---
  if (creditApplied > 0) {
    nextEntries.push({
      id: `${paymentId}:applied`,
      circleId,
      memberAddress,
      type: "applied",
      amount: creditApplied,
      round,
      paymentId,
    });
  }
  nextEntries.push({
    id: `${paymentId}:payment`,
    circleId,
    memberAddress,
    type: "payment",
    amount: normalizedPaidAmount,
    round,
    paymentId,
  });
  if (overpayment > 0) {
    nextEntries.push({
      id: `${paymentId}:credit`,
      circleId,
      memberAddress,
      type: "overpayment",
      amount: overpayment,
      round,
      paymentId,
    });
  }

  return {
    entries: nextEntries,
    creditApplied,
    amountDue,
    overpayment,
    remainingCredit: getContributionCreditBalance(nextEntries, circleId, memberAddress),
    reserveContributed,
    reserveUsed,
    newReserveBalance,
  };
}

/** Records one refund for each member's positive credit balance. Safe to rerun. */
export function refundRemainingContributionCredits(
  entries: ContributionCreditEntry[],
  circleId: string
): { entries: ContributionCreditEntry[]; refunds: ContributionCreditEntry[] } {
  const addresses = new Set(
    entries
      .filter((entry) => entry.circleId === circleId)
      .map((entry) => entry.memberAddress.toLowerCase())
  );
  const nextEntries = [...entries];
  const refunds: ContributionCreditEntry[] = [];

  for (const memberAddress of addresses) {
    const balance = getContributionCreditBalance(nextEntries, circleId, memberAddress);
    if (balance <= 0) continue;

    const refundNumber = nextEntries.filter(
      (entry) =>
        entry.circleId === circleId &&
        entry.memberAddress.toLowerCase() === memberAddress &&
        entry.type === "refund"
    ).length + 1;
    const refund: ContributionCreditEntry = {
      id: `refund:${circleId}:${memberAddress}:${refundNumber}`,
      circleId,
      memberAddress,
      type: "refund",
      amount: balance,
      round: null,
    };
    nextEntries.push(refund);
    refunds.push(refund);
  }

  return { entries: nextEntries, refunds };
}

/**
 * Distributes leftover reserve back to members at the end of a circle.
 * Each member receives a share proportional to their total reserve contributions.
 * Safe to rerun — checks for existing distributions.
 */
export function distributeReserveBalance(
  entries: ContributionCreditEntry[],
  circleId: string,
  memberAddresses: string[]
): { entries: ContributionCreditEntry[]; distributions: ContributionCreditEntry[] } {
  const nextEntries = [...entries];
  const distributions: ContributionCreditEntry[] = [];
  const currentReserve = getReserveBalance(nextEntries, circleId);

  if (currentReserve <= 0) return { entries: nextEntries, distributions };

  // Calculate total reserve contributions across all members
  const contributions: Record<string, number> = {};
  let totalContributed = 0;
  for (const address of memberAddresses) {
    const normalized = address.toLowerCase();
    const amount = getMemberReserveContributed(nextEntries, circleId, normalized);
    contributions[normalized] = amount;
    totalContributed += amount;
  }

  if (totalContributed <= 0) return { entries: nextEntries, distributions };

  // Distribute proportionally, handling rounding by giving the remainder to the first member
  let distributed = 0;
  const memberList = memberAddresses.map((a) => a.toLowerCase());

  for (let i = 0; i < memberList.length; i++) {
    const address = memberList[i];
    const share = contributions[address];
    if (share <= 0) continue;

    let payout = roundAmount((currentReserve * share) / totalContributed);
    // Last member gets any rounding remainder
    if (i === memberList.length - 1) {
      payout = roundAmount(currentReserve - distributed);
    }
    if (payout <= 0) continue;

    // Check if already distributed
    const existing = nextEntries.some(
      (entry) =>
        entry.circleId === circleId &&
        entry.memberAddress.toLowerCase() === address &&
        entry.type === "reserve_distribution" &&
        entry.round === null
    );
    if (existing) continue;

    const distNumber = nextEntries.filter(
      (entry) =>
        entry.circleId === circleId &&
        entry.type === "reserve_distribution"
    ).length + 1;

    const distribution: ContributionCreditEntry = {
      id: `reserve-distribution:${circleId}:${address}:${distNumber}`,
      circleId,
      memberAddress: address,
      type: "reserve_distribution",
      amount: payout,
      round: null,
    };
    nextEntries.push(distribution);
    distributions.push(distribution);
    distributed = roundAmount(distributed + payout);
  }

  return { entries: nextEntries, distributions };
}

import { safeStorage } from "@/lib/safeStorage";
/**
 * Email verification for new signups.
 *
 * There's no auth/email backend yet, so verification is modeled client-side:
 * "sending" an email mints a time-limited mock token and stores it, and
 * "clicking the link" is simulated by visiting /verify-email?token=...
 * Swap sendVerificationEmail's internals for a real API call once one exists.
 */
import { isProduction } from "@/lib/env";

const STORAGE_KEY = "ahjoor:email-verification";

// Same-tab components need a signal when localStorage changes — the native
// "storage" event only fires in *other* tabs, so we dispatch this ourselves.
export const EMAIL_VERIFICATION_EVENT = "ahjoor:email-verification-changed";

const TOKEN_TTL_MS = 30 * 60 * 1000; // 30 minutes
const RESEND_COOLDOWN_MS = 60 * 1000; // 60 seconds between resends
const MAX_RESENDS_PER_WINDOW = 3;
const RESEND_WINDOW_MS = 15 * 60 * 1000; // 15 minutes

export interface EmailVerificationState {
  email: string | null;
  verified: boolean;
  pendingToken: string | null;
  tokenExpiresAt: number | null; // epoch ms
  lastSentAt: number | null; // epoch ms
  resendTimestamps: number[]; // epoch ms, recent attempts for rate limiting
}

const DEFAULT_STATE: EmailVerificationState = {
  email: null,
  verified: false,
  pendingToken: null,
  tokenExpiresAt: null,
  lastSentAt: null,
  resendTimestamps: [],
};

export function getEmailVerificationState(): EmailVerificationState {
  if (typeof window === "undefined") return DEFAULT_STATE;
  try {
    const raw = safeStorage.getItem(STORAGE_KEY);
    if (!raw) return DEFAULT_STATE;
    return { ...DEFAULT_STATE, ...JSON.parse(raw) };
  } catch {
    return DEFAULT_STATE;
  }
}

function saveState(state: EmailVerificationState) {
  try {
    safeStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    window.dispatchEvent(new Event(EMAIL_VERIFICATION_EVENT));
  } catch {
    // ignore storage errors
  }
}

function generateToken(): string {
  return typeof crypto !== "undefined" && crypto.randomUUID
    ? crypto.randomUUID().replace(/-/g, "")
    : Math.random().toString(36).slice(2) + Date.now().toString(36);
}

export interface SendResult {
  ok: boolean;
  reason?: "rate-limited";
  retryAfterMs?: number;
}

/**
 * Registers the email and "sends" the verification email (mints a
 * time-limited token). Used for both the initial signup email and the
 * resend action, so one rate limit covers both entry points.
 */
export function sendVerificationEmail(email: string): SendResult {
  const state = getEmailVerificationState();
  const now = Date.now();

  if (state.lastSentAt && now - state.lastSentAt < RESEND_COOLDOWN_MS) {
    return { ok: false, reason: "rate-limited", retryAfterMs: RESEND_COOLDOWN_MS - (now - state.lastSentAt) };
  }

  const recentAttempts = state.resendTimestamps.filter((ts) => now - ts < RESEND_WINDOW_MS);
  if (recentAttempts.length >= MAX_RESENDS_PER_WINDOW) {
    const oldest = Math.min(...recentAttempts);
    return { ok: false, reason: "rate-limited", retryAfterMs: RESEND_WINDOW_MS - (now - oldest) };
  }

  const token = generateToken();
  saveState({
    ...state,
    email,
    verified: email === state.email ? state.verified : false,
    pendingToken: token,
    tokenExpiresAt: now + TOKEN_TTL_MS,
    lastSentAt: now,
    resendTimestamps: [...recentAttempts, now],
  });

  // Dev/demo helper: with no mail server, log the "email" link so reviewers
  // can grab it. Remove once a real send exists.
  if (typeof window !== "undefined") {
    // eslint-disable-next-line no-console
    console.info(`[dev] Verification link: /verify-email?token=${token}`);
  }

  return { ok: true };
}

export type VerifyResult = "success" | "expired" | "invalid";

export function verifyEmailToken(token: string): VerifyResult {
  const state = getEmailVerificationState();

  if (!state.pendingToken || state.pendingToken !== token) return "invalid";
  if (state.tokenExpiresAt && Date.now() > state.tokenExpiresAt) return "expired";

  saveState({ ...state, verified: true, pendingToken: null, tokenExpiresAt: null });
  return "success";
}

export function getResendCooldownMs(): number {
  const state = getEmailVerificationState();
  if (!state.lastSentAt) return 0;
  return Math.max(RESEND_COOLDOWN_MS - (Date.now() - state.lastSentAt), 0);
}

/** Dev-only: exposes the link that would otherwise be emailed, for local
 * testing without a mail server. Never surfaced in production. */
export function getDevVerificationLink(): string | null {
  if (isProduction) return null;
  const state = getEmailVerificationState();
  return state.pendingToken ? `/verify-email?token=${state.pendingToken}` : null;
}

let StrKeySdk: any = null;
try {
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const sdk = require("@stellar/stellar-sdk");
  StrKeySdk = sdk?.StrKey || sdk;
} catch {
  // Fall back to Stellar Base32 specification when SDK is unavailable
}

export const INVALID_STELLAR_ADDRESS_MESSAGE = "Enter a valid Stellar address (starts with G or M).";

/**
 * Validate a Stellar address.
 *
 * By default only Ed25519 public keys (G...) are accepted. Pass
 * `{ allowMuxed: true }` to also accept muxed accounts (M...).
 */
export function isValidStellarAddress(
  address: string | null | undefined,
  options: { allowMuxed?: boolean } = {}
): boolean {
  if (!address) return false;
  const trimmed = address.trim();
  if (!trimmed) return false;

  try {
    if (StrKeySdk) {
      if (StrKeySdk.isValidEd25519PublicKey(trimmed)) return true;
      if (options.allowMuxed && StrKeySdk.isValidMed25519PublicKey(trimmed)) return true;
      return false;
    }
  } catch {
    // fallback
  }

  // Fallback Stellar address validation according to Stellar SEP-0023 / StrKey spec:
  // - Ed25519 Public Key: 56 chars, begins with 'G', RFC 4648 Base32 alphabet (A-Z, 2-7)
  // - Med25519 Muxed Account: 69 chars, begins with 'M', RFC 4648 Base32 alphabet (A-Z, 2-7)
  if (/^G[A-Z2-7]{55}$/.test(trimmed)) return true;
  if (options.allowMuxed && /^M[A-Z2-7]{68}$/.test(trimmed)) return true;
  return false;
}
